// macOS ships lsof in /usr/sbin while Ubuntu packages it in /usr/bin. The
// installed sidecar has a deliberately small PATH, so relying on only PATH or
// hard-coding either platform's location makes the other platform report every
// listener as stopped. Keep argv direct (no shell) and choose only known files,
// falling back to PATH for other Unix layouts.
const LSOF_EXECUTABLE = ['/usr/sbin/lsof', '/usr/bin/lsof'].find(candidate => existsSync(candidate)) ?? 'lsof';
const worktreePortDiscovery = createWorktreePortDiscovery({ executable: LSOF_EXECUTABLE });
const IS_BUNDLED_API_SIDECAR = process.env.PORTMGR_BUNDLED_SIDECAR === '1';
// Source development intentionally opens the local Codex task surface for
// product testing. Packaged sidecars and Windows remain fail-closed regardless
// of inherited environment values. The flag is removed before any child CLI
// can inherit it.
const AGENT_RUNTIME_LOCAL_DEVELOPMENT_TEST_MODE = (
  !IS_BUNDLED_API_SIDECAR
  && !IS_WIN
  && process.env.AGENTSTOZ_LOCAL_RUNTIME_TEST_MODE === '1'
);
const ORCHESTRATION_MISSION_TEST_KEY_HEX = process.env.NODE_ENV === 'test'
  ? process.env.PORTMGR_ORCHESTRATION_MISSION_TEST_KEY
  : undefined;
const EMBEDDED_PARENT_PID = Number(process.env.PORTMGR_PARENT_PID);
const WHAT_I_SAID_MANAGEMENT_CAPABILITY = /^[0-9a-f]{64}$/.test(process.env.PORTMGR_WHAT_I_SAID_CAPABILITY ?? '')
  ? process.env.PORTMGR_WHAT_I_SAID_CAPABILITY!
  : null;
const REMOTE_CONTROL_MANAGEMENT_CAPABILITY = /^[0-9a-f]{64}$/.test(process.env.PORTMGR_REMOTE_CONTROL_CAPABILITY ?? '')
  ? process.env.PORTMGR_REMOTE_CONTROL_CAPABILITY!
  : null;
const ONBOARDING_MANAGEMENT_CAPABILITY = /^[0-9a-f]{64}$/.test(process.env.PORTMGR_ONBOARDING_CAPABILITY ?? '') ? process.env.PORTMGR_ONBOARDING_CAPABILITY! : null;
const AGENT_RUNTIME_MANAGEMENT_CAPABILITY = /^[0-9a-f]{64}$/.test(process.env.PORTMGR_AGENT_RUNTIME_CAPABILITY ?? '')
  ? process.env.PORTMGR_AGENT_RUNTIME_CAPABILITY!
  : null;
// This secret authenticates only the Tauri -> sidecar management proxy. Keep
// it in this process constant, then remove it before any registered project,
// CLI, build, or helper process can inherit the sidecar environment.
delete process.env.PORTMGR_WHAT_I_SAID_CAPABILITY;
delete process.env.PORTMGR_REMOTE_CONTROL_CAPABILITY;
delete process.env.PORTMGR_AGENT_RUNTIME_CAPABILITY;
delete process.env.PORTMGR_ONBOARDING_CAPABILITY;
delete process.env.AGENTSTOZ_LOCAL_RUNTIME_TEST_MODE;
delete process.env.PORTMGR_ORCHESTRATION_MISSION_TEST_KEY;
// 디버그 로그 게이트: NODE_ENV 체크는 실사용 환경에서 사실상 항상 열려 있어,
// 10초 폴링류(per-poll) 로그가 자기 자신의 포트 로그 파일로 흘러들어
// 로그가 quadratic하게 자라는 문제가 있었음. DEBUG_PORTMGR=1일 때만 출력.
// 시작/에러 로그는 console.log / console.error를 직접 사용 (devLog 사용 금지).
const DEBUG = process.env.DEBUG_PORTMGR === '1';
// eslint-disable-next-line @typescript-eslint/no-explicit-any
const devLog = (...args: any[]) => { if (DEBUG) console.log(...args); };

const AGENTSTOZ_APP_NAME = 'AgentsToZ_byCS.app';
const AGENTSTOZ_APP_EXECUTABLE_SUFFIX = `/${AGENTSTOZ_APP_NAME}/Contents/MacOS/app`;

interface StagedMacosAppInstall {
  sourcePath: string;
  destinationPath: string;
  stagedPath: string;
  backupPath: string;
  logPath: string;
}

// Runs outside the app/sidecar process because installing an app that invoked this
// endpoint must be able to finish after that app exits. Paths and PIDs are passed as
// positional arguments, not interpolated into the shell program.
const MACOS_APP_INSTALL_HELPER = String.raw`
destination_path=$1
staged_path=$2
backup_path=$3
log_path=$4
shift 4

exec >>"$log_path" 2>&1
echo "[$(/bin/date '+%Y-%m-%d %H:%M:%S')] AgentsToZ install helper started"

# Let the HTTP/Tauri caller receive the scheduled result before its app exits.
/bin/sleep 1
/usr/bin/osascript -e 'tell application id "com.intenet.agentstozbycs" to quit' >/dev/null 2>&1 || true
/bin/sleep 1

is_agentstoz_pid() {
  running_command=$(/bin/ps -p "$1" -o command= 2>/dev/null || true)
  case "$running_command" in
    */AgentsToZ_byCS.app/Contents/MacOS/app) return 0 ;;
    *) return 1 ;;
  esac
}

for app_pid in "$@"; do
  if is_agentstoz_pid "$app_pid"; then
    /bin/kill -TERM "$app_pid" 2>/dev/null || true
  fi
done

wait_round=0
while [ "$wait_round" -lt 50 ]; do
  still_running=0
  for app_pid in "$@"; do
    if is_agentstoz_pid "$app_pid"; then
      still_running=1
      break
    fi
  done
  [ "$still_running" -eq 0 ] && break
  wait_round=$((wait_round + 1))
  /bin/sleep 0.2
done

if [ "$still_running" -ne 0 ]; then
  echo "Install aborted: an AgentsToZ app process did not exit. Existing app was not changed."
  exit 20
fi

had_destination=0
if [ -e "$destination_path" ]; then
  if ! /bin/mv "$destination_path" "$backup_path"; then
    echo "Install aborted: could not move existing app to backup."
    exit 30
  fi
  had_destination=1
fi

if /bin/mv "$staged_path" "$destination_path"; then
  echo "Install complete. Previous app backup: $backup_path"
  /usr/bin/open -n "$destination_path" || true
  exit 0
fi

echo "Install failed while activating staged app; attempting rollback."
if [ "$had_destination" -eq 1 ] && [ -e "$backup_path" ] && [ ! -e "$destination_path" ]; then
  if /bin/mv "$backup_path" "$destination_path"; then
    echo "Rollback complete."
  else
    echo "Rollback failed. Backup remains at: $backup_path"
  fi
fi
exit 40
`;

async function commandOutput(command: string[]): Promise<{ exitCode: number; output: string }> {
  const child = spawn({ cmd: command, stdout: 'pipe', stderr: 'pipe' });
  const stdout = new Response(child.stdout).text();
  const stderr = new Response(child.stderr).text();
  const exitCode = await child.exited;
  return { exitCode, output: `${await stdout}${await stderr}`.trim() };
}

async function runningAgentsTozAppPids(): Promise<number[]> {
  const result = await commandOutput(['/bin/ps', '-axo', 'pid=,command=']);
  if (result.exitCode !== 0) return [];
  const pids = new Set<number>();
  for (const line of result.output.split(/\r?\n/)) {
    const match = line.match(/^\s*(\d+)\s+(.+)$/);
    const pidText = match?.[1];
    const command = match?.[2];
    if (!pidText || !command?.trimEnd().endsWith(AGENTSTOZ_APP_EXECUTABLE_SUFFIX)) continue;
    const pid = Number(pidText);
    if (Number.isInteger(pid) && pid > 1) pids.add(pid);
  }
  return [...pids];
}

async function stageMacosAppInstall(): Promise<StagedMacosAppInstall> {
  const sourcePath = join(homedir(), 'cargo-targets', 'portmanager', 'release', 'bundle', 'macos', AGENTSTOZ_APP_NAME);
  const destinationPath = join('/Applications', AGENTSTOZ_APP_NAME);
  if (!existsSync(sourcePath) || !statSync(sourcePath).isDirectory()) {
    throw new Error(`빌드된 앱을 찾을 수 없습니다: ${sourcePath}`);
  }

  const token = `${Date.now()}-${process.pid}`;
  const stagedPath = join('/Applications', `.AgentsToZ_byCS-installing-${token}.app`);
  const backupDir = join('/Applications', '.AgentsToZ_byCS-backups');
  const backupPath = join(backupDir, `AgentsToZ_byCS-${token}.app`);
  const logDir = join(homedir(), 'Library', 'Logs', 'AgentsToZ_byCS');
  const logPath = join(logDir, `install-${token}.log`);
  mkdirSync(backupDir, { recursive: true });
  mkdirSync(logDir, { recursive: true });

  if (existsSync(stagedPath) || existsSync(backupPath)) {
    throw new Error('설치 임시 경로가 이미 존재합니다. 잠시 후 다시 시도하세요.');
  }

  const copied = await commandOutput(['/usr/bin/ditto', sourcePath, stagedPath]);
  if (copied.exitCode !== 0) {
    rmSync(stagedPath, { recursive: true, force: true });
    throw new Error(`새 앱을 설치 준비 경로에 복사하지 못했습니다: ${copied.output || `exit ${copied.exitCode}`}`);
  }

  const stagedExecutable = join(stagedPath, 'Contents', 'MacOS', 'app');
  if (!existsSync(stagedExecutable)) {
    rmSync(stagedPath, { recursive: true, force: true });
    throw new Error('설치 준비된 앱에 실행 파일이 없습니다. 기존 앱은 변경하지 않았습니다.');
  }

  const verified = await commandOutput(['/usr/bin/codesign', '--verify', '--deep', '--strict', stagedPath]);
  if (verified.exitCode !== 0) {
    rmSync(stagedPath, { recursive: true, force: true });
    throw new Error(`설치 준비된 앱의 서명 검증에 실패했습니다: ${verified.output || `exit ${verified.exitCode}`}`);
  }

  return { sourcePath, destinationPath, stagedPath, backupPath, logPath };
}

async function scheduleMacosAppInstall(plan: StagedMacosAppInstall): Promise<number[]> {
  const appPids = await runningAgentsTozAppPids();
  try {
    const helper = spawn({
      cmd: [
        '/bin/sh',
        '-c',
        MACOS_APP_INSTALL_HELPER,
        'agentstoz-install-helper',
        plan.destinationPath,
        plan.stagedPath,
        plan.backupPath,
        plan.logPath,
        ...appPids.map(String),
      ],
      stdin: 'ignore',
      stdout: 'ignore',
      stderr: 'ignore',
      detached: true,
    });
    helper.unref();
    return appPids;
  } catch (error) {
    rmSync(plan.stagedPath, { recursive: true, force: true });
    throw error;
  }
}

/** Git 바이너리 절대경로 — Tauri sandbox·다른 머신 호환성을 위해 PATH 대신 절대경로 사용 */
function resolveGitPath(): string {
  if (IS_WIN) {
    for (const p of ['C:/Program Files/Git/cmd/git.exe', 'C:/Program Files/Git/bin/git.exe', 'C:/Program Files (x86)/Git/cmd/git.exe']) {
      if (existsSync(p)) return p;
    }
    const r = Bun.spawnSync(['where', 'git'], { stdout: 'pipe', stderr: 'pipe' });
    const p = r.stdout.toString().trim().split(/\r?\n/)[0]?.trim();
    if (p) return p;
    return 'git';
  }
  if (existsSync('/usr/bin/git')) return '/usr/bin/git';
  if (existsSync('/opt/homebrew/bin/git')) return '/opt/homebrew/bin/git';
  if (existsSync('/usr/local/bin/git')) return '/usr/local/bin/git';
  return 'git';
}
const GIT_PATH = resolveGitPath();

/**
 * clone 은 네트워크 작업이라 끝을 보장할 수 없다. 무한정 매달려 있으면 사용자는 앱이
 * 죽은 것으로 읽는다. 큰 저장소도 통과할 만큼 넉넉하되 유한하게 둔다.
 */
const CLONE_TIMEOUT_MS = 10 * 60 * 1000;

/**
 * git 의 stderr 를 그대로 보여주면 원인이 묻힌다. 가장 흔한 두 실패는 **없는 저장소**와
 * **인증**인데, private 저장소는 GitHub 이 존재 자체를 숨기므로 둘이 같은 메시지로 온다.
 * 그 사실을 감추지 않고 두 가능성을 함께 말한다.
 */
function describeCloneFailure(stderr: string): string {
  const text = stderr.trim();
  if (/could not read (Username|Password)|terminal prompts disabled|Authentication failed|Permission denied \(publickey\)/i.test(text)) {
    return `저장소에 접근하지 못했습니다. private 저장소라면 이 PC의 git 인증(SSH 키 또는 gh 로그인)을 먼저 설정하세요.\n${text}`;
  }
  if (/(repository .* not found|Could not resolve host|does not exist)/i.test(text)) {
    return `저장소를 찾지 못했습니다. 주소가 맞는지, private 저장소라면 접근 권한이 있는지 확인하세요.\n${text}`;
  }
  return text || "git clone 실패";
}

/**
 * Stage everything except volatile artifacts (playwright logs, .env, .DS_Store, memory backups).
 * `git add -A -- . <exclude pathspecs>` fails outright (non-zero exit, nothing staged) whenever
 * one of the excluded paths is *also* gitignored — git raises "paths ignored by .gitignore" and
 * refuses before staging anything, regardless of the exclude magic. Staging in two plain steps
 * (add everything, then unstage the volatile paths) sidesteps that git quirk.
 */
async function stageAllExceptVolatileArtifacts(cwd: string): Promise<{ exitCode: number; output: string }> {
  const add = Bun.spawn([GIT_PATH, "add", "-A", "--", "."], { cwd, stdout: "pipe", stderr: "pipe" });
  await add.exited;
  if (add.exitCode !== 0) {
    const output = `${await new Response(add.stdout).text()}${await new Response(add.stderr).text()}`.trim();
    return { exitCode: add.exitCode ?? 1, output };
  }
  const unstage = Bun.spawn(
    [GIT_PATH, "reset", "--quiet", "--", ...GIT_VOLATILE_ARTIFACT_PATHS],
    { cwd, stdout: "pipe", stderr: "pipe" },
  );
  await unstage.exited;
  const output = `${await new Response(unstage.stdout).text()}${await new Response(unstage.stderr).text()}`.trim();
  return { exitCode: unstage.exitCode ?? 0, output };
}

/**
 * 링크된 워크트리에는 **커밋된 파일만** 실체화된다 — .gitignore된 로컬 설정은 따라오지 않는다.
 * 그래서 Codex는 `.codex/hooks.json`이 추적 파일이라 워크트리에서도 멀쩡한데, Claude는
 * `.claude/`가 gitignore라 활동 훅(settings.json)·권한 허용목록(settings.local.json)·
 * 스킬(/remember-session)이 통째로 빠진 반쪽 상태로 뜬다. `.env`도 마찬가지로 빠진다.
 *
 * node_modules를 자동 설치해주는 것과 같은 취지로 메인의 로컬 설정을 워크트리에 심어
 * 두 에이전트의 동작을 맞춘다. 이미 있는 파일은 덮어쓰지 않는다(워크트리에서 수정했을 수 있음).
 *
 * `.claude/worktrees/`는 반드시 제외한다 — 워크트리 자신이 그 아래 있어 재귀 복사가 된다.
 */
function seedWorktreeLocalConfig(mainPath: string, targetPath: string): void {
  const readEntries = (dir: string) => {
    try { return readdirSync(dir, { withFileTypes: true }); } catch { return []; }
  };
  const copyTree = (src: string, dest: string, depth: number): void => {
    if (depth > 8) return;
    for (const entry of readEntries(src)) {
      // depth 0 == .claude 바로 아래. 여기의 worktrees/ 가 재귀의 원인이다.
      if (depth === 0 && entry.name === "worktrees") continue;
      const from = join(src, entry.name);
      const to = join(dest, entry.name);
      if (entry.isDirectory()) {
        try { mkdirSync(to, { recursive: true }); } catch { continue; }
        copyTree(from, to, depth + 1);
      } else if (entry.isFile() && !existsSync(to)) {
        try { copyFileSync(from, to); } catch { /* 개별 파일 실패는 무시 */ }
      }
    }
  };
  try {
    const claudeSrc = join(mainPath, ".claude");
    if (existsSync(claudeSrc)) {
      const claudeDest = join(targetPath, ".claude");
      mkdirSync(claudeDest, { recursive: true });
      copyTree(claudeSrc, claudeDest, 0);
    }
  } catch { /* best-effort */ }
  try {
    for (const entry of readEntries(mainPath)) {
      if (!entry.isFile() || !/^\.env(\..+)?$/.test(entry.name)) continue;
      const to = join(targetPath, entry.name);
      if (!existsSync(to)) copyFileSync(join(mainPath, entry.name), to);
    }
  } catch { /* best-effort */ }
}

async function createInitialSnapshotCommit(folderPath: string): Promise<{ success: boolean; error?: string }> {
  const add = await stageAllExceptVolatileArtifacts(folderPath);
  if (add.exitCode !== 0) {
    return { success: false, error: add.output || "초기 프로젝트 파일을 스테이징하지 못했습니다." };
  }
  const commit = Bun.spawn(
    [
      GIT_PATH,
      "-c", "user.name=AgentsToZ",
      "-c", "user.email=agentstoz@localhost",
      "commit", "--allow-empty", "-m", "Initial commit",
    ],
    { cwd: folderPath, stdout: "pipe", stderr: "pipe" },
  );
  await commit.exited;
  if (commit.exitCode !== 0) {
    const detail = `${await new Response(commit.stdout).text()}${await new Response(commit.stderr).text()}`.trim();
    return { success: false, error: detail || "초기 커밋을 만들지 못했습니다." };
  }
  return { success: true };
}

/** 앱이 워크트리를 만드는 기본 폴더(비숨김). 숨김 폴더면 Orca가 인식하지 못한다. */
const WORKTREE_DIR = 'worktrees';
/** 이전 기본 폴더 — 이미 만들어진 워크트리를 계속 앱 소유로 인식하기 위해 유지한다. */
const LEGACY_WORKTREE_REL = '.claude/worktrees';

/** Git이 반환한 경로와 API 입력 경로를 플랫폼에 맞게 정확히 비교한다. */
function normalizeWorktreePath(value: string): string {
  const normalized = resolve(value).replace(/\\/g, '/').replace(/\/+$/, '');
  return IS_WIN ? normalized.toLowerCase() : normalized;
}

/** 비ASCII 경로를 C 스타일 escape로 바꾸지 않아 실제 절대경로와 비교할 수 있게 한다. */
const gitWorktreeListArgs = (): string[] => [
  '-c',
  'core.quotePath=false',
  'worktree',
  'list',
  '--porcelain',
];

/** 경로가 앱이 만든 워크트리 영역(현행 또는 레거시) 안에 있는가. */
function isAppOwnedWorktreePath(folderPath: string, wtPath: string): boolean {
  const root = normalizeWorktreePath(folderPath);
  const target = normalizeWorktreePath(wtPath);
  return target.startsWith(`${root}/${WORKTREE_DIR}/`) || target.startsWith(`${root}/${LEGACY_WORKTREE_REL}/`);
}

/** 경로가 **레거시(숨김) 워크트리 폴더** 안에 있는가 — 숨김 폴더라 Orca가 스캔하지 않는다. */
function isLegacyWorktreePath(folderPath: string, wtPath: string): boolean {
  return normalizeWorktreePath(wtPath).startsWith(`${normalizeWorktreePath(folderPath)}/${LEGACY_WORKTREE_REL}/`);
}

async function ensureLocalWorktreeExclude(folderPath: string): Promise<void> {
  const result = Bun.spawnSync([GIT_PATH, "rev-parse", "--git-path", "info/exclude"], {
    cwd: folderPath,
    stdout: "pipe",
    stderr: "pipe",
  });
  if (!result.success) return;
  const rawPath = result.stdout.toString().trim();
  if (!rawPath) return;
  const excludePath = isAbsolute(rawPath) ? rawPath : join(folderPath, rawPath);
  let content = "";
  try { content = await Bun.file(excludePath).text(); } catch {}
  const patterns = ["/.claude/worktrees/", "/worktrees/", ".DS_Store", "/.agent-memory/backups/"];
  const existing = new Set(content.split(/\r?\n/).map(line => line.trim()).filter(Boolean));
  const missing = patterns.filter(pattern => !existing.has(pattern));
  if (missing.length === 0) return;
  mkdirSync(dirname(excludePath), { recursive: true });
  const suffix = `${missing.join("\n")}\n`;
  await Bun.write(excludePath, content ? `${content.trimEnd()}\n${suffix}` : suffix);
}

interface GitWorktreeStatus extends ParsedGitCheckoutStatus {
  hasUpstream: boolean;
  remoteBranchExists: boolean;
  githubConnected: boolean;
  statusError?: string;
}

async function runGitForStatus(
  cwd: string,
  args: string[],
  timeoutMs = 8_000,
  isolateRepositoryContext = false,
): Promise<{ ok: boolean; stdout: string; stderr: string; timedOut: boolean }> {
  // Bun 1.3.1의 spawn/spawnSync를 장시간 폴링에서 수천 번 호출하면 종료된
  // 핸들이 누적돼 API 프로세스가 SIGSEGV로 끝나는 것이 실측됐다. Node 호환
  // execFile callback은 자원을 회수하며, 전역 큐로 동시에 하나만 실행한다.
  const run = () => new Promise<{ ok: boolean; stdout: string; stderr: string; timedOut: boolean }>((resolveRun) => {
    let settled = false;
    const finish = (value: { ok: boolean; stdout: string; stderr: string; timedOut: boolean }) => {
      if (settled) return;
      settled = true;
      clearTimeout(hardStop);
      resolveRun(value);
    };
    const gitEnvironment: NodeJS.ProcessEnv = { ...process.env };
    if (isolateRepositoryContext) {
      for (const key of Object.keys(gitEnvironment)) {
        if (key.startsWith('GIT_')) delete gitEnvironment[key];
      }
      gitEnvironment.GIT_OPTIONAL_LOCKS = '0';
      gitEnvironment.LC_ALL = 'C';
      gitEnvironment.LANG = 'C';
    }
    gitEnvironment.GIT_TERMINAL_PROMPT = '0';
    const child = nodeExecFile(
      GIT_PATH,
      args,
      {
        cwd,
        env: gitEnvironment,
        timeout: timeoutMs,
        // ⚠️ 기본 killSignal(SIGTERM)은 git이 무시하면 콜백이 끝내 오지 않는다.
        // 이 호출은 전역 큐를 물고 있으므로, 하나가 안 죽으면 서버의 모든 git 조회가
        // 영구히 멈춘다. 상태 조회는 중단해도 안전하니 곧바로 SIGKILL을 쓴다.
        killSignal: 'SIGKILL',
        maxBuffer: 4 * 1024 * 1024,
        encoding: 'utf8',
      },
      (error: any, stdout: string, stderr: string) => {
        const timedOut = !!error && (error.killed === true || error.code === 'ETIMEDOUT');
        finish({
          ok: !error,
          stdout: String(stdout ?? '').trim(),
          stderr: String(stderr ?? error?.message ?? '').trim(),
          timedOut,
        });
      },
    );
    // 그래도 콜백이 오지 않는 경우(자식이 fd를 물려준 손자 프로세스를 남기는 등)를 대비한
    // 큐 차원의 최종 방어선 — 큐가 통째로 멈추는 것보다 이 호출 하나를 포기하는 게 낫다.
    const hardStop = setTimeout(() => {
      try { child.kill('SIGKILL'); } catch { /* 이미 종료됨 */ }
      finish({ ok: false, stdout: '', stderr: 'git 응답 없음 — 호출을 중단했습니다.', timedOut: true });
    }, timeoutMs + 5_000);
    (hardStop as any).unref?.();
  });
  const task = gitStatusProcessQueue.then(run, run);
  gitStatusProcessQueue = task.then(() => undefined, () => undefined);
  return task;
}

/** 워크트리 생성 시각. git이 기록하지 않으므로 `.git` 표식의 생성 시각을 쓴다.
 *  연결 워크트리에서 `.git`은 생성 시점에 쓰이는 파일이라 정확하고,
 *  주 워크트리에서는 `.git` 디렉터리 = 저장소가 만들어진 시각이다.
 *  birthtime을 못 얻는 파일시스템에서는 ctime으로 물러선다. */
function readWorktreeCreatedAt(worktreePath: string): { createdAt?: string } {
  try {
    const marker = join(worktreePath, '.git');
    const stat = statSync(existsSync(marker) ? marker : worktreePath);
    const birth = stat.birthtime instanceof Date && stat.birthtime.getTime() > 0
      ? stat.birthtime
      : stat.ctime;
    return Number.isFinite(birth?.getTime?.()) ? { createdAt: birth.toISOString() } : {};
  } catch {
    return {};
  }
}

function readDirtySubmodules(worktreePath: string): DirtySubmoduleDiagnostic[] {
  const candidatePaths = new Set<string>();
  if (existsSync(join(worktreePath, '.gitmodules'))) {
    const configured = Bun.spawnSync(
      [GIT_PATH, 'config', '-f', '.gitmodules', '--get-regexp', '^submodule\\..*\\.path$'],
      { cwd: worktreePath, stdout: 'pipe', stderr: 'pipe', timeout: 5_000 },
    );
    if (configured.success) {
      for (const line of configured.stdout.toString().split(/\r?\n/)) {
        const path = line.match(/^\S+\s+(.+)$/)?.[1]?.trim();
        if (path) candidatePaths.add(path);
      }
    }
  }
  // .gitmodules가 누락되거나 불완전해도 Git index의 160000(gitlink) 항목으로
  // 실제 서브모듈 경로를 복구한다.
  const gitlinks = Bun.spawnSync(
    [GIT_PATH, 'ls-files', '--stage'],
    { cwd: worktreePath, stdout: 'pipe', stderr: 'pipe', timeout: 5_000 },
  );
  if (gitlinks.success) {
    for (const line of gitlinks.stdout.toString().split(/\r?\n/)) {
      const path = line.match(/^160000\s+[0-9a-f]+\s+\d+\t(.+)$/i)?.[1]?.trim();
      if (path) candidatePaths.add(path);
    }
  }

  const dirty: DirtySubmoduleDiagnostic[] = [];
  for (const path of candidatePaths) {
    if (!path || isAbsolute(path) || path.split(/[\\/]/).includes('..')) continue;
    const submodulePath = join(worktreePath, path);
    if (!existsSync(submodulePath) || !statSync(submodulePath).isDirectory()) continue;
    const status = Bun.spawnSync(
      [GIT_PATH, 'status', '--porcelain=v1', '--untracked-files=normal'],
      { cwd: submodulePath, stdout: 'pipe', stderr: 'pipe', timeout: 5_000 },
    );
    const output = status.stdout.toString().trim();
    if (output) dirty.push({ path, status: output });
    if (dirty.length >= 20) break;
  }
  return dirty;
}

async function readGitWorktreeStatus(path: string, branch?: string): Promise<GitWorktreeStatus> {
  const statusResult = await runGitForStatus(
    path,
    [
      'status',
      '--porcelain=v2',
      '--branch',
      '--untracked-files=normal',
      '--',
      '.',
      ...GIT_VOLATILE_ARTIFACT_PATHSPECS,
    ],
  );
  if (!statusResult.ok) {
    return {
      changedFiles: 0,
      stagedFiles: 0,
      untrackedFiles: 0,
      conflictedFiles: 0,
      hasCommits: false,
      ahead: 0,
      behind: 0,
      hasUpstream: false,
      remoteBranchExists: false,
      githubConnected: false,
      statusError: statusResult.timedOut ? 'Git 상태 확인 시간 초과' : (statusResult.stderr || 'Git 상태 확인 실패'),
    };
  }

  const parsed = parseGitStatusPorcelainV2(statusResult.stdout);
  const originResult = await runGitForStatus(path, ['remote', 'get-url', 'origin']);
  const githubConnected = originResult.ok && isGitHubRemoteUrl(originResult.stdout);
  const hasUpstream = !!parsed.upstream;
  let remoteBranchExists = hasUpstream;

  // Tracking 설정만 빠진 경우에도 로컬 origin/<branch> 참조가 있으면
  // Pull/Push 필요 상태를 계산할 수 있다.
  if (!parsed.upstream && branch) {
    const remoteRef = `refs/remotes/origin/${branch}`;
    const remoteResult = await runGitForStatus(path, ['show-ref', '--verify', '--quiet', remoteRef]);
    if (remoteResult.ok) {
      remoteBranchExists = true;
      const fallbackUpstream = `origin/${branch}`;
      const countsResult = await runGitForStatus(
        path,
        ['rev-list', '--left-right', '--count', `HEAD...${fallbackUpstream}`],
      );
      if (countsResult.ok) {
        const [aheadText = '0', behindText = '0'] = countsResult.stdout.split(/\s+/);
        parsed.ahead = Number.parseInt(aheadText, 10) || 0;
        parsed.behind = Number.parseInt(behindText, 10) || 0;
        parsed.upstream = fallbackUpstream;
      }
    }
  }

  return { ...parsed, hasUpstream, remoteBranchExists, githubConnected };
}

/** VS Build Tools (MSVC) 설치 여부 감지. 디렉터리 존재로 판정 — Bun.file().exists()는 디렉터리에 false를 반환하므로 existsSync 사용. */
function hasVsBuildTools(): boolean {
  const vsPaths = [
    'C:/Program Files/Microsoft Visual Studio/2022/BuildTools',
    'C:/Program Files/Microsoft Visual Studio/2022/Community',
    'C:/Program Files/Microsoft Visual Studio/2022/Professional',
    'C:/Program Files/Microsoft Visual Studio/2022/Enterprise',
    'C:/Program Files (x86)/Microsoft Visual Studio/2022/BuildTools',
    'C:/Program Files (x86)/Microsoft Visual Studio/2019/BuildTools',
    'C:/BuildTools',
  ];
  return vsPaths.some(p => existsSync(p + '/VC/Tools/MSVC'));
}

/** Windows 경로를 WSL /mnt/... 경로로 변환 */
function winToWslPath(winPath: string): string {
  if (winPath.length >= 2 && winPath[1] === ':') {
    const drive = winPath.charAt(0).toLowerCase();
    const rest = winPath.slice(2).replace(/\\/g, '/');
    return `/mnt/${drive}${rest}`;
  }
  return winPath.replace(/\\/g, '/');
}

const { spawnSync: nodeSpawnSync, execFile: nodeExecFile } = require('child_process');
let gitStatusProcessQueue: Promise<unknown> = Promise.resolve();

// ──────────────── cmux helpers (browser/web fallback path) ────────────────
// Tauri app uses Rust commands directly (src-tauri/src/lib.rs). For browser/
// localhost mode, we keep these helpers but use Node's child_process to
// sidestep the Bun.spawn degradation observed in long-running Bun.serve.

function resolveCmuxCli(): string | null {
  const bundled = '/Applications/cmux.app/Contents/Resources/bin/cmux';
  const homeBundled = `${homedir()}/Applications/cmux.app/Contents/Resources/bin/cmux`;
  const homebrew = '/opt/homebrew/bin/cmux';
  const usrLocal = '/usr/local/bin/cmux';
  if (existsSync(bundled)) return bundled;
  if (existsSync(homeBundled)) return homeBundled;
  if (existsSync(homebrew)) return homebrew;
  if (existsSync(usrLocal)) return usrLocal;
  return null;
}

/** cmux does not necessarily inherit the interactive shell PATH. Resolve tmux
 *  before creating the workspace so a successful cmux RPC cannot hide an
 *  immediate `tmux: command not found` inside the new terminal. */
function resolveTmuxCli(): string | null {
  const candidates = [
    `${homedir()}/.local/bin/tmux`,
    '/opt/homebrew/bin/tmux',
    '/usr/local/bin/tmux',
    '/usr/bin/tmux',
  ];
  const known = candidates.find(candidate => existsSync(candidate));
  if (known) return known;
  try {
    const result = nodeSpawnSync('/bin/zsh', ['-lc', 'command -v -- tmux'], {
      encoding: 'utf-8',
      timeout: 5_000,
    });
    const found = String(result.stdout ?? '').trim().split(/\r?\n/)[0] ?? '';
    return result.status === 0 && isAbsolute(found) && existsSync(found) ? found : null;
  } catch {
    return null;
  }
}

function cmuxAppExists(): boolean {
  return existsSync('/Applications/cmux.app') || existsSync(`${homedir()}/Applications/cmux.app`);
}

/** Invoke cmux via `osascript do shell script` with a CLEANED env (no CMUX_*
 *  vars inherited from the api-server's parent shell) — Bun.serve's long-running
 *  process tree exhibits a degradation where cmux subprocess calls start
 *  failing with broken pipe after some time, even via bash/Node child_process.
 *  Using osascript routes through macOS's AppleScript engine (fully detached
 *  from Bun's subprocess state) and stripping CMUX_* prevents the daemon from
 *  treating the call as a stale-pane request. */
function nodeCmuxRun(cli: string, args: string[], timeoutMs = 8000): { ok: boolean; stderr: string; stdout: string } {
  const escape = (s: string) => s.replace(/\\/g, '\\\\').replace(/"/g, '\\"');
  const shellEscape = (s: string) => `'${s.replace(/'/g, "'\\''")}'`;
  const shellCmd = `${shellEscape(cli)} ${args.map(shellEscape).join(' ')}`;
  const appleScript = `do shell script "${escape(shellCmd)}"`;
  // Strip CMUX_* env vars — they reference panes that may not match the call context.
  const cleanEnv: Record<string, string> = {};
  for (const [k, v] of Object.entries(process.env)) {
    if (!k.startsWith('CMUX_') && v !== undefined) cleanEnv[k] = v;
  }
  const r = nodeSpawnSync('osascript', ['-e', appleScript], {
    encoding: 'utf-8',
    timeout: timeoutMs,
    env: cleanEnv,
  });
  const spawnError = (r as any).error;
  const timeoutError = spawnError?.code === 'ETIMEDOUT'
    ? `cmux CLI 응답 시간 초과 (${Math.round(timeoutMs / 1000)}초)`
    : '';
  return {
    ok: r.status === 0 && !spawnError,
    stderr: timeoutError || (r.stderr ?? '').toString().trim() || spawnError?.message || '',
    stdout: (r.stdout ?? '').toString().trim(),
  };
}

function ensureCmuxWindowNode(cli: string): { ok: boolean; error?: string } {
  const listing = nodeCmuxRun(cli, ['list-windows']);
  if (!listing.ok) return { ok: false, error: listing.stderr || 'cmux 창 목록을 확인하지 못했습니다.' };
  if (listing.stdout.trim() !== 'No windows') return { ok: true };
  const created = nodeCmuxRun(cli, ['new-window']);
  return created.ok
    ? { ok: true }
    : { ok: false, error: created.stderr || 'cmux 창을 만들지 못했습니다.' };
}

/** The context-usage poll must not block Bun's request loop. Focus/create
 * actions retain the synchronous helper above for their existing sequencing,
 * while passive liveness checks use this non-blocking equivalent. */
async function nodeCmuxRunAsync(
  cli: string,
  args: string[],
  timeoutMs = 8000,
): Promise<{ ok: boolean; stderr: string; stdout: string }> {
  const escape = (s: string) => s.replace(/\\/g, '\\\\').replace(/"/g, '\\"');
  const shellEscape = (s: string) => `'${s.replace(/'/g, "'\\''")}'`;
  const shellCmd = `${shellEscape(cli)} ${args.map(shellEscape).join(' ')}`;
  const appleScript = `do shell script "${escape(shellCmd)}"`;
  const cleanEnv: Record<string, string> = {};
  for (const [k, v] of Object.entries(process.env)) {
    if (!k.startsWith('CMUX_') && v !== undefined) cleanEnv[k] = v;
  }
  return new Promise((resolveRun) => {
    nodeExecFile(
      'osascript',
      ['-e', appleScript],
      { encoding: 'utf-8', timeout: timeoutMs, env: cleanEnv, maxBuffer: 4 * 1024 * 1024 },
      (error: any, stdout: string, stderr: string) => {
        const timeoutError = error?.code === 'ETIMEDOUT'
          ? `cmux CLI 응답 시간 초과 (${Math.round(timeoutMs / 1000)}초)`
          : '';
        const detail = String(stderr ?? '').trim() || error?.message || '';
        resolveRun({
          ok: !error,
          stderr: timeoutError || detail,
          stdout: String(stdout ?? '').trim(),
        });
      },
    );
  });
}

/** A socket-policy denial does not prove that cmux is closed. When it occurs,
 * this separate read-only process check can still prove the inverse: no cmux
 * app process means no cmux surface exists. `null` preserves uncertainty when
 * macOS blocks process inspection. */
async function isCmuxAppProcessRunning(): Promise<boolean | null> {
  if (IS_WIN) return null;
  const script = "do shell script \"/usr/bin/pgrep -f '[c]mux\\.app/Contents/MacOS/cmux' >/dev/null 2>&1; /bin/echo $?\"";
  return new Promise((resolveCheck) => {
    nodeExecFile(
      'osascript',
      ['-e', script],
      { encoding: 'utf-8', timeout: 2_000 },
      (error: any, stdout: string) => {
        if (error) return resolveCheck(null);
        const code = String(stdout ?? '').trim();
        if (code === '0') return resolveCheck(true);
        if (code === '1') return resolveCheck(false);
        return resolveCheck(null);
      },
    );
  });
}

async function waitCmuxReadyNode(cli: string, totalMs = 10000): Promise<boolean> {
  const deadline = Date.now() + totalMs;
  while (Date.now() < deadline) {
    const remaining = deadline - Date.now();
    if (remaining <= 0) break;
    // ping timeout: 2초로 제한 — 8초 기본값이면 10초 윈도우에서 1번밖에 못 시도
    if (nodeCmuxRun(cli, ['ping'], Math.min(2000, remaining)).ok) return true;
    await new Promise(res => setTimeout(res, 200));
  }
  return false;
}

/** Build the cmux workspace tab title — mirrors Rust `build_window_title` for the
 *  is_tmux=true / cmux flow: "⚡️ project › worktree" (bypass) or "🔷 project › worktree". */
function buildCmuxTitle(name: string, worktreePath: string | undefined, bypass: boolean): string {
  const wtBase = (worktreePath ?? '').split(',')[0]?.trim().split('/').pop() ?? '';
  const base = wtBase ? `${name} › ${wtBase}` : name;
  const prefix = bypass ? '⚡️ ' : '🔷 ';
  return prefix + base;
}

function cmuxAccessHelp(base: string): string {
  return `${base}\n\n💡 cmux 설정 확인: cmux 메뉴 → Settings → Socket Control → "Allow All"로 변경 후 재시도하세요. (현재 cmuxOnly 모드는 외부 앱의 호출을 차단)`;
}

async function cmuxSendNodeWithRetry(cli: string, payload: string): Promise<{ ok: boolean; stderr: string }> {
  let lastErr = '';
  for (let attempt = 0; attempt < 3; attempt++) {
    const r = nodeCmuxRun(cli, ['send', payload]);
    if (r.ok) return { ok: true, stderr: '' };
    lastErr = r.stderr;
    if (!/Broken pipe|errno 32/i.test(lastErr)) break;
    if (attempt < 2) await new Promise(res => setTimeout(res, 300));
  }
  return { ok: false, stderr: lastErr || 'unknown' };
}

// ──────────────── Orca helpers (browser/web fallback path) ────────────────
// Orca(https://www.onorca.dev)는 Electron 앱 + VS Code 스타일 CLI 런처를 번들.
// 워크플로: orca open(런타임 대기, 멱등) → repo add(멱등) → terminal create.
// git 저장소만 등록 가능 — 비 git 폴더는 명확한 에러로 안내.

/** 모든 Orca CLI 호출을 직렬화하는 락. 실측: 더블클릭 등으로 요청 2~3개가 겹치면
 *  osascript 경유 nodeSpawnSync(완전 블로킹) 호출이 겹쳐 쌓이면서 Bun 자체가
 *  세그폴트로 죽는 것을 확인(Bun 1.3.1 자체 버그로 보이나 우리 쪽에서 유발).
 *  Orca 작업은 항상 이 락을 통해 한 번에 하나씩만 실행 — 동시 요청은 대기열로 직렬화. */
let orcaLock: Promise<unknown> = Promise.resolve();
function withOrcaLock<T>(fn: () => Promise<T>): Promise<T> {
  const run = orcaLock.then(fn, fn);
  orcaLock = run.then(() => undefined, () => undefined);
  return run;
}

function resolveOrcaCli(): string | null {
  if (IS_WIN) {
    const local = process.env.LOCALAPPDATA ?? '';
    const pf = process.env['ProgramFiles'] ?? '';
    const candidates = [
      `${local}\\Programs\\orca\\resources\\bin\\orca.exe`,
      `${local}\\Programs\\Orca\\resources\\bin\\orca.exe`,
      `${pf}\\orca\\resources\\bin\\orca.exe`,
      `${pf}\\Orca\\resources\\bin\\orca.exe`,
    ];
    for (const p of candidates) if (existsSync(p)) return p;
    return null;
  }
  const candidates = [
    '/Applications/Orca.app/Contents/Resources/bin/orca',
    `${homedir()}/Applications/Orca.app/Contents/Resources/bin/orca`,
    '/opt/homebrew/bin/orca',
    '/usr/local/bin/orca',
  ];
  for (const p of candidates) if (existsSync(p)) return p;
  return null;
}

/** Orca ignores hidden path segments when attaching visible worktree panes. */
function hasHiddenOrcaPathSegment(pathValue: string | null | undefined): boolean {
  if (!pathValue) return false;
  return pathValue.replace(/\\/g, '/').split('/').some((segment) => segment.length > 1 && segment.startsWith('.'));
}

/** Resolve a saved symlink before giving its path to Orca's sidebar selector. */
function resolveOrcaProjectPath(pathValue: string | null): string | null {
  if (!pathValue) return null;
  try { return realpathSync(pathValue); } catch { return pathValue; }
}

function hiddenOrcaWorktreeResponse(headers: Record<string, string>): Response {
  return new Response(JSON.stringify({
    success: false,
    code: 'ORCA_HIDDEN_WORKTREE_NOT_VISIBLE',
    error: '이 워크트리는 숨김 경로라 Orca 화면에 연결되지 않는 세션이 생성될 수 있습니다. WORKTREES의 “새 경로로 옮기기”를 먼저 실행하세요. 아무 세션도 생성하지 않았습니다.',
  }), { status: 409, headers });
}

/** macOS: osascript 우회(Bun.serve 프로세스 트리에서 직접 spawn 시 간헐 실패).
 *  Windows: 직접 execFile — osascript 없음, Bun.serve 트리 격리는 cleanEnv로 처리. */
async function nodeOrcaRun(
  cli: string,
  args: string[],
  timeoutMs = 40000,
): Promise<{ ok: boolean; stderr: string; stdout: string }> {
  // Windows: 직접 실행
  if (IS_WIN) {
    const cleanEnv: Record<string, string> = {
      APPDATA: process.env.APPDATA ?? '',
      LOCALAPPDATA: process.env.LOCALAPPDATA ?? '',
      USERPROFILE: process.env.USERPROFILE ?? homedir(),
      USERNAME: process.env.USERNAME ?? '',
      COMPUTERNAME: process.env.COMPUTERNAME ?? '',
      SYSTEMROOT: process.env.SYSTEMROOT ?? 'C:\\Windows',
      PATH: process.env.PATH ?? '',
      TEMP: process.env.TEMP ?? '',
      TMP: process.env.TMP ?? '',
    };
    return new Promise((resolveRun) => {
      nodeExecFile(
        cli,
        args,
        { encoding: 'utf8', timeout: timeoutMs, env: cleanEnv, maxBuffer: 4 * 1024 * 1024 },
        (error: any, stdout: string, stderr: string) => {
          const timedOut = !!error && (error.killed === true || error.code === 'ETIMEDOUT');
          resolveRun({
            ok: !error,
            stderr: timedOut
              ? `Orca CLI 응답 시간 초과 (${Math.round(timeoutMs / 1000)}초)`
              : String(stderr ?? error?.message ?? '').trim(),
            stdout: String(stdout ?? '').trim(),
          });
        },
      );
    });
  }
  // macOS: osascript 우회
  const escape = (s: string) => s.replace(/\\/g, '\\\\').replace(/"/g, '\\"');
  const shellEscape = (s: string) => `'${s.replace(/'/g, "'\\''")}'`;
  const shellCmd = `${shellEscape(cli)} ${args.map(shellEscape).join(' ')} 2>&1; exit 0`;
  const appleScript = `do shell script "${escape(shellCmd)}"`;
  const cleanEnv: Record<string, string> = {
    HOME: homedir(),
    USER: process.env.USER ?? '',
    LOGNAME: process.env.LOGNAME ?? process.env.USER ?? '',
    SHELL: process.env.SHELL ?? '/bin/zsh',
    TMPDIR: process.env.TMPDIR ?? '/tmp',
    LANG: process.env.LANG ?? 'en_US.UTF-8',
    PATH: '/opt/homebrew/bin:/usr/local/bin:/usr/bin:/bin:/usr/sbin:/sbin',
  };
  return new Promise((resolveRun) => {
    nodeExecFile(
      'osascript',
      ['-e', appleScript],
      { encoding: 'utf8', timeout: timeoutMs, env: cleanEnv, maxBuffer: 4 * 1024 * 1024 },
      (error: any, stdout: string, stderr: string) => {
        const timedOut = !!error && (error.killed === true || error.code === 'ETIMEDOUT');
        resolveRun({
          ok: !error,
          stderr: timedOut
            ? `Orca CLI 응답 시간 초과 (${Math.round(timeoutMs / 1000)}초)`
            : String(stderr ?? error?.message ?? '').trim(),
          stdout: String(stdout ?? '').trim(),
        });
      },
    );
  });
}

/** Some Electron CLIs emit a diagnostic line on stderr before their JSON.  The
 * macOS osascript bridge intentionally combines stdout/stderr, so recover the
 * JSON document instead of treating harmless diagnostics as a runtime outage. */
function parseCliJsonOutput(stdout: string): any | null {
  try { return JSON.parse(stdout); } catch { /* try the first JSON document below */ }
  const starts = stdout.matchAll(/^[\t ]*([\[{])/gm);
  for (const match of starts) {
    const offset = (match.index ?? 0) + match[0].lastIndexOf(match[1]!);
    try { return JSON.parse(stdout.slice(offset).trim()); } catch { /* try the next line */ }
  }
  return null;
}

/** JSON 출력 커맨드 실행 — CLI는 실패도 exit 0 + {ok:false}로 반환하므로 둘 다 검사
 *  timeoutMs 기본값은 15s — 관측된 데몬 부하 스파이크(7~10s)보다 여유 있게 크지만,
 *  요청 하나가 open→repo add→terminal create→send→switch 5단계를 재시도까지 포함해
 *  순차 실행하므로 Bun.serve idleTimeout(90s로 상향, 아래 참고)을 넘기지 않도록 억제. */
async function nodeOrcaRunJson(
  cli: string,
  args: string[],
  timeoutMs = 15000,
): Promise<{ ok: boolean; error: string; result: any }> {
  const r = await nodeOrcaRun(cli, [...args, '--json'], timeoutMs);
  if (!r.ok) return { ok: false, error: r.stderr || r.stdout || 'unknown', result: null };
  const parsed = parseCliJsonOutput(r.stdout);
  if (!parsed) {
    return { ok: false, error: `JSON 파싱 실패: ${r.stdout.slice(0, 200)}`, result: null };
  }
  if (parsed?.ok === false) return { ok: false, error: parsed?.error?.message ?? 'unknown', result: null };
  return { ok: true, error: '', result: parsed?.result ?? null };
}

/**
 * Orca가 **자체 관리하는** 워크트리 경로 집합.
 *
 * Orca는 `orca worktree create`로 자기가 만든 워크트리만 사이드바 트리에 표시한다
 * (repo 메타데이터의 externalWorktreeVisibility 기본값이 "hide"). 그래서 이 앱이
 * `git worktree add`로 만든 워크트리는 **실행은 정상인데 Orca 목록에는 안 보인다**.
 * 사용자가 그 차이를 앱에서 바로 알 수 있도록 출처 배지를 붙이는 데 쓴다.
 *
 * Orca가 없거나 조회에 실패하면 available:false로 응답해 UI가 배지를 감추게 한다
 * (틀린 출처를 단정하지 않는다).
 */
let orcaWorktreeCache: { at: number; paths: string[] } | null = null;
const ORCA_WORKTREE_CACHE_MS = 15_000;

/**
 * project-memory 요청 파라미터 — JSON body와 쿼리스트링을 **둘 다** 받는다.
 *
 * 이 API는 앱 UI만 쓰는 게 아니라 AI(Claude/Codex)가 스킬에서 `curl --get`으로 직접 부른다.
 * 예전에는 엔드포인트마다 방식이 달라서 push/mark-remembered만 쿼리를 받고
 * detect/pull/remote-status/history는 body만 받았고, 그래서 **AI는 push는 할 수 있어도
 * pull은 할 수 없었다**(다른 PC에서 저장한 기억을 가져올 방법이 없었다).
 * body가 우선이고, 없으면 쿼리에서 읽는다.
 */
async function readMemoryParams(req: Request, url: URL): Promise<Record<string, any>> {
  let body: Record<string, any> = {};
  if (req.headers.get("content-type")?.includes("application/json")) {
    // Swallowing a failed body read here used to surface as "절대경로가 필요합니다",
    // which blames the caller for a path it actually sent. Report the real
    // condition instead so a dropped body is diagnosable rather than misleading.
    try {
      body = await req.json() as Record<string, any>;
    } catch (error: any) {
      throw new ProjectMemoryError(
        `요청 본문을 읽지 못했습니다: ${error?.message || String(error)}`,
        "REQUEST_BODY_UNREADABLE",
      );
    }
  }
  return { ...Object.fromEntries(url.searchParams.entries()), ...body };
}

function projectMemoryThreadRoute(body: Record<string, any>): ProjectMemoryThreadRoute {
  return {
    platform: typeof body.platform === "string" ? body.platform : "",
    chatId: typeof body.chatId === "string" ? body.chatId : "",
    threadId: typeof body.threadId === "string" && body.threadId.trim() ? body.threadId : null,
  };
}

async function verifiedProjectMemoryThreadBinding(body: Record<string, any>) {
  const storedBinding = await getProjectMemoryThreadBinding(
    PROJECT_MEMORY_THREAD_BINDINGS_FILE,
    projectMemoryThreadRoute(body),
  );
  if (!storedBinding) {
    throw new ProjectMemoryError(
      "현재 채팅/스레드는 프로젝트 장기기억과 연결되어 있지 않습니다.",
      "PROJECT_MEMORY_THREAD_NOT_BOUND",
    );
  }
  const registered = await loadPortsData() as Array<PortRecord & {
    name?: string;
    folderPath?: string;
    worktreePath?: string;
  }>;
  const resolution = resolveRegisteredProjectMemory(
    storedBinding.projectId,
    registered,
    alias => {
      const candidate = detectProjectMemory(alias);
      return candidate.exists && candidate.config ? candidate.projectRoot : null;
    },
  );
  if ("code" in resolution) {
    throw new ProjectMemoryError(
      "스레드에 연결된 프로젝트가 현재 AgentsToZ 등록 목록에서 유효하지 않습니다. 다시 연결하세요.",
      "PROJECT_MEMORY_THREAD_IDENTITY_MISMATCH",
    );
  }
  const status = detectProjectMemory(resolution.canonicalPath);
  if (!status.exists || !status.config || status.config.memoryId !== storedBinding.memoryId) {
    throw new ProjectMemoryError(
      "스레드에 저장된 프로젝트 장기기억 ID가 현재 저장소와 일치하지 않습니다. 다시 연결하세요.",
      "PROJECT_MEMORY_THREAD_IDENTITY_MISMATCH",
    );
  }
  const binding = await bindProjectMemoryThread(PROJECT_MEMORY_THREAD_BINDINGS_FILE, {
    ...projectMemoryThreadRoute(body),
    projectId: resolution.id,
    projectName: resolution.name,
    memoryId: status.config.memoryId,
    canonicalPath: status.projectRoot,
  });
  return { binding, status };
}

type RegisteredBuzzProject = {
  projectId: string;
  projectName: string;
  canonicalPath: string;
  memoryId: string;
};

/** Resolve only an exact AgentsToZ project row. The browser never supplies a
 * working directory to Buzz endpoints; canonicalPath is recovered from the
 * registered allowlist and checked again against project-local memory. */
async function resolveRegisteredUseProject(portIdInput: unknown): Promise<{
  projectId: string;
  projectName: string;
  canonicalPath: string;
  memoryId: string | null;
}> {
  const portId = typeof portIdInput === "string" ? portIdInput.trim() : "";
  if (!portId) throw new ProjectMemoryError("등록 프로젝트 ID가 필요합니다.", "PROJECT_QUERY_REQUIRED");
  const registered = await loadPortsData() as Array<PortRecord & {
    name?: string;
    folderPath?: string;
    worktreePath?: string;
  }>;
  const resolution = resolveRegisteredProjectMemory(portId, registered, undefined, { requireInitialized: false });
  if (!resolution.ok) throw new ProjectMemoryError(resolution.error, resolution.code);
  const memory = detectProjectMemory(resolution.canonicalPath);
  return {
    projectId: resolution.id,
    projectName: resolution.name,
    canonicalPath: memory.exists && memory.config?.memoryId ? memory.projectRoot : resolution.canonicalPath,
    memoryId: memory.exists && memory.config?.memoryId ? memory.config.memoryId : null,
  };
}

async function resolveRegisteredBuzzProject(portIdInput: unknown): Promise<RegisteredBuzzProject> {
  const project = await resolveRegisteredUseProject(portIdInput);
  if (!project.memoryId) {
    throw new ProjectMemoryError(
      "Buzz 채널에 연결하려면 프로젝트 장기기억을 먼저 초기화해야 합니다.",
      "PROJECT_MEMORY_NOT_INITIALIZED",
    );
  }
  return { ...project, memoryId: project.memoryId };
}

async function currentBuzzProjectBinding(project: RegisteredBuzzProject): Promise<ProjectMemoryThreadBinding | null> {
  const bindings = await findProjectMemoryThreadBindings(PROJECT_MEMORY_THREAD_BINDINGS_FILE, {
    platform: "buzz",
    projectId: project.projectId,
    memoryId: project.memoryId,
  });
  return bindings.find(binding => binding.canonicalPath === project.canonicalPath) ?? null;
}

function buzzBindingResponse(binding: ProjectMemoryThreadBinding | null) {
  if (!binding) return null;
  return {
    relayUrl: binding.chatId,
    channelId: binding.threadId,
    channelName: binding.threadName ?? null,
    verified: typeof binding.verifiedAt === "string" && !!binding.verifiedAt,
    verifiedAt: binding.verifiedAt ?? null,
    boundAt: binding.boundAt,
    updatedAt: binding.updatedAt,
  };
}

async function bindBuzzProjectChannel(input: {
  project: RegisteredBuzzProject;
  relayUrl: string;
  channelId: string;
  channelName: string;
  verifiedAt: string | null;
}): Promise<ProjectMemoryThreadBinding> {
  const route: ProjectMemoryThreadRoute = {
    platform: "buzz",
    chatId: input.relayUrl,
    threadId: input.channelId,
  };
  try {
    return await bindExclusiveProjectMemoryThread(PROJECT_MEMORY_THREAD_BINDINGS_FILE, {
      ...route,
      projectId: input.project.projectId,
      projectName: input.project.projectName,
      memoryId: input.project.memoryId,
      canonicalPath: input.project.canonicalPath,
      threadName: input.channelName,
      verifiedAt: input.verifiedAt,
    });
  } catch (error) {
    if (error instanceof ProjectMemoryThreadBindingConflictError) {
      throw new BuzzProjectError(
        "이 Buzz 채널은 이미 다른 AgentsToZ 프로젝트와 연결되어 있습니다. 기존 연결을 먼저 해제하세요.",
        "BUZZ_CHANNEL_ALREADY_BOUND",
      );
    }
    throw error;
  }
}

function buzzApiErrorResponse(error: unknown, headers: Record<string, string>): Response {
  const code = error instanceof BuzzProjectError || error instanceof ProjectMemoryError || error instanceof ServiceMemoryError
    ? error.code
    : "BUZZ_INTEGRATION_FAILED";
  const status = error instanceof BuzzProjectError
    ? error.status
    : error instanceof ServiceMemoryError
      ? error.code === "SERVICE_MEMORY_INPUT_INVALID"
        ? 400
        : error.code === "SERVICE_MEMORY_REGISTRY_CORRUPT"
          ? 500
          : 409
    : code === "PROJECT_NOT_REGISTERED" || code === "PROJECT_QUERY_REQUIRED"
      ? 404
      : code === "PROJECT_MEMORY_NOT_INITIALIZED"
        ? 409
        : 500;
  return new Response(JSON.stringify({
    success: false,
    code,
    error: error instanceof Error ? error.message : String(error),
  }), { status, headers });
}

function agentsToZUseErrorResponse(error: unknown, headers: Record<string, string>): Response {
  if (error instanceof AgentsToZUseControlError) {
    return new Response(JSON.stringify({ success: false, performed: false, code: error.code, error: error.message }), {
      status: error.status,
      headers,
    });
  }
  if (error instanceof ProjectMemoryError) {
    const status = error.code === "PROJECT_NOT_REGISTERED" || error.code === "PROJECT_QUERY_REQUIRED" ? 404 : 409;
    return new Response(JSON.stringify({ success: false, performed: false, code: error.code, error: error.message }), {
      status,
      headers,
    });
  }
  if (error instanceof BuzzProjectError) {
    return new Response(JSON.stringify({ success: false, performed: false, code: error.code, error: error.message }), {
      status: error.status,
      headers,
    });
  }
  return new Response(JSON.stringify({
    success: false,
    performed: false,
    code: "AGENTSTOZ_USE_ACTION_FAILED",
    error: error instanceof Error ? error.message : String(error),
  }), { status: 500, headers });
}

async function verifyAgentsToZUseController(portId: string): Promise<RegisteredBuzzProject> {
  const controller = await resolveRegisteredBuzzProject(portId);
  if (!isAgentsToZControlProject(controller)) {
    throw new AgentsToZUseControlError(
      "이 USE Agent는 등록된 AgentsToZ 프로젝트를 제어 정본으로 사용하지 않습니다.",
      "AGENTSTOZ_USE_CONTROLLER_MISMATCH",
      403,
    );
  }
  return controller;
}

function githubUrlsFromPort(port: Record<string, unknown> | undefined): string[] {
  if (!port) return [];
  const candidates = [
    ...(Array.isArray(port.githubUrls) ? port.githubUrls : []),
    port.githubUrl,
  ];
  return [...new Set(candidates
    .filter((value): value is string => typeof value === "string" && isGitHubRemoteUrl(value))
    .map(value => value.trim()))];
}

function agentsToZUseProjectStatusSnapshot(
  project: Omit<RegisteredBuzzProject, "memoryId"> & { memoryId: string | null },
  port: Record<string, unknown> | undefined,
  binding: ProjectMemoryThreadBinding | null,
) {
  const githubUrls = githubUrlsFromPort(port);
  return {
    projectId: project.projectId,
    projectName: project.projectName,
    memoryId: project.memoryId,
    memory: { initialized: project.memoryId !== null },
    github: {
      connected: githubUrls.length > 0,
      urls: githubUrls,
    },
    buzzDev: binding ? {
      connected: true,
      channelId: binding.threadId,
      channelName: binding.threadName ?? null,
      verified: typeof binding.verifiedAt === "string" && !!binding.verifiedAt,
    } : {
      connected: false,
      channelId: null,
      channelName: null,
      verified: false,
    },
  };
}

async function agentsToZUseProjectStatus(project: RegisteredBuzzProject) {
  const registered = await loadPortsData() as Array<PortRecord & Record<string, unknown>>;
  const port = registered.find(candidate => candidate.id === project.projectId);
  const binding = await currentBuzzProjectBinding(project);
  return agentsToZUseProjectStatusSnapshot(project, port, binding);
}

async function listAgentsToZUseProjects() {
  const registered = await loadPortsData() as Array<PortRecord & {
    name?: string;
    folderPath?: string;
    worktreePath?: string;
  } & Record<string, unknown>>;
  const bindings = await findProjectMemoryThreadBindings(PROJECT_MEMORY_THREAD_BINDINGS_FILE, { platform: "buzz" });
  const seen = new Set<string>();
  const unique = registered.filter(candidate => {
    if (!candidate?.id || seen.has(candidate.id)) return false;
    seen.add(candidate.id);
    return true;
  });
  const inspected = await Promise.all(unique.map(async candidate => {
    try {
      const aliases = [candidate.folderPath, candidate.worktreePath]
        .filter((value): value is string => typeof value === "string" && isAbsolute(value));
      const detectedAliases = await Promise.all(aliases.map(alias => Promise.race([
          (async () => {
            const projectRoot = await realpathAsync(alias);
            if (!(await statAsync(projectRoot)).isDirectory()) return null;
            try {
              const raw = await readFileAsync(join(projectRoot, ".agent-memory", "config.json"), "utf8");
              const config = JSON.parse(raw) as { memoryId?: unknown };
              const memoryId = typeof config.memoryId === "string" && /^[0-9a-f]{8}-[0-9a-f-]{27}$/i.test(config.memoryId)
                ? config.memoryId
                : null;
              return { projectRoot, memoryId };
            } catch {
              return { projectRoot, memoryId: null };
            }
          })(),
          new Promise<null>(resolve => setTimeout(() => resolve(null), 500)),
        ])));
      const memory = detectedAliases.find(value => value?.memoryId)
        ?? detectedAliases.find((value): value is NonNullable<typeof value> => value !== null)
        ?? null;
      if (!memory) return null;
      const project: Omit<RegisteredBuzzProject, "memoryId"> & { memoryId: string | null } = {
        projectId: candidate.id,
        projectName: typeof candidate.name === "string" && candidate.name.trim()
          ? candidate.name.trim()
          : basename(memory.projectRoot),
        canonicalPath: memory.projectRoot,
        memoryId: memory.memoryId,
      };
      const binding = project.memoryId
        ? bindings.find(value => value.projectId === project.projectId
          && value.memoryId === project.memoryId
          && value.canonicalPath === project.canonicalPath) ?? null
        : null;
      return agentsToZUseProjectStatusSnapshot(project, candidate, binding);
    } catch {
      // A stale registration must not prevent the valid project list from loading.
      return null;
    }
  }));
  const projects = inspected.filter((project): project is NonNullable<typeof project> => project !== null);
  return projects.sort((left, right) => left.projectName.localeCompare(right.projectName));
}

type AgentsToZUseWorkspaceRoot = {
  workspaceRootId: string;
  name: string;
  path: string;
};

async function agentsToZUseWorkspaceRoots(): Promise<AgentsToZUseWorkspaceRoot[]> {
  const rows = await loadWorkspaceRootsData();
  if (!Array.isArray(rows)) return [];
  const roots: AgentsToZUseWorkspaceRoot[] = [];
  const seen = new Set<string>();
  for (const row of rows) {
    if (!row || typeof row !== "object") continue;
    const value = row as Record<string, unknown>;
    const workspaceRootId = typeof value.id === "string" ? value.id.trim() : "";
    const path = typeof value.path === "string" ? value.path.trim() : "";
    if (!workspaceRootId || workspaceRootId.length > 200 || seen.has(workspaceRootId)) continue;
    if (!isAbsolute(path) || !existsSync(path)) continue;
    try {
      if (!statSync(path).isDirectory()) continue;
    } catch {
      continue;
    }
    const requestedName = typeof value.name === "string" ? value.name.trim() : "";
    roots.push({
      workspaceRootId,
      name: requestedName.slice(0, 120) || basename(path),
      path: realpathSync(path),
    });
    seen.add(workspaceRootId);
  }
  return roots;
}

function agentsToZUseWorkspaceRootResponse(root: AgentsToZUseWorkspaceRoot) {
  return { workspaceRootId: root.workspaceRootId, name: root.name };
}

type RegisteredLocalGitHubProject = {
  projectId: string;
  projectName: string;
  canonicalPath: string;
  record: PortRecord & Record<string, unknown>;
};

async function resolveRegisteredLocalGitHubProject(portIdInput: unknown): Promise<RegisteredLocalGitHubProject> {
  const projectId = typeof portIdInput === "string" ? portIdInput.trim() : "";
  if (!projectId || projectId.length > 200) {
    throw new AgentsToZUseControlError("등록 프로젝트 ID가 필요합니다.", "AGENTSTOZ_USE_PROJECT_ID_INVALID");
  }
  const ports = await readPortsFileStrict() as Array<PortRecord & Record<string, unknown>>;
  const record = ports.find(candidate => candidate.id === projectId);
  if (!record) {
    throw new AgentsToZUseControlError("등록된 프로젝트를 찾지 못했습니다.", "PROJECT_NOT_REGISTERED", 404);
  }
  const storedPath = typeof record.worktreePath === "string" && record.worktreePath.trim()
    ? record.worktreePath.trim()
    : typeof record.folderPath === "string"
      ? record.folderPath.trim()
      : "";
  if (!storedPath || !isAbsolute(storedPath) || !existsSync(storedPath)) {
    throw new AgentsToZUseControlError(
      "등록 프로젝트의 로컬 폴더가 없거나 현재 단말에서 접근할 수 없습니다.",
      "AGENTSTOZ_USE_PROJECT_FOLDER_UNAVAILABLE",
      409,
    );
  }
  let canonicalPath: string;
  try {
    canonicalPath = realpathSync(storedPath);
    if (!statSync(canonicalPath).isDirectory()) throw new Error("not a directory");
  } catch {
    throw new AgentsToZUseControlError(
      "등록 프로젝트의 로컬 폴더를 확인하지 못했습니다.",
      "AGENTSTOZ_USE_PROJECT_FOLDER_UNAVAILABLE",
      409,
    );
  }
  return {
    projectId,
    projectName: typeof record.name === "string" && record.name.trim() ? record.name.trim() : basename(canonicalPath),
    canonicalPath,
    record,
  };
}

async function runGitHubCliCommand(
  command: string[],
  options: { cwd?: string; timeoutMs?: number } = {},
): Promise<{ ok: boolean; stdout: string; stderr: string; timedOut: boolean }> {
  const proc = Bun.spawn(command, {
    ...(options.cwd ? { cwd: options.cwd } : {}),
    stdout: "pipe",
    stderr: "pipe",
  });
  const stdoutPromise = new Response(proc.stdout).text().catch(() => "");
  const stderrPromise = new Response(proc.stderr).text().catch(() => "");
  let timedOut = false;
  const timeoutId = setTimeout(() => {
    timedOut = true;
    try { proc.kill(); } catch {}
  }, options.timeoutMs ?? 120_000);
  await proc.exited.catch(() => undefined);
  clearTimeout(timeoutId);
  const [stdout, stderr] = await Promise.all([stdoutPromise, stderrPromise]);
  return { ok: !timedOut && proc.exitCode === 0, stdout: stdout.trim(), stderr: stderr.trim(), timedOut };
}

const githubRepositoryCreatesInFlight = new Set<string>();

async function createGitHubRepositoryForRegisteredProject(input: {
  portId: string;
  visibility: GitHubRepositoryVisibility;
}) {
  if (input.visibility !== "private" && input.visibility !== "public") {
    throw new AgentsToZUseControlError(
      "GitHub 공개 범위는 private 또는 public을 명시해야 합니다.",
      "AGENTSTOZ_USE_GITHUB_VISIBILITY_REQUIRED",
    );
  }
  const project = await resolveRegisteredLocalGitHubProject(input.portId);
  if (githubRepositoryCreatesInFlight.has(project.projectId)) {
    throw new AgentsToZUseControlError(
      "이 프로젝트의 GitHub 저장소를 이미 만들고 있습니다.",
      "AGENTSTOZ_USE_GITHUB_CREATE_IN_PROGRESS",
      409,
    );
  }
  githubRepositoryCreatesInFlight.add(project.projectId);
  try {
    return await withAgentsToZUseWorkspaceLease(project.canonicalPath, 'GitHub repository creation', async () => {
      if (githubRepositoryUrls({
      githubUrl: typeof project.record.githubUrl === "string" ? project.record.githubUrl : null,
      githubUrls: Array.isArray(project.record.githubUrls)
        ? project.record.githubUrls.filter((value): value is string => typeof value === "string")
        : null,
    }).length > 0) {
      throw new AgentsToZUseControlError(
        "이 프로젝트에는 이미 GitHub 저장소 주소가 등록되어 있습니다.",
        "AGENTSTOZ_USE_GITHUB_ALREADY_CONNECTED",
        409,
      );
    }
    const gitRoot = await runGitForStatus(project.canonicalPath, ["rev-parse", "--show-toplevel"]);
    if (!gitRoot.ok || normalizeWorktreePath(gitRoot.stdout.trim()) !== normalizeWorktreePath(project.canonicalPath)) {
      throw new AgentsToZUseControlError(
        "등록 프로젝트 폴더가 Git 저장소 루트가 아닙니다. 앱에서 Git 저장소를 먼저 초기화하세요.",
        "AGENTSTOZ_USE_GIT_REPOSITORY_REQUIRED",
        409,
      );
    }
    const head = await runGitForStatus(project.canonicalPath, ["rev-parse", "--verify", "HEAD"]);
    if (!head.ok) {
      throw new AgentsToZUseControlError(
        "GitHub에 올릴 초기 커밋이 없습니다. 먼저 로컬 커밋을 만드세요.",
        "AGENTSTOZ_USE_GIT_COMMIT_REQUIRED",
        409,
      );
    }
    const origin = await runGitForStatus(project.canonicalPath, ["remote", "get-url", "origin"]);
    if (origin.ok && origin.stdout.trim()) {
      throw new AgentsToZUseControlError(
        "이 프로젝트에는 이미 origin 원격 저장소가 있습니다. 기존 원격을 자동 변경하지 않습니다.",
        "AGENTSTOZ_USE_GIT_ORIGIN_EXISTS",
        409,
      );
    }
    const ghPath = resolveGitHubCliPath();
    if (!ghPath) {
      throw new AgentsToZUseControlError(
        "GitHub CLI(gh)가 없습니다. 설치 후 gh auth login을 완료하세요.",
        "AGENTSTOZ_USE_GITHUB_CLI_MISSING",
        503,
      );
    }
    const auth = await runGitHubCliCommand([ghPath, "auth", "status"], { timeoutMs: 15_000 });
    if (!auth.ok || !/Logged in to|✓ Logged in/.test(`${auth.stdout}\n${auth.stderr}`)) {
      throw new AgentsToZUseControlError(
        "GitHub CLI 인증이 필요합니다. AgentsToZ 설정에서 gh 로그인을 완료하세요.",
        "AGENTSTOZ_USE_GITHUB_AUTH_REQUIRED",
        409,
      );
    }
    const repositoryName = githubRepositoryNameFromProject({
      projectName: project.projectName,
      folderName: basename(project.canonicalPath),
      projectId: project.projectId,
    });
    const dirty = await runGitForStatus(project.canonicalPath, ["status", "--porcelain=v1", "--untracked-files=all"]);
    const uncommittedFileCount = dirty.ok && dirty.stdout.trim() ? dirty.stdout.trim().split("\n").length : 0;
    const created = await runGitHubCliCommand([
      ghPath,
      ...githubRepositoryCreateArgs({
        repositoryName,
        folderPath: project.canonicalPath,
        visibility: input.visibility,
      }),
    ], { cwd: project.canonicalPath, timeoutMs: 120_000 });
    const remote = await runGitForStatus(project.canonicalPath, ["remote", "get-url", "origin"]);
    const repositoryUrl = remote.ok ? normalizeGitHubRepositoryUrl(remote.stdout.trim()) : null;
    if (!repositoryUrl) {
      const detail = (created.timedOut
        ? "GitHub 저장소 생성 시간이 초과되었습니다."
        : created.stderr || created.stdout || "GitHub 저장소를 만들지 못했습니다.").slice(0, 800);
      throw new AgentsToZUseControlError(detail, "AGENTSTOZ_USE_GITHUB_CREATE_FAILED", 502);
    }

    let registrationUpdated = false;
    let registrationWarning: string | null = null;
    try {
      const latest = await readPortsFileStrict() as Array<PortRecord & Record<string, unknown>>;
      const current = latest.find(candidate => candidate.id === project.projectId);
      if (!current) throw new Error("생성 후 프로젝트 등록 행을 찾지 못했습니다.");
      const fields = githubRepositoryUrlFields([repositoryUrl, ...githubRepositoryUrls({
        githubUrl: typeof current.githubUrl === "string" ? current.githubUrl : null,
        githubUrls: Array.isArray(current.githubUrls)
          ? current.githubUrls.filter((value): value is string => typeof value === "string")
          : null,
      })]);
      await savePortsData({
        basePorts: latest,
        ports: latest.map(candidate => candidate.id === project.projectId ? { ...candidate, ...fields } : candidate),
        source: "github-repository-create",
      });
      registrationUpdated = true;
    } catch (error) {
      registrationWarning = `원격 저장소는 생성됐지만 AgentsToZ 등록 갱신에 실패했습니다: ${error instanceof Error ? error.message : String(error)}`;
    }

      return {
        projectId: project.projectId,
        projectName: project.projectName,
        repositoryName,
        repositoryUrl,
        visibility: input.visibility,
        pushed: created.ok,
        uncommittedFileCount,
        registrationUpdated,
        warning: registrationWarning
          ?? (!created.ok
            ? "GitHub 저장소와 origin은 생성됐지만 첫 push가 완료되지 않았습니다. 앱에서 Git push를 다시 실행하세요."
            : uncommittedFileCount > 0
              ? `커밋된 이력만 push했습니다. 미커밋 파일 ${uncommittedFileCount}개는 GitHub에 올라가지 않았습니다.`
              : null),
      };
    });
  } finally {
    githubRepositoryCreatesInFlight.delete(project.projectId);
  }
}

async function createAgentsToZUseProject(input: {
  projectName: string;
  workspaceRootId: string;
  projectKind?: "project" | "control-center";
  projectId?: string;
  retainDirectory?: (identity: string) => Promise<void>;
  retainRegistration?: (identity: string) => Promise<void>;
  deferBackup?: boolean;
  expectedRootIdentity?: string;
}) {
  const roots = await agentsToZUseWorkspaceRoots();
  if (roots.length === 0) {
    throw new AgentsToZUseControlError(
      "등록되어 있고 현재 접근 가능한 작업 루트가 없습니다. AgentsToZ 앱에서 작업 루트를 먼저 추가하세요.",
      "AGENTSTOZ_USE_WORKSPACE_ROOT_MISSING",
      409,
    );
  }
  const root = roots.find(candidate => candidate.workspaceRootId === input.workspaceRootId);
  if (!root) {
    throw new AgentsToZUseControlError(
      "등록된 작업 루트 ID가 아닙니다. 작업 루트 목록을 다시 조회하세요.",
      "AGENTSTOZ_USE_WORKSPACE_ROOT_NOT_REGISTERED",
      404,
    );
  }
  const safeProjectName = sanitizeProjectFolderName(input.projectName);
  if (!safeProjectName) {
    throw new AgentsToZUseControlError(
      "프로젝트 이름으로 사용할 수 있는 글자가 없습니다.",
      "AGENTSTOZ_USE_PROJECT_NAME_INVALID",
    );
  }
  const target = resolveProjectStartTarget({
    name: safeProjectName,
    rootPath: root.path,
    roots: [{ id: root.workspaceRootId, name: root.name, path: root.path }],
    homeDir: homedir(),
  });
  if (target.status !== "ok") {
    throw new AgentsToZUseControlError(
      target.status === "error" ? target.error : "작업 루트를 확정하지 못했습니다.",
      target.status === "error" ? target.code : "AGENTSTOZ_USE_WORKSPACE_ROOT_REQUIRED",
      409,
    );
  }
  return withAgentsToZUseWorkspaceLease(target.rootPath, 'AgentsToZ project parent reservation', async () => {
    if (input.expectedRootIdentity && projectLaunchDirectoryIdentity(target.rootPath) !== input.expectedRootIdentity) {
      throw new ProjectLaunchReceiptError('WORKSPACE_ROOT_CHANGED', '선택한 작업 루트가 변경되었습니다. 새 폴더를 만들지 않았습니다.');
    }
    // Re-check inside the parent reservation. The target does not exist yet,
    // so its canonical directory identity cannot be leased before creation.
    if (existsSync(target.folderPath)) {
      throw new AgentsToZUseControlError(
        "같은 이름의 폴더가 작업 루트에 이미 있습니다.",
        "AGENTSTOZ_USE_PROJECT_FOLDER_EXISTS",
        409,
      );
    }

    const projectId = input.projectId ?? crypto.randomUUID();
    let registrationCommitted = false;
    let memory: ReturnType<typeof initializeProjectMemory> | null = null;
    let gitInitialized = false;
    let initialCommitCreated = false;
    let gitWarning: string | null = null;
    let createdWorkspaceLease: WorkspaceDirectoryLease | null = null;
    try {
      mkdirSync(target.folderPath, { recursive: false });
      await input.retainDirectory?.(projectLaunchDirectoryIdentity(target.folderPath));
      // Reserve the newly materialized directory before its plain→Git identity
      // transition and keep that directory component through registration and
      // the first memory backup. The parent reservation only protects naming.
      createdWorkspaceLease = await acquireManagedWorkspaceDirectoryLease(target.folderPath);
      const initProc = Bun.spawn([GIT_PATH, "init"], {
        cwd: target.folderPath,
        stdout: "pipe",
        stderr: "pipe",
      });
      await initProc.exited;
      if (initProc.exitCode === 0) {
        gitInitialized = true;
        await promoteManagedWorkspaceDirectoryLease(createdWorkspaceLease);
      } else {
        gitWarning = (await new Response(initProc.stderr).text()).trim() || "Git 저장소를 초기화하지 못했습니다.";
      }

      memory = initializeProjectMemory({
        folderPath: target.folderPath,
        projectName: safeProjectName,
        agent: "codex",
        autoBackup: true,
      });
      if (input.projectKind === "control-center") {
        for (const template of controlCenterTemplateFiles(safeProjectName)) {
          const destination = join(target.folderPath, ...template.relativePath.split("/"));
          mkdirSync(dirname(destination), { recursive: true });
          writeFileSync(destination, template.content, { encoding: "utf8", flag: "wx" });
        }
      }
      // Commit the generated memory agents as part of the first baseline.
      // Committing before memory initialization leaves a brand-new project dirty
      // and immediately blocks the worktree safety gate. Repository workflow
      // metadata lives under .git and can be installed after that baseline.
      if (gitInitialized) {
        const snapshot = await createInitialSnapshotCommit(target.folderPath);
        initialCommitCreated = snapshot.success;
        if (snapshot.success) upgradeRepositoryWorkflow(target.folderPath);
        else gitWarning = snapshot.error || "초기 커밋을 만들지 못했습니다.";
      }
      const registered = await readPortsFileStrict();
      await savePortsData({
        basePorts: registered,
        ports: [{
          id: projectId,
          name: safeProjectName,
          folderPath: memory.projectRoot,
          category: "프로젝트",
          description: "AgentsToZ USE 채널에서 만든 프로젝트",
        } as PortRecord, ...registered],
        source: "agentstoz-use-create-project",
      });
      registrationCommitted = true;
      await input.retainRegistration?.(projectLaunchDirectoryIdentity(target.folderPath));
      await saveLastVisitData(projectId, Date.now());
    } catch (error) {
      // Registration is the commit point. Receipt or auxiliary failures must
      // never move a directory that the project list already references.
      if (!registrationCommitted && existsSync(target.folderPath)) {
        const failedRoot = join(target.rootPath, ".agentstoz-failed");
        try {
          mkdirSync(failedRoot, { recursive: true });
          renameSync(target.folderPath, join(failedRoot, `${target.folderName}-${Date.now()}`));
        } catch { /* preserve the original failure and leave recoverable data in place */ }
      }
      if (createdWorkspaceLease) {
        releaseManagedWorkspaceLease(createdWorkspaceLease, 'AgentsToZ project creation failure');
        createdWorkspaceLease = null;
      }
      throw new AgentsToZUseControlError(
        error instanceof Error ? error.message : String(error),
        "AGENTSTOZ_USE_PROJECT_CREATE_FAILED",
        500,
      );
    }

    let backupSucceeded = false;
    let backupWarning: string | null = null;
    try {
      if (input.deferBackup) {
        backupWarning = "프로젝트와 로컬 기억이 준비됐습니다. 원격 백업은 백그라운드에서 진행합니다.";
      } else {
      const backup = await pushProjectMemory({
        portalDataFile: PORTAL_DATA_FILE,
        folderPath: memory!.projectRoot,
        projectName: safeProjectName,
      });
      backupSucceeded = backup.success === true && backup.contentBackedUp === true;
      if (!backupSucceeded) backupWarning = "프로젝트는 생성됐지만 장기기억 원격 백업은 완료되지 않았습니다.";
      }
    } catch (error) {
      backupWarning = `프로젝트는 생성됐지만 장기기억 원격 백업에 실패했습니다: ${error instanceof Error ? error.message : String(error)}`;
    }

    const result = {
      projectId,
      projectName: safeProjectName,
      memoryId: memory!.config!.memoryId,
      workspaceRoot: agentsToZUseWorkspaceRootResponse(root),
      git: { initialized: gitInitialized, initialCommitCreated, warning: gitWarning },
      memory: { initialized: true, backupSucceeded, warning: backupWarning },
      projectKind: input.projectKind ?? "project",
    };
    if (createdWorkspaceLease) {
      releaseManagedWorkspaceLease(createdWorkspaceLease, 'AgentsToZ project creation');
      createdWorkspaceLease = null;
    }
    return result;
  });
}

async function connectAgentsToZUseBuzzChannel(input: {
  portId: string;
  channelId: string;
  channelName?: string | null;
}) {
  const registered = await resolveRegisteredUseProject(input.portId);
  const channelId = normalizeBuzzChannelId(input.channelId);
  const relayUrl = loadBuzzProjectSettings(BUZZ_PROJECT_SETTINGS_FILE).relayUrl;
  let channelName = input.channelName
    ? normalizeBuzzChannelName(input.channelName)
    : `Buzz ${channelId.slice(0, 8)}`;
  let verifiedAt: string | null = null;
  let verificationProblem: { code: string; message: string } | null = null;
  if (resolveBuzzCliPath()) {
    try {
      const channel = listBuzzChannels(relayUrl).find(candidate => candidate.channelId === channelId);
      if (!channel) {
        throw new BuzzProjectError(
          "인증된 로컬 Buzz relay에서 현재 channel UUID를 찾지 못했습니다.",
          "BUZZ_CHANNEL_NOT_FOUND",
          404,
        );
      }
      channelName = channel.name;
      verifiedAt = new Date().toISOString();
    } catch (error) {
      if (!(error instanceof BuzzProjectError)
        || !["BUZZ_CLI_AUTH_REQUIRED", "BUZZ_RELAY_UNREACHABLE", "BUZZ_CLI_NOT_FOUND"].includes(error.code)) {
        throw error;
      }
      verificationProblem = { code: error.code, message: error.message };
    }
  } else {
    verificationProblem = {
      code: "BUZZ_CLI_NOT_FOUND",
      message: "Buzz CLI가 없어 context의 현재 channel UUID를 독립 검증하지 못했습니다.",
    };
  }
  const route = { platform: "buzz", chatId: relayUrl, threadId: channelId };
  const existingRoute = await getProjectMemoryThreadBinding(PROJECT_MEMORY_THREAD_BINDINGS_FILE, route);
  if (existingRoute && existingRoute.projectId !== registered.projectId) {
    throw new BuzzProjectError(
      "현재 Buzz 채널은 이미 다른 AgentsToZ 프로젝트와 연결되어 있습니다. 앱에서 기존 연결을 먼저 확인하세요.",
      "BUZZ_CHANNEL_ALREADY_BOUND",
      409,
    );
  }

  return withAgentsToZUseWorkspaceLease(registered.canonicalPath, 'Buzz project memory connection', async () => {
    let memoryInitialized = false;
    let memoryId = registered.memoryId;
    let canonicalPath = registered.canonicalPath;
    if (!memoryId) {
      const initialized = initializeProjectMemory({
        folderPath: registered.canonicalPath,
        projectName: registered.projectName,
        agent: "codex",
        autoBackup: true,
      });
      if (!initialized.config?.memoryId) {
        throw new ProjectMemoryError(
          "프로젝트 장기기억을 초기화했지만 memory ID를 확인하지 못했습니다.",
          "PROJECT_MEMORY_NOT_INITIALIZED",
        );
      }
      memoryInitialized = true;
      memoryId = initialized.config.memoryId;
      canonicalPath = initialized.projectRoot;
    }

    let memoryBackupSucceeded = false;
    let memoryBackupWarning: string | null = null;
    if (memoryInitialized) {
      try {
        const backup = await pushProjectMemory({
          portalDataFile: PORTAL_DATA_FILE,
          folderPath: canonicalPath,
          projectName: registered.projectName,
        });
        memoryBackupSucceeded = backup.success === true && backup.contentBackedUp === true;
        if (!memoryBackupSucceeded) memoryBackupWarning = "DEV 장기기억은 만들었지만 원격 백업은 완료되지 않았습니다.";
      } catch (error) {
        memoryBackupWarning = `DEV 장기기억은 만들었지만 원격 백업에 실패했습니다: ${error instanceof Error ? error.message : String(error)}`;
      }
    }

    const project: RegisteredBuzzProject = {
      projectId: registered.projectId,
      projectName: registered.projectName,
      canonicalPath,
      memoryId,
    };
    const binding = await bindBuzzProjectChannel({
      project,
      relayUrl,
      channelId,
      channelName,
      verifiedAt,
    });
    return {
      projectId: project.projectId,
      projectName: project.projectName,
      memoryId: project.memoryId,
      memory: {
        initialized: true,
        createdNow: memoryInitialized,
        backupSucceeded: memoryInitialized ? memoryBackupSucceeded : null,
        warning: memoryBackupWarning,
      },
      channel: {
        channelId: binding.threadId,
        channelName: binding.threadName ?? channelName,
        verified: verifiedAt !== null,
        verificationProblem,
      },
    };
  });
}

function openAgentsToZDashboard(): void {
  if (process.platform !== "darwin") {
    throw new AgentsToZUseControlError(
      "이 버전의 AgentsToZ 화면 열기는 macOS에서만 지원합니다.",
      "AGENTSTOZ_USE_DASHBOARD_UNSUPPORTED",
      409,
    );
  }
  const appPath = join("/Applications", AGENTSTOZ_APP_NAME);
  if (!existsSync(appPath)) {
    throw new AgentsToZUseControlError(
      "설치된 AgentsToZ 앱을 찾지 못했습니다.",
      "AGENTSTOZ_USE_DASHBOARD_NOT_INSTALLED",
      404,
    );
  }
  const opened = Bun.spawnSync(["/usr/bin/open", appPath], { stdout: "ignore", stderr: "pipe", timeout: 5_000 });
  if (!opened.success) {
    throw new AgentsToZUseControlError(
      opened.stderr?.toString().trim() || "AgentsToZ 앱을 열지 못했습니다.",
      "AGENTSTOZ_USE_DASHBOARD_OPEN_FAILED",
      500,
    );
  }
}

let agentsToZUseWorkroomNavigation: {
  nonce: string;
  targetId: string;
  agent: 'codex' | 'claude' | 'hermes' | 'agy';
  sessionId: string;
  expiresAt: number;
} | null = null;

async function nodeOrcaManagedWorktreePathsUnlocked(
  cli: string,
): Promise<{ available: boolean; paths: string[]; stale?: boolean }> {
  if (orcaWorktreeCache && Date.now() - orcaWorktreeCache.at < ORCA_WORKTREE_CACHE_MS) {
    return { available: true, paths: orcaWorktreeCache.paths };
  }
  // stale-while-error: 만료된 캐시라도 갖고 있으면, 조회 실패 시 그걸 그대로 돌려준다.
  // Orca 데몬이 잠깐 바쁠 때(= 사용자가 워크트리에서 AI를 띄우는 바로 그 순간) 배지가
  // 통째로 사라지는 것을 막는 것이 목적. 워크트리 경로는 초 단위로 변하지 않는다.
  const staleFallback = orcaWorktreeCache
    ? { available: true, paths: orcaWorktreeCache.paths, stale: true }
    : { available: false, paths: [] as string[] };
  // 읽기 전용 조회지만 데몬 부하 시 1회성 실패가 잦아 2회까지 짧은 백오프로 재시도한다.
  const r = await nodeOrcaRunJsonRetry(cli, ['worktree', 'list'], { attempts: 2, backoffMs: 400, timeoutMs: 8000 });
  if (!r.ok) return staleFallback;
  const items: any[] = Array.isArray(r.result?.worktrees) ? r.result.worktrees : [];
  const paths = items
    .map((w) => (typeof w?.path === 'string' ? w.path : null))
    .filter((p): p is string => !!p)
    .map((p) => { try { return realpathSync(p); } catch { return p; } });
  orcaWorktreeCache = { at: Date.now(), paths };
  return { available: true, paths };
}

async function orcaManagedWorktreePaths(): Promise<{ available: boolean; paths: string[]; stale?: boolean }> {
  if (orcaWorktreeCache && Date.now() - orcaWorktreeCache.at < ORCA_WORKTREE_CACHE_MS) {
    return { available: true, paths: orcaWorktreeCache.paths };
  }
  // 목록 조회도 terminal create/send와 동일한 Orca CLI 프로세스를 사용한다. 앱 부팅 시
  // 여러 UI 요청이 동시에 들어오면 Bun.spawnSync(osascript)가 겹쳐 Bun 자체가 SIGSEGV로
  // 종료된 실측 사례가 있으므로 반드시 전역 락 안에서 실행한다. 락을 기다리는 동안 앞선
  // 요청이 캐시를 채웠을 수 있어 안에서 한 번 더 확인해 중복 CLI 호출도 제거한다.
  return withOrcaLock(async () => {
    if (orcaWorktreeCache && Date.now() - orcaWorktreeCache.at < ORCA_WORKTREE_CACHE_MS) {
      return { available: true, paths: orcaWorktreeCache.paths };
    }
    const cli = resolveOrcaCli();
    if (!cli) {
      return orcaWorktreeCache
        ? { available: true, paths: orcaWorktreeCache.paths, stale: true }
        : { available: false, paths: [] };
    }
    return nodeOrcaManagedWorktreePathsUnlocked(cli);
  });
}

/** 확정적 실패(재시도해도 결과가 같음) — repo 등록 거부 등. 이 패턴이면 즉시 반환하고 재시도 안 함. */
const ORCA_TERMINAL_ERROR_RE = /not a valid git repository/i;

/** 데몬 부하로 인한 일시적 컨텐션(osascript/Apple Event 직렬화, 터미널 핸들 지연 등)을
 *  흡수하는 재시도 래퍼. 실측: 동시 요청 시 단일 CLI 호출이 정상 0.6~1.6s에서
 *  드물게 7~10s까지 튀며, 타임아웃/일시 실패로 이어짐 — 확정적 에러가 아니면 백오프 재시도. */
async function nodeOrcaRunJsonRetry(
  cli: string,
  args: string[],
  opts?: { timeoutMs?: number; attempts?: number; backoffMs?: number },
): Promise<{ ok: boolean; error: string; result: any }> {
  const attempts = opts?.attempts ?? 3;
  const backoffMs = opts?.backoffMs ?? 900;
  const timeoutMs = opts?.timeoutMs ?? 25000;
  let last = await nodeOrcaRunJson(cli, args, timeoutMs);
  for (let i = 1; i < attempts && !last.ok && !ORCA_TERMINAL_ERROR_RE.test(last.error); i++) {
    await new Promise((res) => setTimeout(res, backoffMs * i));
    last = await nodeOrcaRunJson(cli, args, timeoutMs);
  }
  return last;
}

/** Orca 앱 실행 + 런타임 대기 (`orca open`은 멱등 — 이미 떠 있으면 ~150ms에 반환)
 *
 *  기본 예산은 20s x 2회. 이미 떠 있으면 어차피 첫 시도가 곧바로 끝나므로 비용이 없고,
 *  콜드 스타트(부팅/종료 직후 첫 클릭)에서는 앱 기동을 기다릴 여지를 남긴다.
 *  5s 단발은 콜드 스타트를 못 버텨 사용자의 주 동선이 첫 클릭에서 실패했고,
 *  30s x 3회(=90s)는 Bun.serve idleTimeout과 같아 요청이 통째로 끊겼다. */
async function ensureOrcaReady(
  cli: string,
  opts: { timeoutMs?: number; attempts?: number; backoffMs?: number } = {},
): Promise<{ ok: boolean; error: string }> {
  const r = await nodeOrcaRunJsonRetry(cli, ['open'], {
    timeoutMs: opts.timeoutMs ?? 20000,
    attempts: opts.attempts ?? 2,
    backoffMs: opts.backoffMs ?? 500,
  });
  // 실패해도 앱은 앞으로 가져온다 — 콜드 스타트야말로 창이 떠야 하는 상황이고,
  // 사용자가 다시 눌렀을 때 성공할 확률을 높인다.
  if (!IS_WIN) nodeSpawnSync('open', ['-a', 'Orca'], { stdio: 'pipe' });
  if (!r.ok) {
    return {
      ok: false,
      error: 'Orca를 실행하는 중입니다. 앱 창이 뜨면 다시 시도해주세요.'
        + `\n(${r.error})`,
    };
  }
  return { ok: true, error: '' };
}

/** repo add — 멱등 (이미 등록된 경로면 기존 repo 반환). 비 git 폴더면 명확한 안내. */
async function orcaEnsureRepo(
  cli: string,
  repoPath: string,
  opts: { timeoutMs?: number; attempts?: number } = {},
): Promise<{ ok: boolean; error: string }> {
  const r = await nodeOrcaRunJsonRetry(cli, ['repo', 'add', '--path', repoPath], {
    timeoutMs: opts.timeoutMs,
    attempts: opts.attempts,
  });
  if (r.ok) return { ok: true, error: '' };
  if (ORCA_TERMINAL_ERROR_RE.test(r.error)) {
    return { ok: false, error: `Orca는 git 저장소만 지원합니다 (${repoPath})\n일반 폴더는 cmux/iterm 터미널을 사용하세요.` };
  }
  return { ok: false, error: `Orca repo 등록 실패: ${r.error}` };
}

/** terminal send 직전 준비 대기 — 고정 sleep(300ms)은 데몬이 느릴 때 입력이 유실되고
 *  빠를 때는 불필요한 지연이 된다. `terminal read`로 출력이 잡힐 때까지 200ms 간격으로
 *  최대 10회(총 ~2.5s) 폴링하고, 준비되지 않아도 그냥 send로 진행한다.
 *  → 폴링 실패가 요청 실패로 이어지지 않는다. 새 macOS/Linux AI 탭은 셸 초기화와
 *  입력 전송 사이의 OSC 응답 경쟁을 피하려고 `terminal create --command`를 사용하므로
 *  이 폴링은 일반 터미널과 Windows 호환 경로에만 남는다. */
async function waitOrcaTerminalReady(cli: string, handle: string, maxWaitMs = 2500): Promise<void> {
  const started = Date.now();
  for (let i = 0; i < 10; i++) {
    if (Date.now() - started >= maxWaitMs) return;
    const r = await nodeOrcaRunJson(cli, ['terminal', 'read', '--terminal', handle], 3000);
    const res: any = r.result;
    const text = typeof res === 'string'
      ? res
      : (res?.output ?? res?.tail ?? res?.terminal?.output ?? res?.terminal?.tail ?? '');
    if (r.ok && String(text ?? '').trim()) return;
    await new Promise((done) => setTimeout(done, 200));
  }
}

/**
 * Cmd+T는 공식 문서상 현재 worktree에 terminal을 만들기 때문에 사용하지 않는다.
 * Orca가 제공하는 global-floating-terminal selector로 전용 Floating tab을 직접 만든다.
 */
async function createOrcaFloatingTerminal(
  cli: string,
  title: string,
  initialCommand: string | null = null,
): Promise<{ ok: boolean; handle?: string; worktreeId?: string; hostPlatform?: string; error: string }> {
  const args = [
    'terminal', 'create',
    '--worktree', ORCA_FLOATING_WORKTREE_SELECTOR,
    '--title', title,
    ...(initialCommand ? ['--command', initialCommand] : []),
    // Orca 1.4.180 no longer makes a newly created Floating tab active unless
    // focus is explicit. Without this the terminal and agent start correctly,
    // but the previously selected project's tab stays in front and the launch
    // looks like it did nothing.
    '--focus',
  ];
  const created = await nodeOrcaRunJsonRetry(cli, args, { attempts: 3, backoffMs: 700 });
  if (!created.ok) return { ok: false, error: `Orca Floating Terminal 생성 실패: ${created.error}` };
  const handle = created.result?.terminal?.handle;
  const worktreeId = created.result?.terminal?.worktreeId;
  if (typeof handle !== 'string' || !handle.trim() || worktreeId !== ORCA_FLOATING_WORKTREE_ID) {
    return { ok: false, error: 'Orca가 전용 Floating Terminal 핸들을 반환하지 않았습니다. 일반 프로젝트 터미널에는 명령을 보내지 않았습니다.' };
  }
  await waitOrcaTerminalReady(cli, handle, 3000);
  return { ok: true, handle, worktreeId, hostPlatform: created.result?.terminal?.hostPlatform, error: '' };
}

type OrcaListedTerminal = {
  handle: string;
  hostPlatform?: string;
};

type OrcaFloatingTerminalLookup = {
  terminal: OrcaListedTerminal | null;
  error: string | null;
};

/**
 * `terminal list` has varied slightly between Orca releases (`terminals` vs.
 * nested terminal objects). Walk the JSON defensively, but accept only a tab
 * with our private title marker and the Floating Workspace worktree id.
 */
function findManagedOrcaFloatingTerminal(
  result: unknown,
  agent: string,
  folderPath: string,
  legacyTitle: string,
): OrcaListedTerminal | null {
  let latestMatch: OrcaListedTerminal | null = null;
  const legacyMatches: OrcaListedTerminal[] = [];
  const visit = (value: unknown): void => {
    if (Array.isArray(value)) {
      for (const entry of value) visit(entry);
      return;
    }
    if (!value || typeof value !== 'object') return;
    const record = value as Record<string, unknown>;
    const handle = record.handle;
    const worktreeId = record.worktreeId;
    if (typeof handle === 'string' && handle.trim() && worktreeId === ORCA_FLOATING_WORKTREE_ID
      && isLiveOrcaFloatingTerminalRecord(record)) {
      const candidate = {
        handle,
        hostPlatform: typeof record.hostPlatform === 'string' ? record.hostPlatform : undefined,
      };
      if (isOrcaManagedFloatingTerminal(record.title, agent, folderPath)) {
        latestMatch = candidate;
      } else if (record.title === legacyTitle) {
        legacyMatches.push(candidate);
      }
    }
    for (const child of Object.values(record)) visit(child);
  };
  visit(result);
  // Before the marker existed, AgentsToZ used only "project · agent" titles.
  // Reuse an old tab only when that legacy title occurs exactly once: it is a
  // migration aid, never a command target, and avoids guessing among collisions.
  return latestMatch ?? (legacyMatches.length === 1 ? legacyMatches[0]! : null);
}

/** Find one exact terminal handle in a `terminal show` response. The response
 * shape has changed across Orca releases, so use the same defensive walk as
 * terminal list, while requiring the global Floating Workspace worktree. */
function findOrcaFloatingTerminalByHandle(
  result: unknown,
  expectedHandle: string,
): OrcaListedTerminal | null {
  let match: OrcaListedTerminal | null = null;
  const visited = new WeakSet<object>();
  const visit = (value: unknown): void => {
    if (Array.isArray(value)) {
      for (const entry of value) visit(entry);
      return;
    }
    if (!value || typeof value !== 'object') return;
    if (visited.has(value)) return;
    visited.add(value);
    const record = value as Record<string, unknown>;
    if (record.handle === expectedHandle && record.worktreeId === ORCA_FLOATING_WORKTREE_ID
      && isLiveOrcaFloatingTerminalRecord(record)) {
      match = {
        handle: expectedHandle,
        hostPlatform: typeof record.hostPlatform === 'string' ? record.hostPlatform : undefined,
      };
      return;
    }
    for (const child of Object.values(record)) visit(child);
  };
  visit(result);
  return match;
}

async function findExistingOrcaFloatingTerminal(
  cli: string,
  agent: string,
  folderPath: string,
  legacyTitle: string,
): Promise<OrcaFloatingTerminalLookup> {
  const listed = await nodeOrcaRunJsonRetry(cli, [
    'terminal', 'list',
    '--limit', String(ORCA_CONTEXT_TERMINAL_LIMIT),
  ], { attempts: 2, backoffMs: 500, timeoutMs: 8000 });
  if (!listed.ok) return { terminal: null, error: listed.error };
  return {
    terminal: findManagedOrcaFloatingTerminal(listed.result, agent, folderPath, legacyTitle),
    error: null,
  };
}

/** 해당 Orca 프로젝트/워크트리 안에 일반 터미널을 만든다. */
async function createOrcaWorktreeTerminal(
  cli: string,
  title: string,
  worktreePath: string,
  initialCommand: string | null = null,
): Promise<{ ok: boolean; handle?: string; worktreeId?: string; hostPlatform?: string; error: string }> {
  const args = [
    'terminal', 'create',
    '--worktree', `path:${worktreePath}`,
    '--title', title,
    ...(initialCommand ? ['--command', initialCommand] : []),
    '--focus',
  ];
  const created = await nodeOrcaRunJsonRetry(cli, args, { attempts: 3, backoffMs: 700 });
  if (!created.ok) return { ok: false, error: `Orca 워크트리 터미널 생성 실패: ${created.error}` };
  const handle = created.result?.terminal?.handle;
  const worktreeId = created.result?.terminal?.worktreeId;
  if (typeof handle !== 'string' || !handle.trim() || worktreeId === ORCA_FLOATING_WORKTREE_ID) {
    return { ok: false, error: 'Orca가 워크트리 내부 터미널 핸들을 반환하지 않았습니다. Floating Workspace에는 명령을 보내지 않았습니다.' };
  }
  await waitOrcaTerminalReady(cli, handle, 3000);
  return { ok: true, handle, worktreeId, hostPlatform: created.result?.terminal?.hostPlatform, error: '' };
}

/** `terminal switch`/`tab show`는 Floating Workspace가 최소화된 경우 패널을 열지 않는다.
 *  실제 Orca 접근성 상태를 읽고 닫힌 경우에만 공식 computer click으로 표시한다. */
async function revealOrcaFloatingWorkspace(cli: string): Promise<{ ok: boolean; error: string }> {
  const maximizeWithMacShortcut = (): { ok: boolean; error: string } => {
    if (IS_WIN) {
      return { ok: false, error: 'Orca 화면 제어 API를 사용할 수 없습니다.' };
    }
    // Orca의 macOS 기본 `floatingWorkspace.maximize` 단축키다. toggle이 아니므로
    // 이미 열린 패널을 실수로 닫지 않는다. CLI computer 런타임이 비활성인 앱에서도 동작한다.
    const script = [
      'tell application "Orca" to activate',
      'delay 0.15',
      'tell application "System Events" to keystroke "a" using {command down, option down, shift down}',
    ].join('\n');
    const result = nodeSpawnSync('osascript', ['-e', script], {
      encoding: 'utf8',
      timeout: 5000,
      env: { ...process.env, PATH: '/usr/bin:/bin:/usr/sbin:/sbin' },
    });
    if (result.status === 0) return { ok: true, error: '' };
    const detail = String(result.stderr || result.stdout || result.error?.message || 'unknown').trim();
    const permissionDenied = /1002|not allowed to send keystrokes|assistive access/i.test(detail);
    if (permissionDenied) {
      nodeSpawnSync('/usr/bin/open', ['x-apple.systempreferences:com.apple.preference.security?Privacy_Accessibility'], {
        stdio: 'ignore',
        timeout: 3000,
      });
    }
    return {
      ok: false,
      error: `Orca 플로팅 최대화 단축키 전송 실패: ${detail}. macOS 손쉬운 사용 설정${permissionDenied ? '을 열었습니다. ' : '에서 '}AgentsToZ_byCS를 허용해주세요.`,
    };
  };

  const readState = async () => nodeOrcaRunJsonRetry(cli, [
    'computer', 'get-app-state',
    '--app', 'Orca',
    '--restore-window',
    '--no-screenshot',
  ], { attempts: 2, backoffMs: 300, timeoutMs: 8000 });

  const before = await readState();
  if (!before.ok) {
    const fallback = maximizeWithMacShortcut();
    return fallback.ok ? fallback : { ok: false, error: `Orca 화면 상태 확인 실패: ${before.error}; ${fallback.error}` };
  }
  const visibility = inspectOrcaFloatingVisibility(before.result);
  if (visibility.open) return { ok: true, error: '' };
  if (visibility.toggleElementIndex === null) {
    const fallback = maximizeWithMacShortcut();
    return fallback.ok ? fallback : { ok: false, error: `Orca에서 “Show floating workspace” 버튼을 찾지 못했습니다. ${fallback.error}` };
  }

  const clicked = await nodeOrcaRunJsonRetry(cli, [
    'computer', 'click',
    '--app', 'Orca',
    '--element-index', String(visibility.toggleElementIndex),
    '--restore-window',
    '--no-screenshot',
  ], { attempts: 2, backoffMs: 300, timeoutMs: 8000 });
  if (!clicked.ok) {
    const fallback = maximizeWithMacShortcut();
    return fallback.ok ? fallback : { ok: false, error: `Orca 플로팅 패널 표시 실패: ${clicked.error}; ${fallback.error}` };
  }

  const after = await readState();
  if (!after.ok || !inspectOrcaFloatingVisibility(after.result).open) {
    return { ok: false, error: 'Orca 터미널은 생성됐지만 플로팅 패널이 열린 것을 확인하지 못했습니다.' };
  }
  return { ok: true, error: '' };
}

/** Orca.app이 없을 때 — 설치를 "시작"시켜 준다. Orca CLI는 앱 번들에만 포함되어
 *  있고 정식 배포 채널(brew cask 'orca'는 완전히 다른 앱 — plotly의 이미지 툴)이
 *  없으므로 headless 자동 설치는 불가능. 대신 공식 다운로드 페이지를 자동으로 열어
 *  사용자가 바로 설치를 이어갈 수 있게 한다 (파일 다운로드/실행은 사용자가 직접). */
function bootstrapOrcaInstall(): string {
  if (IS_WIN) {
    nodeSpawnSync('cmd', ['/c', 'start', 'https://www.onorca.dev/download'], { stdio: 'pipe' });
  } else {
    nodeSpawnSync('open', ['https://www.onorca.dev'], { stdio: 'pipe' });
  }
  return 'Orca가 설치되지 않아 다운로드 페이지를 열었습니다 (https://www.onorca.dev/download).\n설치 후 다시 시도해주세요.';
}

/** WSL distro 목록 캐시 (빈 결과도 캐시해서 registry 반복 쿼리 방지) */
let _cachedDistros: string[] | null = null;
let _distrosCached = false;

/** WSL registry에서 distro 목록 조회 (reg.exe 사용 — powershell보다 훨씬 빠르고 안정적) */
function listWslDistros(): string[] {
  if (_distrosCached) return _cachedDistros ?? [];
  const r = nodeSpawnSync('reg', ['query', 'HKCU\\Software\\Microsoft\\Windows\\CurrentVersion\\Lxss', '/s', '/v', 'DistributionName'],
    { timeout: 5000, stdio: 'pipe' });
  const stdout = r.stdout?.toString('utf8') ?? '';
  if (r.status !== 0 || r.error) {
    console.error('[listWslDistros] failed:', { status: r.status, error: r.error?.message });
    _cachedDistros = []; _distrosCached = true;
    return [];
  }
  // reg output format: "    DistributionName    REG_SZ    <name>"
  const distros = [...stdout.matchAll(/DistributionName\s+REG_SZ\s+(.+)/g)]
    .map((m) => (m[1] ?? '').trim())
    .filter((n: string) => n && !n.toLowerCase().includes('docker'));
  devLog('[listWslDistros] found:', distros);
  _cachedDistros = distros;
  _distrosCached = true;
  return distros;
}

/** docker-desktop 제외한 WSL distro 이름 반환 (bash 테스트 없이 목록만 확인 — 빠름) */
function findWslDistro(): string | null {
  const distros = listWslDistros();
  return distros[0] ?? null;
}

/** 터미널/탭 타이틀: ⚡️ tmux+bypass  🔷🆕 tmux+fresh  🔷 tmux  🛡️ bypass  🪟 normal */
function buildWindowTitle(sessionName: string, worktreePath?: string | null, tags?: string | string[] | null, branchHint?: string | null): string {
  const wtRaw = worktreePath?.split(',')[0]?.trim();
  const wtName = branchHint || (wtRaw ? wtRaw.split(/[\\/]/).filter(Boolean).pop() : undefined);
  // Strip "-branchName" suffix from sessionName: "project-design" → "project \u203A design"
  const displaySession = wtName && sessionName.endsWith(`-${wtName}`)
    ? sessionName.slice(0, -(wtName.length + 1))
    : sessionName;
  const base = wtName ? `${displaySession} \u203A ${wtName}` : sessionName;
  const tagList = Array.isArray(tags) ? tags : tags ? [tags] : [];
  const isTmux = tagList.includes('tmux');
  const isBypass = tagList.includes('bypass');
  const isFresh = tagList.includes('fresh');
  let prefix: string;
  if (isTmux && isBypass) prefix = '\u26A1\uFE0F ';
  else if (isTmux && isFresh) prefix = '\u{1F537}\u{1F195} ';
  else if (isTmux) prefix = '\u{1F537} ';
  else if (isBypass) prefix = '\u{1F6E1}\uFE0F ';
  else prefix = '\u{1FA9F} ';
  return `${prefix}${base}`;
}

/** WSL tmux bash 명령 문자열 생성 (외부에서 bash -c로 실행됨 — WSL default PATH가 Windows npm 포함) */
function buildWslTmuxBashCmd(sessionName: string, folderPath: string | null, worktreePath: string | null, fresh: boolean, bypass: boolean): string {
  const rawPath = worktreePath?.split(',')[0]?.trim() || folderPath;
  const wslPath = rawPath ? winToWslPath(rawPath) : null;
  const cdPart = wslPath ? `cd '${escapeSq(wslPath)}' && ` : '';
  // 세션명 규칙은 tmuxSessionName() 한 곳뿐 — 여기 리터럴로 복제하면
  // 워크트리 접미사가 빠져 메인트리와 워크트리가 한 세션을 공유한다.
  const sess = escapeSq(tmuxSessionName(sessionName, worktreePath, bypass));
  const claudeArgs = bypass ? 'claude --dangerously-skip-permissions' : 'claude';
  // ⚠️ 세미콜론(;) 금지 — wt.exe가 subcommand 구분자로 취급해서 명령줄이 쪼개짐
  // ⚠️ 쌍따옴표(") 금지 — cmd.exe가 \"를 몰라서 명령이 중간에 끊김
  // ⚠️ printf OSC 타이틀 금지 — bash single-quote 안에서 \; 가 literal로 출력되어 터미널에 깨진 문자 남김
  //    → 터미널 타이틀은 `wt --title`로 충분, Claude가 추후 자체 OSC로 덮어씀
  // Safety net: claude 실패 시 tmux 안에서 login shell로 fallback → 에러 메시지 확인 가능
  const inner = `${claudeArgs} || bash -l`;
  if (fresh) {
    // kill-session이 실패해도(세션 없음) 계속 진행하도록 || : 로 감쌈 (세미콜론 대체)
    return `${cdPart}(tmux kill-session -t '${sess}' 2>/dev/null || :) && tmux new-session -s '${sess}' '${inner}'`;
  }
  return `${cdPart}tmux new-session -A -s '${sess}' '${inner}'`;
}

/** Resolved Windows Terminal alias path (cached to avoid `where` per click). */
let _cachedWindowsTerminalPath: string | null | undefined;
function windowsTerminalPath(): string | null {
  if (_cachedWindowsTerminalPath !== undefined) return _cachedWindowsTerminalPath;
  const found = Bun.spawnSync(['where', 'wt.exe'], { stdout: 'pipe', stderr: 'pipe' });
  _cachedWindowsTerminalPath = found.exitCode === 0
    ? found.stdout.toString().split(/\r?\n/).map(line => line.trim()).find(Boolean) ?? null
    : null;
  return _cachedWindowsTerminalPath;
}

let _cachedWindowsProcessSupervisor: string | null | undefined;
function windowsProcessSupervisorScript(): string {
  if (_cachedWindowsProcessSupervisor !== undefined) {
    if (_cachedWindowsProcessSupervisor) return _cachedWindowsProcessSupervisor;
    throw new Error('Windows process supervisor resource를 찾을 수 없습니다. 앱을 다시 빌드하세요.');
  }
  const executableDir = dirname(process.execPath);
  const candidates = [
    process.env.AGENTSTOZ_PROCESS_SUPERVISOR,
    join(import.meta.dir, 'src-tauri', 'resources', 'windows-process-supervisor.ps1'),
    join(import.meta.dir, 'resources', 'windows-process-supervisor.ps1'),
    join(executableDir, 'windows-process-supervisor.ps1'),
    join(executableDir, 'resources', 'windows-process-supervisor.ps1'),
    join(executableDir, '..', 'Resources', 'windows-process-supervisor.ps1'),
  ].filter((value): value is string => Boolean(value));
  _cachedWindowsProcessSupervisor = candidates.find(candidate => existsSync(candidate)) ?? null;
  if (!_cachedWindowsProcessSupervisor) {
    throw new Error('Windows process supervisor resource를 찾을 수 없습니다. 앱을 다시 빌드하세요.');
  }
  return _cachedWindowsProcessSupervisor;
}

function windowsProcessSupervisorAvailable(): boolean {
  if (process.platform !== 'win32') return false;
  try {
    windowsProcessSupervisorScript();
    return true;
  } catch {
    return false;
  }
}

/** WSL tmux 세션 열기 (Windows Terminal 우선, 없으면 cmd 폴백) */
function spawnWslTmux(bashCmd: string, title?: string): void {
  const distro = findWslDistro();
  if (!distro) throw new Error('WSL Ubuntu distro를 찾을 수 없습니다.');
  // bash -c (기본) → WSL의 default PATH가 Windows PATH를 import하므로 npm global(claude.exe 등)도 자동 접근
  // -i (interactive) 플래그는 WSL pty 레이어에서 hang 유발 가능 → 사용 금지
  const wt = windowsTerminalPath();
  const command = wt
    ? [wt, ...(title ? ['--title', title] : []), '--', 'wsl.exe', '-d', distro, '--', 'bash', '-c', bashCmd]
    : ['wsl.exe', '-d', distro, '--', 'bash', '-c', bashCmd];
  // Direct argv + detached console: title/bash values never cross an outer cmd
  // expansion pass, so `%TEMP%` and metacharacters stay literal.
  const child = spawn({ cmd: command, stdout: 'ignore', stderr: 'ignore', detached: true });
  child.unref();
}

/** 포트를 **LISTEN 중인** PID 목록 반환 (Windows/macOS 공용)
 * WHY: Windows에서 PowerShell Get-NetTCPConnection은 기동 오버헤드 ~300-500ms.
 * netstat -ano 파싱은 ~50ms로 6배 빠름.
 *
 * ⚠️ 반드시 리스너만 반환해야 한다. 호출부는 여기서 받은 PID를 자손 트리째
 * SIGKILL 하므로(`killProcessTree`), 포트에 단지 **접속만** 한 프로세스가 섞이면
 * 그것까지 죽는다. `lsof -ti :3001`은 실측으로 앱 자신의 WebKit 렌더러를 함께
 * 반환한다 — 강제 재실행이 자기 UI/서버를 죽여서 진행 중이던 요청이
 * "TypeError: Failed to fetch"로 끊기던 원인이다. dev.ts는 같은 이유로 이미
 * `-sTCP:LISTEN`을 쓰고 있었지만, 정작 stop/force-restart 경로에는 빠져 있었다. */
async function getPidsByPort(port: number): Promise<string[]> {
  // 포트 값 검증 — Supabase 동기화 등 외부 데이터가 들어올 수 있으므로 인젝션 방지
  const p = Number(port);
  if (!Number.isInteger(p) || p < 1 || p > 65535) return [];
  if (IS_WIN) {
    // `-p tcp`는 IPv4만 나열한다 — Vite/Node가 localhost를 [::1]로 바인딩하면
    // 리스너를 통째로 놓쳐 "중지됨"으로 오판하고 stop도 PID를 못 찾는다.
    // 프로토콜 필터 없이 받아 TCP/TCPv6를 모두 본다.
    const proc = spawn({
      cmd: ['netstat', '-ano'],
      stdout: 'pipe', stderr: 'pipe',
    });
    await proc.exited;
    const out = await new Response(proc.stdout).text();
    return windowsListenerPidsForPort(out, p);
  } else {
    const proc = spawn({
      cmd: [LSOF_EXECUTABLE, '-ti', `:${p}`, '-sTCP:LISTEN'],
      stdout: 'pipe', stderr: 'pipe',
    });
    await proc.exited;
    const out = await new Response(proc.stdout).text();
    return out.trim().split('\n').filter(p => p.length > 0);
  }
}

/** LISTEN 중인 모든 TCP 포트를 단 1회 spawn으로 수집 (Windows/macOS 공용).
 * 배경: 프론트의 10초 폴링이 포트당 lsof를 1회씩 spawn(~35개 = 틱당 ~35 spawn)
 * 하면서 장시간 실행 시 메모리/프로세스 압박 — 스냅샷 1회로 전부 응답한다.
 * WHY: Windows에서 PowerShell 대신 netstat 사용 — 기동 오버헤드 6배 감소 (300ms → 50ms). */
async function getListeningPortsSnapshot(): Promise<Set<number>> {
  const listening = new Set<number>();
  try {
    if (IS_WIN) {
      // `-p tcp`는 IPv4 전용 — [::1] 바인딩(Vite 등)을 놓치므로 프로토콜 필터 없이 받는다.
      const proc = spawn({
        cmd: ['netstat', '-ano'],
        stdout: 'pipe', stderr: 'pipe',
      });
      await proc.exited;
      const out = await new Response(proc.stdout).text();
      windowsListeningPorts(out).forEach(port => listening.add(port));
    } else {
      const proc = spawn({ cmd: [LSOF_EXECUTABLE, '-nP', '-iTCP', '-sTCP:LISTEN'], stdout: 'pipe', stderr: 'pipe' });
      await proc.exited;
      const out = await new Response(proc.stdout).text();
      for (const line of out.split('\n')) {
        // NAME 컬럼: *:3001 / 127.0.0.1:5173 / [::1]:8080 (LISTEN) — 마지막 콜론 뒤가 포트
        const m = line.match(/:(\d+)\s+\(LISTEN\)\s*$/);
        if (m) {
          const n = Number(m[1]);
          if (n >= 1 && n <= 65535) listening.add(n);
        }
      }
    }
  } catch (e) {
    console.error('[CheckPortsBatch] listening snapshot failed:', e);
  }
  return listening;
}

async function killWindowsProcessTree(pid: string): Promise<void> {
  const proc = spawn({
    cmd: ['taskkill', '/F', '/T', '/PID', pid],
    stdout: 'pipe',
    stderr: 'pipe',
  });
  const stdout = new Response(proc.stdout).text();
  const stderr = new Response(proc.stderr).text();
  await proc.exited;
  const detail = `${await stdout}\n${await stderr}`.trim();
  if (proc.exitCode !== 0) {
    throw new Error(`taskkill failed for PID ${pid} (exit ${proc.exitCode ?? 'unknown'}): ${detail || 'no diagnostic'}`);
  }
}

/** PID 종료 (Windows/macOS 공용) */
async function killPid(pid: string, force = false): Promise<void> {
  if (IS_WIN) {
    await killWindowsProcessTree(pid);
  } else {
    const sig = force ? '-9' : '-15';
    const p = spawn({ cmd: ['kill', sig, pid], stdout: 'inherit', stderr: 'inherit' });
    await p.exited;
  }
}

/** macOS/Linux: `pgrep -P` BFS로 rootPid의 모든 자손 PID 수집.
 * 루트를 먼저 죽이면 자손이 launchd(1)로 reparent되어 추적 불가하므로,
 * 종료 전에 반드시 트리를 먼저 수집해야 한다. */
async function collectDescendantPids(rootPid: number | string): Promise<string[]> {
  const out: string[] = [];
  let frontier = [String(rootPid)];
  // 안전 상한: 비정상적으로 큰 트리(폭주)에서 무한 루프 방지
  while (frontier.length > 0 && out.length < 4096) {
    const next: string[] = [];
    for (const pid of frontier) {
      try {
        const proc = spawn({ cmd: ['pgrep', '-P', pid], stdout: 'pipe', stderr: 'pipe' });
        await proc.exited;
        const children = (await new Response(proc.stdout).text())
          .trim().split('\n').map(s => s.trim()).filter(s => /^\d+$/.test(s));
        for (const c of children) { out.push(c); next.push(c); }
      } catch { /* pgrep 실패 시 해당 가지 스킵 */ }
    }
    frontier = next;
  }
  return out;
}

/** 프로세스 + 자손 트리 전체 종료 (Windows/macOS 공용).
 * 배경: stop이 lsof로 포트 리스너 PID만 죽이면, .command가 띄운 자식
 * 프로세스들(dev server의 node helper 등)이 살아남아 누적된다.
 * macOS에는 setsid가 없어 프로세스 그룹 분리가 어려우므로,
 * pgrep -P BFS로 자손을 전부 수집한 뒤 SIGTERM → (생존 시) SIGKILL 처리.
 * Windows는 taskkill /T가 트리 종료를 네이티브 지원. */
async function killProcessTree(rootPid: number | string, force = false): Promise<void> {
  const pidStr = String(rootPid);
  if (!/^\d+$/.test(pidStr)) return;
  if (IS_WIN) {
    await killWindowsProcessTree(pidStr);
    return;
  }
  const descendants = await collectDescendantPids(pidStr);
  const all = [pidStr, ...descendants];
  for (const pid of all) await killPid(pid, force);
  if (!force) {
    await new Promise(r => setTimeout(r, 200));
    for (const pid of all) {
      const check = spawn({ cmd: ['kill', '-0', pid], stdout: 'pipe', stderr: 'pipe' });
      await check.exited;
      if (check.exitCode === 0) await killPid(pid, true);
    }
  }
}

/** 폴더/파일 열기 (Windows/macOS 공용)
 * WHY: Windows에서 PowerShell Start-Process 대신 explorer.exe 직접 호출 — 기동 오버헤드 제거 (~300ms → 즉시). */
function openPath(target: string): void {
  if (IS_WIN) {
    const winPath = target.replace(/\//g, '\\');
    spawn({ cmd: ['explorer.exe', winPath], stdout: 'pipe', stderr: 'pipe' });
  } else {
    spawn({ cmd: ['open', target], stdout: 'inherit', stderr: 'inherit' });
  }
}

/**
 * The same open, but with an answer. A phone pressing Finder gets one line back and nothing else,
 * so reporting success from an unchecked spawn is the "가짜 성공" this repo forbids: a path the
 * Finder refused looked identical to one it opened.
 *
 * Follows the terminal-launch contract rather than inventing a second one — a non-zero exit is a
 * real failure, but a deadline overrun is *unverified*, not failure, and the process is left alone
 * because the window may still be on its way. Windows keeps the old behaviour: explorer.exe
 * reports a non-zero exit even when it succeeds, so checking it would invent failures.
 */
async function openPathVerified(target: string): Promise<void> {
  if (IS_WIN) { openPath(target); return; }
  const child = spawn({ cmd: ['open', target], stdout: 'pipe', stderr: 'pipe' });
  let timer: ReturnType<typeof setTimeout> | undefined;
  const exitCode = await Promise.race([
    child.exited,
    new Promise<null>(resolve => { timer = setTimeout(() => resolve(null), 5_000); }),
  ]);
  if (timer) clearTimeout(timer);
  if (exitCode === null) {
    // Reporting success here would rebuild the fake success this exists to remove: the phone gets
    // one line and would read "완료" for a Finder that never came. Opening a folder is idempotent
    // and harmless to repeat, so failing closed costs the user a second tap at worst — unlike a
    // terminal launch, where an unverified repeat opens a second window.
    console.error('[RemoteControl] open 응답이 5초 안에 오지 않았습니다:', target);
    throw new RemoteControlError('ACTION_NOT_VERIFIED', '폴더를 열었는지 확인하지 못했습니다. Mac 화면을 확인하고 필요하면 다시 누르세요.', 409);
  }
  if (exitCode !== 0) {
    throw new RemoteControlError('ACTION_NOT_AVAILABLE', '이 Mac에서 폴더를 열지 못했습니다.', 409);
  }
}

// Resolve claude binary path once at startup.
// GUI 앱 환경에서는 Bun.spawnSync PATH가 제한적이므로 login shell로
// 사용자 셸 프로파일을 로드한 뒤 command -v를 실행한다. 셸이 없는 플랫폼에서는
// Bun.spawnSync가 throw하므로 이 경로가 API 서버 기동 자체를 막아서는 안 된다.
function resolveClaudeThroughLoginShell(shell: string): string | null {
  try {
    const result = Bun.spawnSync([shell, '-l', '-c', 'command -v claude'], {
      env: { ...process.env },
      stdout: 'pipe',
      stderr: 'pipe',
    });
    if (!result.success) return null;
    const candidate = (result.stdout.toString().trim().split(/\r?\n/)[0] ?? '').trim();
    return candidate && existsSync(candidate) ? candidate : null;
  } catch {
    return null;
  }
}

function resolveClaudePath(): string | null {
  const isWin = process.platform === 'win32';
  if (isWin) {
    // Prefer the actual .exe inside the npm package — avoids Unix shebang file and cmd.exe chain.
    // npm install -g places the real binary at: %APPDATA%\npm\node_modules\@anthropic-ai\claude-code\bin\claude.exe
    const npmExe = join(process.env.APPDATA ?? '', 'npm', 'node_modules', '@anthropic-ai', 'claude-code', 'bin', 'claude.exe');
    if (existsSync(npmExe)) return npmExe;
    // Fallback: unwrap claude.cmd → actual .exe (avoids direct .cmd spawn via Bun)
    const npmCmd = join(process.env.APPDATA ?? '', 'npm', 'claude.cmd');
    if (existsSync(npmCmd)) {
      try {
        const content = readFileSync(npmCmd, 'utf8');
        const dir = dirname(npmCmd);
        const match = content.match(/"([^"]+\.exe)"\s*%\*/i);
        if (match?.[1]) {
          const exePath = match[1].replace(/%dp0%/gi, dir);
          const resolved = isAbsolute(exePath) ? exePath : join(dir, exePath);
          if (existsSync(resolved)) return resolved;
        }
      } catch { /* fall through */ }
    }
    // Last resort: where.exe — only accept .exe (skip Unix shebang and .cmd)
    const r = Bun.spawnSync(['where', 'claude'], { env: { ...process.env } });
    for (const line of r.stdout.toString().trim().split(/\r?\n/)) {
      const p = line.trim();
      if (p && p.toLowerCase().endsWith('.exe') && existsSync(p) && !p.includes('WindowsApps')) return p;
    }
    return null;
  }
  // macOS GUI 앱의 기본 로그인 셸은 zsh다. Linux에는 zsh가 기본 설치되지
  // 않을 수 있으므로 macOS에서만 시도하고, 공통 fallback은 bash로 둔다.
  if (process.platform === 'darwin') {
    const fromZsh = resolveClaudeThroughLoginShell('zsh');
    if (fromZsh) return fromZsh;
  }
  const fromBash = resolveClaudeThroughLoginShell('bash');
  if (fromBash) return fromBash;
  // 알려진 고정 경로 탐색 (cmux 번들 포함)
  const home = process.env.HOME ?? '';
  for (const p of [
    '/Applications/cmux.app/Contents/Resources/bin/claude',
    '/opt/homebrew/bin/claude',
    '/usr/local/bin/claude',
    `${home}/.npm-global/bin/claude`,
    `${home}/.npm/bin/claude`,
    `${home}/.local/bin/claude`,
    `${home}/.claude/local/bin/claude`,
  ]) {
    if (p && existsSync(p)) return p;
  }
  return null;
}
const CLAUDE_PATH = resolveClaudePath();

/**
 * One-shot Claude call for short generated text (commit titles, project aliases).
 *
 * Three things here are load-bearing:
 *  1. `--tools ''` disables the agent loop. Without it `claude -p` treats the prompt
 *     as a task, goes off reading the repo, and answers with narration like
 *     "변경 내용을 확인하겠습니다" instead of the one line we asked for — measured
 *     against a real 16KB diff. Tool loops are also what makes these calls slow
 *     enough to hit the timeout.
 *  2. The prompt goes over stdin on every platform, not as an argv entry. `--tools`
 *     is variadic, so a trailing positional prompt gets swallowed by it ("Input must
 *     be provided either through stdin or as a prompt argument"), and argv also has
 *     length limits on Windows.
 *  3. Timeout is tracked with an explicit flag. Bun reports our own `proc.kill()` as
 *     `exitCode === null` + `signalCode === 'SIGTERM'`, but a process terminated by
 *     someone else (an app restart, the OS) surfaces as plain `exit 143`, which the
 *     old inference read as an ordinary failure and reported as a confusing
 *     "AI 메시지 생성 실패 (exit 143)".
 */
async function runClaudePrompt(
  prompt: string,
  opts: { timeoutMs: number; cwd?: string; label: string },
): Promise<{ ok: true; text: string } | { ok: false; error: string }> {
  if (!CLAUDE_PATH) {
    return { ok: false, error: 'claude CLI를 찾을 수 없습니다. Claude Code를 설치했는지 확인해주세요.' };
  }
  const proc = Bun.spawn(
    [CLAUDE_PATH, '--safe-mode', '-p', '--model', 'haiku', '--tools', ''],
    {
      ...(opts.cwd ? { cwd: opts.cwd } : {}),
      env: { ...process.env, ...(IS_WIN ? {} : { PATH: '/opt/homebrew/bin:/usr/local/bin:/usr/bin:/bin' }) },
      stdin: Buffer.from(prompt),
      stdout: 'pipe',
      stderr: 'pipe',
    },
  );
  let timedOut = false;
  const timeoutId = setTimeout(() => { timedOut = true; proc.kill(); }, opts.timeoutMs);
  await proc.exited;
  clearTimeout(timeoutId);
  const text = (await new Response(proc.stdout).text()).trim();
  const stderr = (await new Response(proc.stderr).text()).trim();
  if (proc.exitCode === 0) return { ok: true, text };

  const detail = stderr || text || `(exitCode=${proc.exitCode}, signal=${proc.signalCode ?? 'none'})`;
  // 143 = 128+SIGTERM, 137 = 128+SIGKILL — the process was terminated from outside.
  const killedExternally = !timedOut && (proc.exitCode === 143 || proc.exitCode === 137 || proc.signalCode != null);
  const error = timedOut
    ? `AI 응답 시간 초과 (${Math.round(opts.timeoutMs / 1000)}초): ${detail}`
    : killedExternally
      ? `AI 프로세스가 외부에서 종료되었습니다 (exit ${proc.exitCode}). 앱이나 API 서버가 재시작되지 않았는지 확인 후 다시 시도해주세요: ${detail}`
      : `AI 메시지 생성 실패 (exit ${proc.exitCode}): ${detail}`;
  console.error(`[${opts.label}]`, error);
  return { ok: false, error };
}

// ──────────────── 에이전트 CLI 바이너리 해석 (claude / codex / agy) ────────────────
// agy는 ~/.local/bin/agy 에 설치되는데, 이 경로는
//  - osascript로 넘기는 clean env PATH(/opt/homebrew/bin:/usr/local/bin:/usr/bin:...)
//  - Orca/cmux가 띄우는 셸의 PATH
// 어디에도 없다 → bare `agy`로 실행하면 "command not found"로 조용히 실패한다.
// 그래서 실행 명령 문자열에 바이너리를 박아 넣을 때는 항상 절대경로로 해석해서 넣는다.
const AGENT_BIN_CACHE = new Map<string, string>();

type AgentName = 'claude' | 'codex' | 'agy' | 'hermes';

/** bypass 플래그 — 각 CLI에서 실제 유효한 값 (변경 금지) */
const AGENT_BYPASS_FLAG: Record<AgentName, string> = {
  claude: '--dangerously-skip-permissions',
  codex: '--dangerously-bypass-approvals-and-sandbox',
  agy: '--dangerously-skip-permissions',
  hermes: '',
};

type RunningHermesDesktop = { pid: number; executable: string; command: string };

function runningHermesDesktops(): RunningHermesDesktop[] {
  if (process.platform !== 'darwin') return [];
  const listing = Bun.spawnSync(['ps', 'ax', '-o', 'pid=,command='], {
    stdout: 'pipe', stderr: 'ignore',
  }).stdout.toString();
  const marker = '/Contents/MacOS/Hermes';
  const processes: RunningHermesDesktop[] = [];
  for (const line of listing.split(/\r?\n/)) {
    const markerAt = line.indexOf(marker);
    if (markerAt < 0) continue;
    const prefix = line.slice(0, markerAt + marker.length).trim();
    const match = prefix.match(/^(\d+)\s+(.+)$/);
    if (!match) continue;
    const pid = Number(match[1]);
    const executable = match[2]!;
    if (Number.isInteger(pid) && existsSync(executable)) processes.push({ pid, executable, command: line.trim() });
  }
  return processes;
}

function runningHermesDesktop(): RunningHermesDesktop | null {
  return runningHermesDesktops()[0] ?? null;
}

function runningHermesDesktopForUserData(projectUserData: string): RunningHermesDesktop | null {
  return runningHermesDesktops().find(process => (
    hermesDesktopCommandUsesUserDataDir(process.command, projectUserData)
  )) ?? null;
}

function installedHermesDesktopExecutable(): string | null {
  const running = runningHermesDesktop();
  if (running) return running.executable;
  for (const candidate of hermesDesktopExecutableCandidates(homedir(), process.platform, process.arch)) {
    if (existsSync(candidate)) return candidate;
  }
  return null;
}

type HermesProjectSessionSnapshot =
  | { state: 'found'; session: HermesProjectSessionCandidate }
  | { state: 'none' }
  | { state: 'unavailable' };

type HermesProjectSessionCandidatesSnapshot =
  | { state: 'available'; sessions: HermesProjectSessionCandidate[] }
  | { state: 'unavailable'; sessions: [] };

/** Read only Hermes' compact session rows once; messages and prompts are not read. */
function readHermesProjectSessionCandidates(): HermesProjectSessionCandidatesSnapshot {
  const databasePath = join(homedir(), '.hermes', 'state.db');
  if (!existsSync(databasePath)) return { state: 'available', sessions: [] };
  let database: Database | null = null;
  try {
    database = new Database(databasePath, { readonly: true, create: false });
    const rows = database.query(`
      SELECT id, source, started_at, last_activity_at, cwd, git_repo_root,
             profile_name, archived, hidden
        FROM sessions
       WHERE source = 'desktop'
    `).all() as Array<{
      id: string;
      source: string;
      started_at: number | null;
      last_activity_at: number | null;
      cwd: string | null;
      git_repo_root: string | null;
      profile_name: string | null;
      archived: number | null;
      hidden: number | null;
    }>;
    return { state: 'available', sessions: rows.map(row => ({
      id: row.id,
      source: row.source,
      startedAt: row.started_at,
      lastActivityAt: row.last_activity_at,
      cwd: row.cwd,
      gitRepoRoot: row.git_repo_root,
      profileName: row.profile_name,
      archived: row.archived,
      hidden: row.hidden,
    })) };
  } catch {
    return { state: 'unavailable', sessions: [] };
  } finally {
    try { database?.close(); } catch { /* read-only handle cleanup */ }
  }
}

function readLatestHermesProjectSession(folderPath: string): HermesProjectSessionSnapshot {
  const snapshot = readHermesProjectSessionCandidates();
  if (snapshot.state === 'unavailable') return { state: 'unavailable' };
  const selected = selectLatestHermesProjectSession(folderPath, snapshot.sessions);
  return selected ? { state: 'found', session: selected } : { state: 'none' };
}

async function verifyHermesDesktopRunning(
  readyFile: string,
  projectUserData: string,
  childPid: number,
  timeoutMs = 30_000,
): Promise<boolean> {
  const deadline = Date.now() + timeoutMs;
  while (Date.now() < deadline) {
    const receiver = runningHermesDesktopForUserData(projectUserData);
    try {
      process.kill(childPid, 0);
    } catch {
      if (!receiver) return false;
    }
    try {
      const port = hermesDashboardReadyPort(JSON.parse(readFileSync(readyFile, 'utf8')));
      if (port && receiver) {
        process.kill(receiver.pid, 0);
        const status = await fetch(`http://127.0.0.1:${port}/api/status`, {
          signal: AbortSignal.timeout(1_000),
        });
        if (status.ok) return true;
      }
    } catch { /* wait for Hermes' atomic {port} receipt and live backend */ }
    await Bun.sleep(250);
  }
  return false;
}

function unwrapWindowsAgentShim(shimPath: string, name: AgentName): string | null {
  if (shimPath.toLowerCase().endsWith('.exe') && existsSync(shimPath)) return shimPath;
  const shimDir = dirname(shimPath);
  try {
    const cmdPath = shimPath.toLowerCase().endsWith('.cmd') ? shimPath : `${shimPath}.cmd`;
    if (existsSync(cmdPath)) {
      const content = readFileSync(cmdPath, 'utf8');
      const directExe = content.match(/"([^"]+\.exe)"\s+%\*/i)?.[1];
      if (directExe) {
        const expanded = directExe.replace(/%dp0%/gi, shimDir).replace(/%~dp0/gi, shimDir);
        const resolved = isAbsolute(expanded) ? expanded : resolve(shimDir, expanded);
        if (existsSync(resolved)) return resolved;
      }
    }
  } catch { /* try package-layout candidates below */ }

  if (name === 'codex') {
    const nodeModules = basename(shimDir).toLowerCase() === '.bin' ? dirname(shimDir) : shimDir;
    const arch = process.arch === 'arm64' ? 'aarch64-pc-windows-msvc' : 'x86_64-pc-windows-msvc';
    const pkg = process.arch === 'arm64' ? 'codex-win32-arm64' : 'codex-win32-x64';
    const candidate = join(nodeModules, '@openai', pkg, 'vendor', arch, 'bin', 'codex.exe');
    if (existsSync(candidate)) return candidate;
  }
  return null;
}

const ORCA_AGENT_START_ERROR_RE = /command not found|no such file or directory|cannot execute|permission denied|the system cannot find the path specified|is not recognized as an internal or external command/i;

/** A fresh terminal must not be reported as launched when its shell immediately rejected the command. */
async function verifyOrcaAgentStarted(cli: string, handle: string): Promise<{ ok: boolean; error: string }> {
  for (let attempt = 0; attempt < 4; attempt++) {
    await new Promise((done) => setTimeout(done, 350));
    const read = await nodeOrcaRunJson(cli, ['terminal', 'read', '--terminal', handle], 3000);
    if (!read.ok) continue;
    const terminal = read.result?.terminal ?? read.result;
    const raw = terminal?.tail ?? terminal?.output ?? '';
    const text = Array.isArray(raw) ? raw.join('\n') : String(raw ?? '');
    const match = text.match(ORCA_AGENT_START_ERROR_RE);
    if (match) {
      const tail = text.split(/\r?\n/).slice(-8).join('\n').slice(-1200);
      return { ok: false, error: `${match[0]}\n${tail}` };
    }
    if (text.trim()) return { ok: true, error: '' };
  }
  // Orca accepted the bytes but some full-screen TUIs do not expose readable tail output.
  return { ok: true, error: '' };
}

/** 에이전트 실행 파일 절대경로 해석 (name별 1회만 계산 후 캐시).
 *  Windows Orca는 WSL 셸을 사용하지만 Windows .exe interop은 지원한다. 따라서
 *  PATH에 우연히 들어온 npm shim을 믿지 않고 실제 실행 파일을 찾아 반환한다. */
function resolveAgentBin(name: AgentName): string {
  const cached = AGENT_BIN_CACHE.get(name);
  if (cached) return cached;
  if (process.platform === 'win32') {
    const appData = process.env.APPDATA ?? '';
    const localAppData = process.env.LOCALAPPDATA ?? '';
    const userProfile = process.env.USERPROFILE ?? '';
    const knownCandidates: Record<AgentName, string[]> = {
      claude: [
        join(userProfile, '.local', 'bin', 'claude.exe'),
        join(appData, 'npm', 'node_modules', '@anthropic-ai', 'claude-code', 'bin', 'claude.exe'),
        join(appData, 'npm', 'node_modules', '@anthropic-ai', 'claude-code', 'node_modules', '@anthropic-ai', 'claude-code-win32-x64', 'claude.exe'),
      ],
      codex: [
        join(localAppData, 'Programs', 'OpenAI', 'Codex', 'bin', 'codex.exe'),
        join(userProfile, '.local', 'bin', 'codex.exe'),
      ],
      agy: [join(localAppData, 'agy', 'bin', 'agy.exe')],
      hermes: windowsHermesExecutableCandidates({
        localAppData,
        hermesHome: process.env.HERMES_HOME,
      }),
    };
    for (const candidate of knownCandidates[name]) {
      if (candidate && existsSync(candidate)) {
        AGENT_BIN_CACHE.set(name, candidate);
        return candidate;
      }
    }

    // where.exe 결과가 .cmd/extensionless shim이면 패키지 내부 실제 .exe로 해석한다.
    const r = Bun.spawnSync(['where', name], { stdout: 'pipe', stderr: 'pipe' });
    if (r.exitCode === 0) {
      for (const found of r.stdout.toString().trim().split(/\r?\n/).map((line) => line.trim()).filter(Boolean)) {
        const executable = unwrapWindowsAgentShim(found, name);
        if (executable) {
          AGENT_BIN_CACHE.set(name, executable);
          return executable;
        }
      }
    }
    return name;
  }
  const home = homedir();
  const candidates = [
    ...(name === 'codex' ? [
      '/Applications/ChatGPT.app/Contents/Resources/codex',
      '/Applications/Codex.app/Contents/Resources/codex',
    ] : []),
    `${home}/.local/bin/${name}`,
    `/opt/homebrew/bin/${name}`,
    `/usr/local/bin/${name}`,
    `${home}/.bun/bin/${name}`,
    `${home}/.npm-global/bin/${name}`,
    `${home}/.volta/bin/${name}`,
  ];
  let found = candidates.find((p) => existsSync(p)) ?? null;
  if (!found) {
    // login shell 폴백 — 사용자 프로파일(PATH 확장)을 로드한 뒤 탐색
    try {
      const r = nodeSpawnSync('zsh', ['-lc', `command -v ${name}`], { encoding: 'utf-8', timeout: 5000 });
      const p = ((r.stdout ?? '').toString().trim().split('\n')[0] ?? '').trim();
      if (p && existsSync(p)) found = p;
    } catch { /* ignore — bare 이름으로 폴백 */ }
  }
  if (found) {
    AGENT_BIN_CACHE.set(name, found);
    return found;
  }
  // Do not cache a miss. Agents can be installed while the sidecar is alive;
  // a permanent bare-name cache made the launch button stay broken until the
  // whole desktop app was restarted.
  return name;
}

/**
 * Hermes 실행 파일의 절대경로. 없으면 null.
 *
 * `resolveAgentBin`은 못 찾으면 이름 그대로를 돌려주는데, 그 값을 spawn하면 사용자에게
 * `Executable not found in $PATH`라는 원시 오류가 그대로 노출된다. 실행 전에 이 함수로
 * 미설치를 먼저 판정하고, 어댑터 상태도 같은 값을 보게 해서 "설정 폴더는 있는데 CLI는
 * 없는" 기기에서 실행 버튼이 뜨는 일을 막는다.
 */
function hermesCliPath(): string | null {
  return hermesCliPathFromResolved(resolveAgentBin('hermes'));
}

const HERMES_PROFILE_ID_PATTERN = /^[A-Za-z0-9][A-Za-z0-9_-]{0,63}$/;

function hermesProfileHome(profileName: string): string {
  return profileName === 'default'
    ? join(homedir(), '.hermes')
    : join(homedir(), '.hermes', 'profiles', profileName);
}

/** profile.yaml의 최상위 display_name만 읽는다. 토큰·설정 전체를 파싱하거나 반환하지 않는다. */
function readHermesProfileDisplayName(profileHome: string): string {
  const metadataPath = join(profileHome, 'profile.yaml');
  if (!existsSync(metadataPath)) return '';
  try {
    const line = readFileSync(metadataPath, 'utf8')
      .split(/\r?\n/)
      .find(candidate => /^display_name\s*:/.test(candidate));
    if (!line) return '';
    const raw = line.slice(line.indexOf(':') + 1).trim();
    if (!raw || raw === 'null' || raw === '~') return '';
    if (raw.startsWith('"') && raw.endsWith('"')) {
      try { return String(JSON.parse(raw)).trim(); } catch { return raw.slice(1, -1).trim(); }
    }
    if (raw.startsWith("'") && raw.endsWith("'")) return raw.slice(1, -1).replace(/''/g, "'").trim();
    return raw.replace(/\s+#.*$/, '').trim();
  } catch {
    return '';
  }
}

async function runHermesProfileCommand(args: string[]): Promise<{ stdout: string; stderr: string }> {
  const cli = hermesCliPath();
  if (!cli) throw new Error(HERMES_CLI_NOT_FOUND_MESSAGE);
  const child = Bun.spawn([cli, 'profile', ...args], {
    stdout: 'pipe',
    stderr: 'pipe',
    env: process.env,
  });
  const [exitCode, stdout, stderr] = await Promise.all([
    child.exited,
    new Response(child.stdout).text(),
    new Response(child.stderr).text(),
  ]);
  if (exitCode !== 0) {
    const detail = (stderr.trim() || stdout.trim() || 'Hermes profile 명령이 실패했습니다.').slice(0, 1000);
    throw new Error(detail);
  }
  return { stdout: stdout.trim(), stderr: stderr.trim() };
}

/** 셸 문자열에 박아 넣을 때만 따옴표 — 공백 없는 절대경로는 그대로 둔다.
 *  (tmux 명령은 `'zsh -l -c "<cmd>"'` 처럼 중첩 인용이라 불필요한 따옴표가 오히려 깨진다) */
function shQuoteIfNeeded(p: string): string {
  return /^[A-Za-z0-9_@%+=:,./-]+$/.test(p) ? p : `'${p.replace(/'/g, "'\\''")}'`;
}

/** Orca의 Windows 터미널은 WSL bash다. 실제 Windows .exe를 /mnt/<drive>/...로
 *  변환하면 npm shim/PATH 차이 없이 WSL interop으로 세 CLI를 동일하게 실행할 수 있다. */
function agentCliForWsl(name: AgentName, bypass: boolean): string | null {
  const resolved = resolveAgentBin(name);
  if (resolved === name || !/^[A-Za-z]:[\\/]/.test(resolved)) return null;
  return buildWindowsOrcaAgentCommand(name, resolved, bypass);
}

function agentCliForWindowsCmd(name: AgentName, bypass: boolean): string | null {
  const resolved = resolveAgentBin(name);
  if (resolved === name || !/^[A-Za-z]:[\\/]/.test(resolved)) return null;
  return buildWindowsCmdAgentCommand(name, resolved, bypass);
}

/** 에이전트 실행 명령 문자열 (절대경로 + bypass 플래그) */
function agentCli(name: AgentName, bypass: boolean): string {
  const bin = shQuoteIfNeeded(resolveAgentBin(name));
  return bypass ? `${bin} ${AGENT_BYPASS_FLAG[name]}` : bin;
}

/** Commands handed to native cmd.exe must use Windows quoting, never the
 * POSIX single quotes used by zsh/tmux. Fail before opening a terminal when
 * discovery did not prove an executable path, rather than reporting a fake
 * successful launch for a bare command that cmd.exe cannot resolve. */
function terminalAgentCli(name: AgentName, bypass: boolean): string {
  if (!IS_WIN) return agentCli(name, bypass);
  const command = agentCliForWindowsCmd(name, bypass);
  if (command) return command;
  if (name === 'hermes') throw new Error(HERMES_CLI_NOT_FOUND_MESSAGE);
  throw new Error(`${name} CLI 실행 파일을 찾을 수 없습니다. 설치 후 AgentsToZ를 다시 시작해주세요.`);
}

type CodexUsagePayload = {
  rateLimits: ReturnType<typeof normalizeCodexRateLimits>;
  checkedAt: string;
  source: 'live-app-server';
  cached?: boolean;
};

const CODEX_LIVE_RATE_LIMIT_CACHE_MS = 30_000;
let codexLiveRateLimitCache: { expiresAt: number; payload: CodexUsagePayload } | null = null;
let codexLiveRateLimitInFlight: Promise<CodexUsagePayload> | null = null;

/** Query the authenticated Codex app-server, never `codex exec`: the latter
 * starts an agent turn while this JSON-RPC method only reads account limits. */
async function getLiveCodexRateLimits(force = false): Promise<CodexUsagePayload> {
  const now = Date.now();
  if (!force && codexLiveRateLimitCache && codexLiveRateLimitCache.expiresAt > now) {
    return { ...codexLiveRateLimitCache.payload, cached: true };
  }
  if (codexLiveRateLimitInFlight) return codexLiveRateLimitInFlight;

  const task = readCodexLiveRateLimits(resolveAgentBin('codex')).then(result => {
    const payload: CodexUsagePayload = {
      rateLimits: result.rateLimits,
      checkedAt: result.checkedAt,
      source: 'live-app-server',
    };
    codexLiveRateLimitCache = { expiresAt: Date.now() + CODEX_LIVE_RATE_LIMIT_CACHE_MS, payload };
    return payload;
  });
  codexLiveRateLimitInFlight = task;
  try {
    return await task;
  } finally {
    if (codexLiveRateLimitInFlight === task) codexLiveRateLimitInFlight = null;
  }
}

const executableProcesses = new Map<string, any>();
const projectWorkerProcesses = new Map<string, { pid: number; cwd: string; startedAt: number; process: any }>();
const projectWorkerLocks = new ProjectWorkerLockRegistry();
type ProjectWorkerResult = { status: "exited"; exitCode: number; finishedAt: number; cwd: string; evidence: ReturnType<typeof readAgentsToZProjectWorkerEvidence>; memory: { localRemembered: boolean; backup: unknown; backupError?: string } };
const projectWorkerResults = new Map<string, ProjectWorkerResult>();
const PROJECT_WORKER_RESULT_TTL_MS = 24 * 60 * 60 * 1000;
const PROJECT_WORKER_RESULT_MAX = 256;
function pruneProjectWorkerResults(now = Date.now()): void {
  for (const [requestId, result] of projectWorkerResults) {
    if (now - result.finishedAt > PROJECT_WORKER_RESULT_TTL_MS) projectWorkerResults.delete(requestId);
  }
  while (projectWorkerResults.size > PROJECT_WORKER_RESULT_MAX) {
    const oldest = projectWorkerResults.keys().next().value as string | undefined;
    if (!oldest) break;
    projectWorkerResults.delete(oldest);
  }
}
const portLaunchOwnership = new PortLaunchOwnership();
let buildProcess: any = null;
let buildStatus = {
  isBuilding: false,
  type: '',
  output: [] as string[],
  outputBase: 0,
  outputCursor: 0,
  exitCode: null as number | null,
};

// 빌드/배포 로그 버퍼 상한 — 장시간 빌드(최대 60분 Windows 빌드 등)에서 output 배열이
// 무한히 커지는 것을 방지. 최근 N개 항목만 유지 (UI는 어차피 최근 로그만 표시).
const MAX_LOG_BUFFER_ENTRIES = 1000;
const MAX_LOG_ENTRY_CHARS = 8_192;
function pushLogBounded(arr: string[], text: string): void {
  arr.push(text.slice(-MAX_LOG_ENTRY_CHARS));
  if (arr.length > MAX_LOG_BUFFER_ENTRIES) {
    arr.splice(0, arr.length - MAX_LOG_BUFFER_ENTRIES);
  }
}

function pushBuildLog(text: string): void {
  buildStatus.output.push(text.slice(-MAX_LOG_ENTRY_CHARS));
  buildStatus.outputCursor += 1;
  if (buildStatus.output.length > MAX_LOG_BUFFER_ENTRIES) {
    const dropped = buildStatus.output.length - MAX_LOG_BUFFER_ENTRIES;
    buildStatus.output.splice(0, dropped);
    buildStatus.outputBase += dropped;
  }
}

let deployProcess: any = null;
let deployStatus = {
  isDeploying: false,
  output: [] as string[],
  exitCode: null as number | null,
  url: null as string | null,
  projectRef: null as string | null,
};

const deploymentPath = IS_WIN
  ? process.env.PATH ?? ''
  : `/opt/homebrew/bin:/usr/local/bin:/usr/bin:/bin:${homedir()}/.bun/bin:${homedir()}/.local/bin:${process.env.PATH ?? ''}`;

/** Values are written over stdin. The shell command contains fixed CLI tokens only. */
function vercelCliCommand(args: string[]): string[] {
  if (IS_WIN) {
    const fixedArg = /^[A-Za-z0-9_./:-]+$/;
    if (!args.every(arg => fixedArg.test(arg))) throw new Error('허용되지 않은 Vercel CLI 인자입니다.');
    return ['cmd.exe', '/d', '/s', '/c', `npx vercel ${args.join(' ')}`];
  }
  return ['npx', 'vercel', ...args];
}

async function runPortalVercelCommand(
  args: string[],
  options: { stdinValue?: string; label: string },
): Promise<{ stdout: string; stderr: string }> {
  pushLogBounded(deployStatus.output, `\n▸ ${options.label}\n`);
  const proc = spawn({
    cmd: vercelCliCommand(args),
    cwd: import.meta.dir,
    env: { ...process.env, PATH: deploymentPath },
    stdin: options.stdinValue === undefined ? 'ignore' : 'pipe',
    stdout: 'pipe',
    stderr: 'pipe',
  });
  deployProcess = proc;
  if (options.stdinValue !== undefined && proc.stdin) {
    proc.stdin.write(`${options.stdinValue}\n`);
    proc.stdin.end();
  }

  const output = { stdout: [] as string[], stderr: [] as string[] };
  const readStream = async (stream: ReadableStream<Uint8Array>, isStderr: boolean) => {
    const decoder = new TextDecoder();
    for await (const chunk of stream) {
      const text = decoder.decode(chunk, { stream: true });
      const safeText = options.stdinValue
        ? text.split(options.stdinValue).join('[입력값 숨김]')
        : text;
      output[isStderr ? 'stderr' : 'stdout'].push(safeText);
      pushLogBounded(deployStatus.output, safeText);
      if (isStderr) console.error(`[Deploy] ${safeText}`);
      else devLog(`[Deploy] ${safeText}`);
    }
  };
  const stdoutDone = readStream(proc.stdout, false);
  const stderrDone = readStream(proc.stderr, true);
  const code = await proc.exited;
  await Promise.all([stdoutDone, stderrDone]);
  if (code !== 0) throw new Error(`${options.label} 실패 (exit ${code})`);
  return { stdout: output.stdout.join(''), stderr: output.stderr.join('') };
}

async function runPortalDeployment(input: {
  supabaseUrl: string;
  supabaseAnonKey: string;
}): Promise<void> {
  try {
    // Fork/GitHub 연결 없이도 현재 공개 clone에서 개인 Vercel 프로젝트를 만들 수 있다.
    await runPortalVercelCommand(['link', '--yes'], { label: 'Vercel 프로젝트 연결' });
    for (const [name, value] of [
      ['VITE_SUPABASE_URL', input.supabaseUrl],
      ['VITE_SUPABASE_ANON_KEY', input.supabaseAnonKey],
    ] as const) {
      await runPortalVercelCommand(['env', 'add', name, 'production', '--force'], {
        label: `${name} 저장`,
        stdinValue: value,
      });
    }
    const production = await runPortalVercelCommand(['deploy', '--prod', '--yes'], { label: 'Production 포털 배포' });
    const productionUrl = selectVercelProductionPortalUrl(production.stdout, production.stderr);
    if (!productionUrl) throw new Error('배포는 끝났지만 Production Vercel URL을 확인하지 못했습니다.');
    deployStatus.url = await persistPortalDeployUrl(productionUrl);
    deployStatus.exitCode = 0;
  } catch (error) {
    pushLogBounded(deployStatus.output, `\n❌ ${error instanceof Error ? error.message : String(error)}\n`);
    deployStatus.exitCode = 1;
  } finally {
    deployStatus.isDeploying = false;
    deployProcess = null;
  }
}

// GitHub Actions는 명시 설정 → 안전한 VITE_REPO_URL → 현재 checkout origin 순서로만
// 대상 저장소를 정한다. 공개판에 운영자의 private fallback을 하드코딩하지 않는다.
const GITHUB_WORKFLOW = process.env.PORTMGR_GITHUB_WORKFLOW || 'build-windows.yml';

function currentCheckoutOriginRemote(): string {
  try {
    const result = Bun.spawnSync(['git', 'remote', 'get-url', '--push', 'origin'], {
      cwd: import.meta.dir,
      stdout: 'pipe',
      stderr: 'pipe',
    });
    return result.exitCode === 0 ? result.stdout.toString().trim() : '';
  } catch {
    return '';
  }
}

function configuredGitHubActionsRepository() {
  return resolveGitHubActionsRepository({
    configuredOwner: process.env.PORTMGR_GITHUB_OWNER,
    configuredRepo: process.env.PORTMGR_GITHUB_REPO,
    repositoryUrl: process.env.VITE_REPO_URL,
    originRemote: currentCheckoutOriginRemote(),
  });
}

function resolveGitHubCliPath(): string | null {
  const configured = process.env.PORTMGR_GH_PATH?.trim();
  const candidates = [
    configured,
    ...(IS_WIN ? [
      process.env.ProgramFiles ? join(process.env.ProgramFiles, 'GitHub CLI', 'gh.exe') : '',
      process.env.LOCALAPPDATA ? join(process.env.LOCALAPPDATA, 'Programs', 'GitHub CLI', 'gh.exe') : '',
    ] : [
      '/opt/homebrew/bin/gh',
      '/usr/local/bin/gh',
      join(homedir(), '.local/bin/gh'),
      '/usr/bin/gh',
    ]),
  ].filter((value): value is string => !!value);
  const direct = candidates.find(candidate => existsSync(candidate));
  if (direct) return direct;

  try {
    const located = Bun.spawnSync(IS_WIN ? ['where', 'gh'] : ['which', 'gh'], { stdout: 'pipe', stderr: 'pipe' });
    const path = located.exitCode === 0 ? located.stdout.toString().trim().split(/\r?\n/)[0] : '';
    if (path && existsSync(path)) return path;
  } catch {}

  if (!IS_WIN) {
    for (const shell of ['/bin/zsh', '/bin/bash']) {
      try {
        const located = Bun.spawnSync([shell, '-l', '-c', 'command -v gh'], { stdout: 'pipe', stderr: 'pipe' });
        const path = located.exitCode === 0 ? located.stdout.toString().trim().split(/\r?\n/)[0] : '';
        if (path && existsSync(path)) return path;
      } catch {}
    }
  }
  return null;
}

// 포트 데이터 파일 - Tauri와 동일한 위치 사용 (플랫폼별)
// macOS: ~/Library/Application Support/com.portmanager.portmanager
// Windows: %APPDATA%\com.portmanager.portmanager
// Linux/AWS Ubuntu: ${XDG_CONFIG_HOME:-~/.config}/com.portmanager.portmanager
const APP_DATA_DIR = resolveAppDataDirFromEnvironment();
const remoteProjectCreateReceipts = new FileProjectLaunchReceiptStore(APP_DATA_DIR);
const remoteProjectCreation = new ProjectCreationCoordinator(remoteProjectCreateReceipts);
const memorySaveDispatcher = new MemorySaveDispatcher();
const memorySessionStore = new MemorySessionStore(join(APP_DATA_DIR, "memory-session-recovery.sqlite"));
const whatISaidPromptOrigins = new WhatISaidPromptOriginRegistry(APP_DATA_DIR);
const promptGuideStore = new PromptGuideStore({ appDataDir: APP_DATA_DIR });
const orchestrationMissionTestKeyProvider = ORCHESTRATION_MISSION_TEST_KEY_HEX === undefined
  ? undefined
  : {
      read: async () => {
        if (!/^[0-9a-f]{64}$/i.test(ORCHESTRATION_MISSION_TEST_KEY_HEX)) throw new Error("MISSION_TEST_KEY_INVALID");
        return Buffer.from(ORCHESTRATION_MISSION_TEST_KEY_HEX, "hex");
      },
      create: async () => {
        if (!/^[0-9a-f]{64}$/i.test(ORCHESTRATION_MISSION_TEST_KEY_HEX)) throw new Error("MISSION_TEST_KEY_INVALID");
        return Buffer.from(ORCHESTRATION_MISSION_TEST_KEY_HEX, "hex");
      },
    };
const orchestrationMissionStore = new OrchestrationMissionStore({
  appDataDir: APP_DATA_DIR,
  keyProvider: orchestrationMissionTestKeyProvider,
});
const orchestrationMissionStartupRecovery: Promise<unknown | null> = orchestrationMissionStore
  .interruptActiveMissions()
  .then(() => null)
  .catch(error => error);
async function requireOrchestrationMissionStartupRecovery(): Promise<void> {
  const error = await orchestrationMissionStartupRecovery;
  if (error) throw error;
}
// These variables belong to the trusted Tauri -> sidecar bootstrap only. The
// sidecar has captured every value it needs, so project commands and package
// lifecycle scripts must not inherit a direct map to the private app data or
// the sidecar authentication channel.
delete process.env.APP_DATA_DIR;
delete process.env.PORTMGR_BUNDLED_SIDECAR;
delete process.env.PORTMGR_PARENT_PID;
let agentRuntimeGuardRegistry: AgentRuntimeGuardRegistry | null = null;
let agentRuntimeGuardLaunchers: AgentRuntimeGuardLaunchers | null = null;
try {
  agentRuntimeGuardRegistry = prepareAgentRuntimeGuardRegistry(APP_DATA_DIR);
  agentRuntimeGuardLaunchers = createAgentRuntimeGuardLaunchers(agentRuntimeGuardRegistry);
} catch (error) {
  // Read-only/local management surfaces may still start, but no stale
  // workspace owner may be reclaimed without this positive crash fence.
  console.error(
    '[AgentRuntime] durable process guard registry is unavailable:',
    error instanceof Error ? error.message : 'unknown error',
  );
}
const PORTS_DATA_FILE = join(APP_DATA_DIR, "ports.json");
const PORTS_BACKUP_FILE = join(APP_DATA_DIR, "ports.json.bak");
const PORTS_LOCK_FILE = join(APP_DATA_DIR, "ports.json.lock");
const PORTS_AUDIT_FILE = join(APP_DATA_DIR, "ports-save-audit.jsonl");
const WORKSPACE_ROOTS_FILE = join(APP_DATA_DIR, "workspace-roots.json");
const LAST_VISITS_FILE = join(APP_DATA_DIR, "last-visits.json");
const PORTAL_DATA_FILE = join(APP_DATA_DIR, "portal.json");
const PORTAL_LOCAL_METADATA_FILE = join(APP_DATA_DIR, "portal-local-metadata.json");
const PORTAL_LOCK_FILE = join(APP_DATA_DIR, "portal.json.lock");
const WORKSPACE_LEASE_ATTEMPTS = 45;
const WORKSPACE_LEASE_RETRY_MS = 25;
const WORKSPACE_LEASE_DEAD_OWNER_GRACE_MS = 1_000;
// Ordinary workspace mutations use manual-recovery owners, so an unavailable
// Agent Runtime guard registry must not disable fresh Git/memory operations.
// This flag is reserved for uncertainty in the workspace lease authority
// itself (for example losing exact ownership during release).
let workspaceLeaseDegraded = false;
const GUARDED_WORKSPACE_LOCK_OWNER_PATTERN =
  /^v3:[1-9][0-9]{0,9}:[0-9a-f]{32}:guarded$/;

function canRecoverWorkspaceDeadOwner(owner: string): boolean {
  // Old/unclassified and ordinary mutation owners have no durable process-tree
  // containment proof. They remain unavailable after a crash rather than
  // risking a second Git/memory writer while a descendant may still be alive.
  if (!GUARDED_WORKSPACE_LOCK_OWNER_PATTERN.test(owner)) return false;
  try {
    return agentRuntimeGuardRegistry?.canRecoverDeadOwner(owner) === true;
  } catch (error) {
    workspaceLeaseDegraded = true;
    console.error(
      '[AgentRuntime] durable process guard recovery proof failed:',
      error instanceof Error ? error.message : 'unknown error',
    );
    return false;
  }
}

/**
 * Local API routes that can change a registered workspace, its Git authority,
 * or the canonical project memory stored inside it. Runtime starts acquire the
 * same lease inside AgentRuntimeService because their ownership outlives the
 * HTTP response. Batch/new-project/long-running worker paths are coordinated
 * at their own lifecycle boundaries instead of being listed here.
 */
const WORKSPACE_MUTATION_PATH_FIELD = new Map<string, 'folderPath' | 'worktreePath'>([
  ['/api/project-memory/init', 'folderPath'],
  ['/api/project-memory/update', 'folderPath'],
  ['/api/project-memory/document-recovery', 'folderPath'],
  ['/api/project-memory/session-recovery', 'folderPath'],
  ['/api/project-memory/upgrade-agent', 'folderPath'],
  ['/api/project-memory/sync', 'folderPath'],
  ['/api/project-memory/preferred-agent', 'folderPath'],
  ['/api/project-memory/private-github-archive/enable', 'folderPath'],
  ['/api/project-memory/private-github-archive/run', 'folderPath'],
  ['/api/project-memory/feedback', 'folderPath'],
  ['/api/project-memory/mark-remembered', 'folderPath'],
  ['/api/project-memory/push', 'folderPath'],
  ['/api/project-memory/pull', 'folderPath'],
  ['/api/project-memory/restore-revision', 'folderPath'],
  ['/api/project-memory/resolve-conflict', 'folderPath'],
  ['/api/project-memory/session-end', 'folderPath'],
  // Despite its name this may adopt canonical identity/alias metadata and
  // rewrite `.agent-memory/config.json` while resolving remote lineage.
  ['/api/project-memory/remote-status', 'folderPath'],
  ['/api/repository-workflow/upgrade', 'folderPath'],
  ['/api/repository-workflow/complete-first-task', 'folderPath'],
  ['/api/repository-workflow/worktree-launch', 'worktreePath'],
  ['/api/list-git-worktrees', 'folderPath'],
  ['/api/git-pull', 'folderPath'],
  ['/api/git-push', 'folderPath'],
  ['/api/git-commit', 'worktreePath'],
  ['/api/git-worktree-unlock', 'folderPath'],
  ['/api/git-worktree-switch-branch', 'folderPath'],
  ['/api/git-init', 'folderPath'],
  ['/api/git-reinitialize', 'folderPath'],
  ['/api/git-worktree-add', 'folderPath'],
  ['/api/move-git-worktree', 'folderPath'],
  ['/api/git-worktree-remove', 'folderPath'],
  ['/api/cleanup-stale-worktrees', 'folderPath'],
  ['/api/git-merge-abort', 'folderPath'],
  ['/api/git-merge-branch', 'folderPath'],
]);

function workspaceLeaseUnavailable(): WorkspaceLeaseError {
  return new WorkspaceLeaseError(
    'WORKSPACE_LEASE_IO',
    '작업공간 잠금 상태를 안전하게 확인할 수 없습니다.',
  );
}

// Shutdown drains held leases before exiting. A lease taken after that drain
// began would race the exit and be left behind as an unrecoverable manual lock.
let managedWorkspaceLeaseAdmissionClosed = false;

function closeManagedWorkspaceLeaseAdmission(): void {
  managedWorkspaceLeaseAdmissionClosed = true;
}

function assertManagedWorkspaceLeaseAdmission(): void {
  if (!managedWorkspaceLeaseAdmissionClosed) return;
  throw new WorkspaceLeaseError(
    'WORKSPACE_LEASE_BUSY',
    '앱이 종료 중이라 새 작업공간 작업을 시작하지 않았습니다.',
  );
}

async function acquireManagedWorkspaceLease(
  workspacePath: string,
  deadOwnerRecoveryClass: WorkspaceLeaseDeadOwnerRecoveryClass = 'manual',
): Promise<WorkspaceLease> {
  if (workspaceLeaseDegraded) throw workspaceLeaseUnavailable();
  assertManagedWorkspaceLeaseAdmission();
  return acquireWorkspaceLease({
    workspacePath,
    appDataDir: APP_DATA_DIR,
    gitExecutable: GIT_PATH,
    attempts: WORKSPACE_LEASE_ATTEMPTS,
    retryMs: WORKSPACE_LEASE_RETRY_MS,
    staleAfterMs: 60_000,
    // The grace period only avoids an immediate PID-exit race. Manual owners
    // remain fail-closed after owner death; it is not process-tree proof.
    deadOwnerGraceMs: WORKSPACE_LEASE_DEAD_OWNER_GRACE_MS,
    deadOwnerRecoveryClass,
    canRecoverDeadOwner: deadOwnerRecoveryClass === 'guarded'
      ? canRecoverWorkspaceDeadOwner
      : undefined,
  });
}

async function acquireManagedWorkspaceDirectoryLease(workspacePath: string): Promise<WorkspaceDirectoryLease> {
  if (workspaceLeaseDegraded) throw workspaceLeaseUnavailable();
  assertManagedWorkspaceLeaseAdmission();
  return acquireWorkspaceDirectoryLease({
    workspacePath,
    appDataDir: APP_DATA_DIR,
    attempts: WORKSPACE_LEASE_ATTEMPTS,
    retryMs: WORKSPACE_LEASE_RETRY_MS,
    staleAfterMs: 60_000,
    deadOwnerGraceMs: WORKSPACE_LEASE_DEAD_OWNER_GRACE_MS,
    deadOwnerRecoveryClass: 'manual',
  });
}

async function promoteManagedWorkspaceDirectoryLease(
  lease: WorkspaceDirectoryLease,
): Promise<WorkspaceLease> {
  if (workspaceLeaseDegraded) throw workspaceLeaseUnavailable();
  assertManagedWorkspaceLeaseAdmission();
  return lease.promote({
    gitExecutable: GIT_PATH,
    attempts: WORKSPACE_LEASE_ATTEMPTS,
    retryMs: WORKSPACE_LEASE_RETRY_MS,
    staleAfterMs: 60_000,
    deadOwnerGraceMs: WORKSPACE_LEASE_DEAD_OWNER_GRACE_MS,
    deadOwnerRecoveryClass: 'manual',
  });
}

/**
 * A committed operation must not be reported as failed merely because cleanup
 * became uncertain: that invites a duplicate destructive retry. Instead stop
 * every later managed writer until the sidecar restarts and re-establishes the
 * cross-process authority.
 */
function releaseManagedWorkspaceLease(lease: WorkspaceLease, context: string): boolean {
  try {
    if (lease.release()) return true;
    workspaceLeaseDegraded = true;
    console.error(`[WorkspaceLease] ${context}: exact ownership was lost during release.`);
  } catch (error) {
    workspaceLeaseDegraded = true;
    console.error(
      `[WorkspaceLease] ${context}: release failed:`,
      error instanceof Error ? error.message : 'unknown error',
    );
  }
  return false;
}

async function withManagedWorkspaceLease<T>(
  workspacePath: string,
  context: string,
  operation: (lease: WorkspaceLease) => Promise<T> | T,
): Promise<T> {
  const lease = await acquireManagedWorkspaceLease(workspacePath);
  try {
    return await operation(lease);
  } finally {
    releaseManagedWorkspaceLease(lease, context);
  }
}

async function withAgentsToZUseWorkspaceLease<T>(
  workspacePath: string,
  context: string,
  operation: () => Promise<T> | T,
): Promise<T> {
  try {
    return await withManagedWorkspaceLease(workspacePath, context, operation);
  } catch (error) {
    if (error instanceof WorkspaceLeaseError) {
      const busy = error.code === 'WORKSPACE_LEASE_BUSY';
      throw new AgentsToZUseControlError(
        busy
          ? '이 프로젝트에서 다른 에이전트 또는 Git 작업이 진행 중입니다.'
          : '이 프로젝트의 작업공간 잠금 상태를 안전하게 확인하지 못했습니다.',
        error.code,
        busy ? 409 : error.code === 'WORKSPACE_LEASE_UNSAFE' ? 400 : 503,
      );
    }
    throw error;
  }
}

// The dispatcher owns no workspace while waiting. Re-resolve the canonical
// memory authority before admission and again under the cross-process lease.
async function withScheduledMemorySave<T>(
  folderPath: string, trigger: 'manual' | 'workroom' | 'checkpoint', label: string,
  operation: (signal: AbortSignal, lease: WorkspaceLease) => Promise<T>, waitingSignal?: AbortSignal,
): Promise<T> {
  const identity = await detectProjectMemoryIdentity(folderPath);
  const root = realpathSync(identity.projectRoot);
  return memorySaveDispatcher.schedule({ root, trigger, waitingSignal, run: signal =>
    withManagedWorkspaceLease(root, label, async lease => {
      signal.throwIfAborted();
      const fresh = await detectProjectMemoryIdentity(folderPath);
      if (realpathSync(fresh.projectRoot) !== root || fresh.config?.memoryId !== identity.config?.memoryId) {
        throw new ProjectMemoryError('프로젝트 경로나 장기기억 계보가 변경되었습니다.', 'PROJECT_NOT_REGISTERED');
      }
      memorySessionStore.assertReady(root);
      return operation(signal,lease);
    }),
  });
}

async function workspaceMutationPathForRequest(req: Request, url: URL): Promise<string | null> {
  if (req.method !== 'POST') return null;
  const field = WORKSPACE_MUTATION_PATH_FIELD.get(url.pathname);
  if (!field) return null;
  const body = await req.clone().json().catch(() => null) as Record<string, unknown> | null;
  const bodyValue = typeof body?.[field] === 'string' ? body[field].trim() : '';
  const queryValue = url.searchParams.get(field)?.trim() ?? '';
  // Some legacy memory routes accept query + JSON while Git routes are JSON
  // only. Never permit those two channels to name different targets: parser
  // precedence and Content-Type otherwise make it possible to lease A and
  // mutate B. Equivalent-but-differently-spelled paths are conservatively
  // rejected; callers should send one authoritative target.
  if (bodyValue && queryValue && bodyValue !== queryValue) {
    throw new WorkspaceLeaseError(
      'WORKSPACE_LEASE_UNSAFE',
      '요청 본문과 쿼리의 작업공간이 일치하지 않습니다.',
    );
  }
  // Listing is read-only unless the caller explicitly asks for the remote
  // refresh, which executes `git fetch --prune` before producing inventory.
  if (url.pathname === '/api/list-git-worktrees' && body?.fetchRemote !== true) return null;
  // `git-init` is also the read-only repository probe used by the UI. It must
  // remain available while a writer is active and must not claim a write lease.
  if (url.pathname === '/api/git-init' && body?.checkOnly === true) return null;
  // Memory routes accept both JSON and query parameters, with JSON taking
  // precedence (`readMemoryParams`). The lease must resolve the exact same
  // effective target or a query/body disagreement could lock A while writing B.
  return bodyValue || queryValue || null;
}

function workspaceLeaseHttpResponse(
  error: unknown,
  headers: Record<string, string>,
): Response {
  const controlled = error instanceof WorkspaceLeaseError ? error : workspaceLeaseUnavailable();
  const busy = controlled.code === 'WORKSPACE_LEASE_BUSY';
  const unsafe = controlled.code === 'WORKSPACE_LEASE_UNSAFE';
  return new Response(JSON.stringify({
    success: false,
    ok: false,
    code: controlled.code,
    error: workspaceLeaseMessage(controlled.code),
  }), {
    status: busy ? 409 : unsafe ? 400 : 503,
    headers: { ...headers, 'Cache-Control': 'private, no-store' },
  });
}
const PORTAL_ORIGIN_CACHE_RECHECK_MS = 1_000;
const PORTAL_ORIGIN_CACHE_MAX_REUSE_MS = 5_000;
let storedPortalOriginCache: {
  checkedAt: number;
  loadedAt: number;
  signature: string | null;
  value: string | null;
} | null = null;

function readPortalJson(path: string): Record<string, any> {
  if (!existsSync(path)) return {};
  const value = JSON.parse(readFileSync(path, 'utf8'));
  if (!value || typeof value !== 'object' || Array.isArray(value)) {
    throw new Error('포털 저장 데이터가 객체 형식이 아닙니다.');
  }
  return value as Record<string, any>;
}

function writePortalJsonAtomic(path: string, value: Record<string, any>): void {
  if (!existsSync(APP_DATA_DIR)) mkdirSync(APP_DATA_DIR, { recursive: true });
  const temporary = `${path}.tmp-${process.pid}-${crypto.randomUUID()}`;
  try {
    writeFileSync(temporary, JSON.stringify(value, null, 2));
    renameSync(temporary, path);
  } finally {
    if (existsSync(temporary)) {
      try { unlinkSync(temporary); } catch {}
    }
  }
}

async function withPortalFileLock<T>(operation: () => T | Promise<T>): Promise<T> {
  return withOwnedPortalFileLock(PORTAL_LOCK_FILE, operation);
}

function authoritativePortalLocalMetadata(portal: Record<string, any>): Record<string, any> {
  return existsSync(PORTAL_LOCAL_METADATA_FILE)
    ? readPortalJson(PORTAL_LOCAL_METADATA_FILE)
    : portal;
}

const PORTAL_SAFETY_LEASE_DEFAULT_TTL_MS = 120_000;
// Production always uses the audited two-minute window. Integration tests may
// shorten it so renewal/expiry ordering is exercised without a two-minute
// sleep; never let an ambient production environment weaken the lease.
const PORTAL_SAFETY_LEASE_TTL_MS = process.env.NODE_ENV === 'test'
  && Number.isSafeInteger(Number(process.env.PORTMGR_TEST_PORTAL_SAFETY_LEASE_TTL_MS))
  && Number(process.env.PORTMGR_TEST_PORTAL_SAFETY_LEASE_TTL_MS) >= 100
    ? Number(process.env.PORTMGR_TEST_PORTAL_SAFETY_LEASE_TTL_MS)
    : PORTAL_SAFETY_LEASE_DEFAULT_TTL_MS;
const PORTAL_SAFETY_LEASE_DEFAULT_RESUME_GRACE_MS = 10_000;
const PORTAL_SAFETY_LEASE_RESUME_GRACE_MS = process.env.NODE_ENV === 'test'
  && Number.isSafeInteger(Number(process.env.PORTMGR_TEST_PORTAL_SAFETY_LEASE_GRACE_MS))
  && Number(process.env.PORTMGR_TEST_PORTAL_SAFETY_LEASE_GRACE_MS) >= 50
    ? Number(process.env.PORTMGR_TEST_PORTAL_SAFETY_LEASE_GRACE_MS)
    : PORTAL_SAFETY_LEASE_DEFAULT_RESUME_GRACE_MS;
const PORTAL_SAFETY_LEASE_BODY_MAX_BYTES = 1_024;
const PORTAL_SAFETY_LEASE_TOKEN_PATTERN = /^[0-9a-f]{64}$/;
interface ActivePortalSafetyLease {
  release: OwnedFileLockRelease;
  heartbeat: ReturnType<typeof setInterval>;
  expiry: ReturnType<typeof setTimeout> | null;
  lastRenewedAt: number;
  resumeGraceDeadlineAt: number | null;
}
const portalSafetyLeases = new Map<string, ActivePortalSafetyLease>();

class PortalSafetyLeaseRequestError extends Error {
  constructor(
    readonly status: number,
    readonly code: string,
    message: string,
  ) {
    super(message);
  }
}

async function readPortalSafetyLeaseJson(req: Request): Promise<Record<string, unknown>> {
  const contentType = req.headers.get('content-type')?.split(';', 1)[0]?.trim().toLowerCase();
  if (contentType !== 'application/json') {
    throw new PortalSafetyLeaseRequestError(
      415,
      'PORTAL_SAFETY_LEASE_JSON_REQUIRED',
      '포털 안전 임대 요청은 application/json 형식이어야 합니다.',
    );
  }
  const declaredLength = req.headers.get('content-length');
  if (declaredLength !== null) {
    const parsedLength = Number(declaredLength);
    if (!Number.isSafeInteger(parsedLength) || parsedLength < 0) {
      throw new PortalSafetyLeaseRequestError(
        400,
        'PORTAL_SAFETY_LEASE_INVALID_CONTENT_LENGTH',
        '포털 안전 임대 요청의 Content-Length가 올바르지 않습니다.',
      );
    }
    if (parsedLength > PORTAL_SAFETY_LEASE_BODY_MAX_BYTES) {
      throw new PortalSafetyLeaseRequestError(
        413,
        'PORTAL_SAFETY_LEASE_BODY_TOO_LARGE',
        '포털 안전 임대 요청 본문이 너무 큽니다.',
      );
    }
  }

  const reader = req.body?.getReader();
  if (!reader) {
    throw new PortalSafetyLeaseRequestError(
      400,
      'PORTAL_SAFETY_LEASE_INVALID_JSON',
      '포털 안전 임대 요청에 JSON 객체가 필요합니다.',
    );
  }
  const chunks: Uint8Array[] = [];
  let size = 0;
  while (true) {
    const { done, value } = await reader.read();
    if (done) break;
    size += value.byteLength;
    if (size > PORTAL_SAFETY_LEASE_BODY_MAX_BYTES) {
      await reader.cancel().catch(() => undefined);
      throw new PortalSafetyLeaseRequestError(
        413,
        'PORTAL_SAFETY_LEASE_BODY_TOO_LARGE',
        '포털 안전 임대 요청 본문이 너무 큽니다.',
      );
    }
    chunks.push(value);
  }
  const bytes = new Uint8Array(size);
  let offset = 0;
  for (const chunk of chunks) {
    bytes.set(chunk, offset);
    offset += chunk.byteLength;
  }
  let parsed: unknown;
  try {
    parsed = JSON.parse(new TextDecoder().decode(bytes));
  } catch {
    throw new PortalSafetyLeaseRequestError(
      400,
      'PORTAL_SAFETY_LEASE_INVALID_JSON',
      '포털 안전 임대 요청 JSON을 해석할 수 없습니다.',
    );
  }
  if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) {
    throw new PortalSafetyLeaseRequestError(
      400,
      'PORTAL_SAFETY_LEASE_INVALID_JSON',
      '포털 안전 임대 요청은 JSON 객체여야 합니다.',
    );
  }
  return parsed as Record<string, unknown>;
}

function portalSafetyLeaseErrorResponse(
  error: unknown,
  headers: Record<string, string>,
  fallbackCode: string,
): Response {
  if (error instanceof PortalSafetyLeaseRequestError) {
    return new Response(JSON.stringify({
      success: false,
      code: error.code,
      error: error.message,
    }), { status: error.status, headers: { ...headers, 'Cache-Control': 'no-store' } });
  }
  return new Response(JSON.stringify({
    success: false,
    code: fallbackCode,
    error: error instanceof Error ? error.message : String(error),
  }), { status: 500, headers: { ...headers, 'Cache-Control': 'no-store' } });
}

function portalSafetyLeaseTokenFromBody(
  body: Record<string, unknown>,
  action: 'renew' | 'release',
): string {
  if (Object.keys(body).some(key => key !== 'token')) {
    throw new PortalSafetyLeaseRequestError(
      400,
      'PORTAL_SAFETY_LEASE_UNEXPECTED_FIELDS',
      `포털 안전 임대 ${action === 'renew' ? '갱신' : '해제'} 요청에는 token만 넣을 수 있습니다.`,
    );
  }
  if (typeof body.token !== 'string' || !PORTAL_SAFETY_LEASE_TOKEN_PATTERN.test(body.token)) {
    throw new PortalSafetyLeaseRequestError(
      400,
      'PORTAL_SAFETY_LEASE_INVALID_TOKEN',
      '포털 안전 임대 토큰 형식이 올바르지 않습니다.',
    );
  }
  return body.token;
}

function schedulePortalSafetyLeaseExpiry(token: string, lease: ActivePortalSafetyLease): void {
  if (lease.expiry) clearTimeout(lease.expiry);
  const nextDeadlineAt = lease.resumeGraceDeadlineAt
    ?? lease.lastRenewedAt + PORTAL_SAFETY_LEASE_TTL_MS;
  const remainingMs = Math.max(1, nextDeadlineAt - Date.now());
  lease.expiry = setTimeout(() => {
    const current = portalSafetyLeases.get(token);
    if (current !== lease) return;
    // A renewal can land immediately before an older timeout callback runs.
    // Recompute from the authoritative last-renew time instead of allowing
    // that stale callback to release a lease in the middle of an operation.
    if (Date.now() < lease.lastRenewedAt + PORTAL_SAFETY_LEASE_TTL_MS) {
      schedulePortalSafetyLeaseExpiry(token, lease);
      return;
    }
    if (lease.resumeGraceDeadlineAt === null) {
      // macOS sleep pauses both renderer and server timers. Give the renderer
      // one bounded wake-up window instead of releasing on the first delayed
      // callback before its overdue heartbeat can run. With an active event
      // loop, a crashed renderer is still retired after TTL + 10 seconds.
      lease.resumeGraceDeadlineAt = Date.now() + PORTAL_SAFETY_LEASE_RESUME_GRACE_MS;
      schedulePortalSafetyLeaseExpiry(token, lease);
      return;
    }
    if (Date.now() < lease.resumeGraceDeadlineAt) {
      schedulePortalSafetyLeaseExpiry(token, lease);
      return;
    }
    releasePortalSafetyLease(token);
  }, remainingMs);
  lease.expiry.unref?.();
}

function releasePortalSafetyLease(token: string): boolean {
  const lease = portalSafetyLeases.get(token);
  if (!lease) return false;
  portalSafetyLeases.delete(token);
  clearInterval(lease.heartbeat);
  if (lease.expiry) clearTimeout(lease.expiry);
  try {
    return lease.release();
  } catch (error) {
    // The map entry and timers must still be retired. Leaving an owned lock
    // file behind fails closed and the stale-lock recovery can reclaim it.
    console.error(`[Portal] safety lease cleanup failed: ${error instanceof Error ? error.message : String(error)}`);
    return false;
  }
}

function renewPortalSafetyLease(token: string): boolean {
  const lease = portalSafetyLeases.get(token);
  if (!lease) return false;
  try {
    // Renewal extends only a lease that still owns the underlying file lock.
    // A syntactically valid token must never manufacture ownership after the
    // lock file was replaced or the lease was already retired.
    if (!lease.release.refresh()) {
      releasePortalSafetyLease(token);
      return false;
    }
  } catch {
    releasePortalSafetyLease(token);
    return false;
  }
  lease.lastRenewedAt = Date.now();
  lease.resumeGraceDeadlineAt = null;
  schedulePortalSafetyLeaseExpiry(token, lease);
  return true;
}

async function acquirePortalSafetyLease(): Promise<{
  token: string;
  metadata: Record<string, any>;
  fingerprint: string;
}> {
  let release: OwnedFileLockRelease;
  try {
    release = await acquireOwnedFileLock(PORTAL_LOCK_FILE, {
      label: 'portal safety operation',
      attempts: 150,
      retryMs: 20,
      staleAfterMs: 15_000,
    });
  } catch (error) {
    if (error instanceof Error && /잠금을 .* 안에 획득하지 못했습니다/.test(error.message)) {
      throw new PortalSafetyLeaseRequestError(
        409,
        'PORTAL_SAFETY_LEASE_BUSY',
        '다른 포털 안전 작업이 진행 중입니다. 잠시 후 다시 시도하세요.',
      );
    }
    throw error;
  }
  const token = randomBytes(32).toString('hex');
  try {
    const portal = readPortalJson(PORTAL_DATA_FILE);
    const metadata = preservePortalLocalMetadata({}, authoritativePortalLocalMetadata(portal));
    const heartbeat = setInterval(() => {
      try {
        if (!release.refresh()) releasePortalSafetyLease(token);
      } catch {
        releasePortalSafetyLease(token);
      }
    }, 4_000);
    heartbeat.unref?.();
    const lease: ActivePortalSafetyLease = {
      release,
      heartbeat,
      expiry: null,
      lastRenewedAt: Date.now(),
      resumeGraceDeadlineAt: null,
    };
    portalSafetyLeases.set(token, lease);
    schedulePortalSafetyLeaseExpiry(token, lease);
    return {
      token,
      metadata,
      fingerprint: portalLocalMetadataFingerprint(metadata),
    };
  } catch (error) {
    try {
      release();
    } catch (cleanupError) {
      console.error(`[Portal] failed safety lease acquisition cleanup: ${cleanupError instanceof Error ? cleanupError.message : String(cleanupError)}`);
    }
    throw error;
  }
}

function portalDataFileSignature(): string | null {
  try {
    const stats = statSync(PORTAL_DATA_FILE);
    return `${stats.dev}:${stats.ino}:${stats.size}:${stats.mtimeMs}:${stats.ctimeMs}`;
  } catch {
    return null;
  }
}

const PROJECT_MEMORY_MENTION_ALIASES_FILE = join(APP_DATA_DIR, "project-memory-mention-aliases.json");
const projectMemoryMentionAliases = new MentionAliasRegistry(PROJECT_MEMORY_MENTION_ALIASES_FILE);

function projectMemoryAgent(value: unknown): ProjectMemoryAgent {
  if (value === "hermes") {
    throw new ProjectMemoryError("Hermes는 장기기억 업데이트 모델이 아닙니다.", "PROJECT_MEMORY_AGENT_UNSUPPORTED");
  }
  return value === "codex" ? "codex" : "claude";
}

function sharedMentionClient(): any | null {
  try {
    const portal = JSON.parse(readFileSync(PORTAL_DATA_FILE, "utf8")) as { supabaseUrl?: string };
    const serviceRoleKey = loadServiceRoleKey(APP_DATA_DIR);
    if (!portal.supabaseUrl || !serviceRoleKey) return null;
    const supabaseUrl = normalizeServerSupabaseUrl(portal.supabaseUrl);
    return createClient(supabaseUrl, serviceRoleKey, { auth: { persistSession: false, autoRefreshToken: false } });
  } catch {
    return null;
  }
}

async function persistPortalDeployUrl(value: unknown): Promise<string> {
  const portalDeployUrl = normalizeVercelPortalDeployUrl(value);
  if (!portalDeployUrl) throw new Error('Vercel이 발급한 HTTPS 배포 주소를 검증하지 못했습니다.');
  return withPortalFileLock(() => {
    const current = existsSync(PORTAL_DATA_FILE)
      ? JSON.parse(readFileSync(PORTAL_DATA_FILE, 'utf8')) as Record<string, unknown>
      : {};
    const safe = preservePortalLocalMetadata(
      { ...current, portalDeployUrl },
      authoritativePortalLocalMetadata(current),
    );
    writePortalJsonAtomic(PORTAL_DATA_FILE, safe);
    storedPortalOriginCache = {
      checkedAt: Date.now(),
      loadedAt: Date.now(),
      signature: portalDataFileSignature(),
      value: portalDeployUrl,
    };
    return portalDeployUrl;
  });
}

function storedPortalIntegrationOrigin(): string | null {
  const now = Date.now();
  if (storedPortalOriginCache && now - storedPortalOriginCache.checkedAt < PORTAL_ORIGIN_CACHE_RECHECK_MS) {
    return storedPortalOriginCache.value;
  }
  try {
    const signature = portalDataFileSignature();
    if (!signature) {
      storedPortalOriginCache = { checkedAt: now, loadedAt: now, signature: null, value: null };
      return null;
    }
    if (
      storedPortalOriginCache
      && storedPortalOriginCache.signature === signature
      && now - storedPortalOriginCache.loadedAt < PORTAL_ORIGIN_CACHE_MAX_REUSE_MS
    ) {
      storedPortalOriginCache.checkedAt = now;
      return storedPortalOriginCache.value;
    }
    const portal = JSON.parse(readFileSync(PORTAL_DATA_FILE, 'utf8')) as Record<string, unknown>;
    const value = normalizeVercelPortalDeployUrl(portal.portalDeployUrl);
    storedPortalOriginCache = { checkedAt: now, loadedAt: now, signature, value };
    return value;
  } catch {
    storedPortalOriginCache = { checkedAt: now, loadedAt: now, signature: portalDataFileSignature(), value: null };
    return null;
  }
}

let onboardingProgressStore: OnboardingProgressStore | undefined;
let onboardingGithubHost: OnboardingGithubHost | undefined;
let onboardingCodexLoginHost: CodexLoginHost | undefined;
let onboardingCodexHost: CodexInstallHost | undefined;
const ONBOARDING_TOOLS_CACHE_TTL_MS = 30_000;
let onboardingToolsCache: { expiresAt: number; value: OnboardingToolsResponse } | null = null;
let onboardingToolsInFlight: Promise<OnboardingToolsResponse> | null = null;

function onboardingPlatform(): OnboardingPlatform {
  return process.platform === 'win32' ? 'windows' : process.platform === 'darwin' ? 'mac' : 'linux';
}

function compactProbeOutput(value: string): string {
  return value
    .replace(/[\r\n]+/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()
    .slice(0, 120);
}

function compactVersionLabel(value: string): string | undefined {
  if (!value) return undefined;
  // CLI stdout는 사용자 환경의 플러그인이 덧붙일 수 있으므로 그대로 UI/API에 싣지 않는다.
  // 제품명·경로·경고문 대신 기계적으로 안전한 버전 토큰 하나만 반환한다.
  return value.match(/\bv?\d+(?:\.\d+){1,3}(?:[-+][A-Za-z0-9.-]+)?\b/i)?.[0];
}

function resolveLocalExecutable(command: string, candidates: string[] = []): string | null {
  const direct = candidates.find(candidate => candidate && existsSync(candidate));
  if (direct) return direct;
  try {
    const result = Bun.spawnSync(IS_WIN ? ['where', command] : ['which', command], {
      stdout: 'pipe', stderr: 'pipe', timeout: 2_000,
    });
    const found = result.exitCode === 0
      ? result.stdout.toString().trim().split(/\r?\n/)[0]?.trim()
      : '';
    return found || null;
  } catch {
    return null;
  }
}

function runOnboardingProbeAsync(executable: string, args: string[], timeout = 2_500): Promise<{ ok: boolean; output: string; timedOut: boolean }> {
  const wrapped = IS_WIN && /\.(cmd|bat)$/i.test(executable);
  const command = wrapped ? 'cmd.exe' : executable;
  const commandArgs = wrapped ? ['/d', '/s', '/c', executable, ...args] : args;
  return new Promise(resolveProbe => {
    nodeExecFile(command, commandArgs, {
      encoding: 'utf8',
      cwd: '/',
      timeout,
      windowsHide: true,
      maxBuffer: 128 * 1024,
    }, (error: NodeJS.ErrnoException & { killed?: boolean; signal?: string } | null, stdout: string, stderr: string) => {
      const output = compactProbeOutput(`${stdout ?? ''} ${stderr ?? ''}`);
      if (!error) return resolveProbe({ ok: true, output, timedOut: false });
      const timedOut = error.killed === true || error.signal === 'SIGTERM';
      resolveProbe({ ok: false, output: output || compactProbeOutput(error.message), timedOut });
    });
  });
}

async function executableDiagnosticAsync(
  id: OnboardingToolId,
  executable: string | null,
  versionArgs: string[] = ['--version'],
): Promise<OnboardingToolDiagnostic> {
  if (!executable) return { id, state: 'missing', installed: false };
  const probe = await runOnboardingProbeAsync(executable, versionArgs, 2_000);
  if (probe.ok) return { id, state: 'ready', installed: true, version: compactVersionLabel(probe.output) };
  return {
    id, state: 'unknown', installed: true,
    detail: probe.timedOut
      ? '실행 파일은 찾았지만 버전 확인 시간이 초과됐습니다.'
      : '실행 파일은 찾았지만 현재 터미널에서 버전을 확인하지 못했습니다.',
  };
}

function resolveNodeGlobalCli(name: string): string | null {
  const home = homedir();
  return resolveLocalExecutable(name, IS_WIN ? [
    join(process.env.APPDATA ?? '', 'npm', `${name}.cmd`),
    join(home, '.bun', 'bin', `${name}.exe`),
    join(home, '.bun', 'bin', `${name}.cmd`),
  ] : [
    join(home, '.bun', 'bin', name),
    join(home, '.npm-global', 'bin', name),
    `/opt/homebrew/bin/${name}`,
    `/usr/local/bin/${name}`,
  ]);
}

function isPackagedOnboardingRuntime(): boolean {
  // Bun standalone binaries expose modules through /$bunfs/root. The executable
  // name check covers packaged Tauri resources even if Bun changes that virtual path.
  const normalizedModuleDir = import.meta.dir.replaceAll('\\', '/');
  return normalizedModuleDir.includes('/$bunfs/')
    || /^agentstoz-api-sidecar(?:\.exe)?$/i.test(basename(process.execPath));
}

async function authenticatedCliDiagnosticAsync(
  id: OnboardingToolId,
  executable: string | null,
  authArgs: string[],
): Promise<OnboardingToolDiagnostic> {
  if (!executable) return { id, state: 'missing', installed: false };
  const [version, auth] = await Promise.all([
    runOnboardingProbeAsync(executable, ['--version'], 2_000),
    runOnboardingProbeAsync(executable, authArgs, 3_000),
  ]);
  return { id, installed: true, version: compactVersionLabel(version.output), ...classifyOnboardingAuth(auth) };
}

async function buildOnboardingToolsDiagnostics(): Promise<OnboardingToolsResponse> {
  const platform = onboardingPlatform();
  const home = homedir();
  const diagnostics: OnboardingToolDiagnostic[] = [];
  diagnostics.push({ id: 'bun', state: 'ready', installed: true, version: `bun ${Bun.version}` });
  diagnostics.push(await executableDiagnosticAsync('git', resolveLocalExecutable('git', [GIT_PATH])));

  if (isPackagedOnboardingRuntime()) {
    diagnostics.push({
      id: 'dependencies',
      state: 'ready',
      installed: true,
      detail: '설치된 앱에 필요한 구성요소가 이미 포함되어 있습니다.',
    });
  } else {
    // Source diagnostics are anchored to this module, never the caller's cwd.
    // That prevents a dashboard opened from another folder from recommending
    // `bun install` against an unrelated package.json.
    const dependenciesReady = existsSync(join(import.meta.dir, 'node_modules', 'react'));
    diagnostics.push({
      id: 'dependencies',
      state: dependenciesReady ? 'ready' : 'missing',
      installed: dependenciesReady,
      detail: dependenciesReady
        ? '현재 AgentsToZ_byCS checkout의 앱 구성요소를 찾았습니다.'
        : 'AgentsToZ_byCS 소스 저장소 최상위에서만 bun install을 실행하세요.',
    });
  }
  diagnostics.push({ id: 'api', state: 'ready', installed: true, detail: '로컬 AgentsToZ API 응답 중' });

  let supabasePath: string | null = null;
  try { supabasePath = resolveSupabaseCli(); } catch { supabasePath = null; }
  diagnostics.push(...await Promise.all([
    authenticatedCliDiagnosticAsync('supabase', supabasePath, ['projects', 'list']),
    process.platform === 'darwin'
      ? createGithubHostEffects(APP_DATA_DIR).probe().then((result): OnboardingToolDiagnostic => ({
        id: 'github', installed: result !== 'missing',
        state: result === 'installed' ? 'needs-login' : result === 'storage-review' ? 'unknown' : result,
        authenticated: result === 'ready' ? true : result === 'installed' ? false : undefined,
        detail: result === 'storage-review' ? '로그인 정보가 일반 파일에 저장되어 있습니다. 키체인 저장 방식을 확인해 주세요.' : undefined,
      }))
      : authenticatedCliDiagnosticAsync('github', resolveGitHubCliPath(), ['auth', 'status']),
    authenticatedCliDiagnosticAsync('vercel', resolveNodeGlobalCli('vercel'), ['whoami']),
  ]));

  const agentExecutables = (['claude', 'codex', 'antigravity'] as const).map(id => {
    const agentName = id === 'antigravity' ? 'agy' : id;
    const resolved = resolveAgentBin(agentName);
    const executable = resolved === agentName ? resolveLocalExecutable(agentName) : resolved;
    return { id, executable };
  });
  const optionalAgentDiagnostics = await Promise.all([
    ...agentExecutables.map(async ({ id, executable }) => {
      const version = await executableDiagnosticAsync(id, executable);
      if(id !== 'codex' || !executable || version.state !== 'ready') return version;
      const login = diagnoseCodexLogin(await runOnboardingProbeAsync(executable, ['login','status'], 3000));
      return {...version,...login};
    }),
    executableDiagnosticAsync('hermes', hermesCliPath()),
  ]);
  diagnostics.push(...optionalAgentDiagnostics.map(diagnostic => (
    diagnostic.id === 'hermes' && diagnostic.state === 'ready'
      ? { ...diagnostic, detail: 'Hermes CLI 설치를 확인했습니다. profile·gateway·Telegram 연결은 개별 연동 화면에서 따로 확인하세요.' }
      : diagnostic
  )));

  const buzzCli = resolveBuzzCliPath();
  diagnostics.push(buzzCli
    ? { id: 'buzz', state: 'ready', installed: true, detail: 'Buzz CLI를 찾았습니다.' }
    : { id: 'buzz', state: 'manual', detail: 'Buzz 앱은 사용할 때 공식 릴리스에서 설치하고 앱 안에서 연결을 확인합니다.' });
  diagnostics.push({ id: 'telegram', state: 'manual', detail: '로컬 설치 항목이 아닙니다. Hermes를 쓸 때 BotFather에서 연결합니다.' });

  diagnostics.push(await executableDiagnosticAsync('rust', resolveLocalExecutable('cargo', [
    join(home, '.cargo', 'bin', IS_WIN ? 'cargo.exe' : 'cargo'),
  ])));
  diagnostics.push(platform === 'windows'
    ? {
        id: 'windows-build-tools',
        state: hasVsBuildTools() ? 'ready' : 'missing',
        installed: hasVsBuildTools(),
        detail: hasVsBuildTools() ? 'MSVC toolchain을 찾았습니다.' : '앱 사용에는 필요 없고 Windows 설치파일을 직접 빌드할 때만 필요합니다.',
      }
    : { id: 'windows-build-tools', state: 'not-applicable' });
  diagnostics.push(platform === 'linux'
    ? await executableDiagnosticAsync('curl', resolveLocalExecutable('curl', ['/usr/bin/curl']))
    : { id: 'curl', state: 'not-applicable' });
  diagnostics.push(platform === 'linux'
    ? await executableDiagnosticAsync('python', resolveLocalExecutable('python3', ['/usr/bin/python3']), ['--version'])
    : { id: 'python', state: 'not-applicable' });

  return {
    platform,
    checkedAt: new Date().toISOString(),
    cacheTtlMs: ONBOARDING_TOOLS_CACHE_TTL_MS,
    diagnostics,
  };
}

async function onboardingToolsStatus(force = false): Promise<OnboardingToolsResponse> {
  if (!force && onboardingToolsCache && onboardingToolsCache.expiresAt > Date.now()) {
    return onboardingToolsCache.value;
  }
  if (force && onboardingToolsInFlight) {
    // Keep probes bounded to one batch, then perform the explicitly requested
    // fresh scan instead of returning the batch that began before installation.
    await onboardingToolsInFlight.catch(() => undefined);
  }
  if (force) {
    onboardingToolsCache = null;
    // resolveAgentBin intentionally caches normal launch paths. Diagnostics
    // refresh is the one place where a just-installed CLI must be rediscovered.
    AGENT_BIN_CACHE.clear();
  }
  if (onboardingToolsInFlight) return onboardingToolsInFlight;
  const task = buildOnboardingToolsDiagnostics();
  onboardingToolsInFlight = task;
  try {
    const value = await task;
    onboardingToolsCache = { expiresAt: Date.now() + ONBOARDING_TOOLS_CACHE_TTL_MS, value };
    return value;
  } finally {
    if (onboardingToolsInFlight === task) onboardingToolsInFlight = null;
  }
}

async function sharedMentionRows(): Promise<Array<{ alias: string; memory_id: string; status: "primary" | "redirect"; updated_at: string }> | null> {
  const client = sharedMentionClient();
  if (!client) return null;
  const { data, error } = await client.from("portmgr_project_memory_mentions")
    .select("alias,memory_id,status,updated_at");
  if (error) throw error;
  return (data ?? []) as Array<{ alias: string; memory_id: string; status: "primary" | "redirect"; updated_at: string }>;
}

/**
 * 공식 VOC 수집 프로젝트의 service_role이 실제로 동작하는 이 로컬 sidecar만
 * 무제한 운영자 전송을 허용한다. GitHub URL·기기명·Vercel 호스트명은 인증 근거로
 * 쓰지 않으며, 키 자체는 브라우저 응답에 절대 포함하지 않는다.
 */
async function verifiedLocalVocAdminKey(): Promise<string | null> {
  const serviceRoleKey = loadServiceRoleKey(APP_DATA_DIR);
  if (!serviceRoleKey || !existsSync(PORTAL_DATA_FILE)) return null;
  try {
    const portal = JSON.parse(readFileSync(PORTAL_DATA_FILE, "utf8")) as { supabaseUrl?: unknown };
    const portalSupabaseUrl = typeof portal.supabaseUrl === "string" ? portal.supabaseUrl.trim() : "";
    const verified = await verifyVocAdminContext({ portalSupabaseUrl, serviceRoleKey });
    return verified ? serviceRoleKey : null;
  } catch {
    return null;
  }
}
