async function acquireAgentRuntimeWorkspaceLeaseForTarget(
  target: { targetId: string; cwd: string },
): Promise<AgentRuntimeWorkspaceLease | null> {
  const beforeLease = await captureAgentRuntimeLeasedTargetIdentity(target.targetId, target.cwd);
  let lease: WorkspaceLease | null = null;
  try {
    lease = await acquireManagedWorkspaceLease(target.cwd);
    const afterLease = await captureAgentRuntimeLeasedTargetIdentity(target.targetId, target.cwd);
    if (!sameAgentRuntimeLeasedTargetIdentity(beforeLease, afterLease)
      || !agentRuntimeWorkspaceLeaseMatchesIdentity(lease, afterLease)) {
      throw new AgentRuntimeHttpError(
        'AGENT_RUNTIME_TARGET_STATUS_UNKNOWN',
        '프로젝트 작업 대상이 잠금 중 변경되어 작업을 시작하지 않습니다.',
        503,
      );
    }
    const leasedIdentity = afterLease;
    const ownedLease = lease;
    return {
      release: () => releaseManagedWorkspaceLease(ownedLease, `agent runtime ${target.targetId}`),
      revalidate: async () => {
        const current = await captureAgentRuntimeLeasedTargetIdentity(target.targetId, target.cwd);
        return sameAgentRuntimeLeasedTargetIdentity(leasedIdentity, current)
          && agentRuntimeWorkspaceLeaseMatchesIdentity(ownedLease, current);
      },
    };
  } catch (error) {
    if (lease) {
      const released = releaseManagedWorkspaceLease(
        lease,
        `agent runtime ${target.targetId} rejected start`,
      );
      lease = null;
      if (!released) {
        throw new AgentRuntimeHttpError(
          'AGENT_RUNTIME_TARGET_STATUS_UNKNOWN',
          '프로젝트 작업 잠금을 안전하게 해제하지 못했습니다.',
          503,
        );
      }
    }
    if (error instanceof WorkspaceLeaseError && error.code === 'WORKSPACE_LEASE_BUSY') {
      return null;
    }
    throw error;
  }
}

