const terminalMemoryQueue = new TerminalMemoryQueue(join(APP_DATA_DIR,'workroom-memory-queue.json'),async job=>{
  if(!codexAutoRememberCoordinator.settings().enabled)return 'pending';
  const sessions=await aiTerminalService.perform({operation:'list',requestId:crypto.randomUUID()});
  if(sessions.sessions?.some(session=>session.id===job.sessionId && session.state==='running'))return 'pending';
  const target=await resolveAgentRuntimeRegisteredTarget(job.targetId);
  if(realpathSync(target.cwd)!==job.cwd)throw new Error('프로젝트 경로가 변경되었습니다.');
  // A pending Workroom job is revisited every three seconds. Full synchronous
  // document/activity detection for every registered alias stalls all PTYs.
  // V2-owned work can wait after an identity-only read; legacy saves use the
  // same bounded asynchronous resolver and under-lease revalidation as checkpoints.
  const identity=await detectProjectMemoryIdentity(target.cwd);
  if(!identity.exists||!identity.config)return 'unavailable';
  if(memoryAutomaticHost.owns(identity.config.memoryId))return 'pending';
  const resolver=await prepareCodexAutoRememberProjectResolver();
  const project=await resolver({sessionId:job.sessionId,cwd:job.cwd,usedPercent:0,
    capturedAt:new Date().toISOString(),turnState:'unknown',turnId:null,turnCompletedAt:null});
  if(!project)return 'unavailable';
  return withScheduledMemorySave(project.projectRoot,'workroom','Workroom session-end checkpoint',async signal=>{
    if(!codexAutoRememberCoordinator.settings().enabled)return 'pending';
    const latestTarget=await resolveAgentRuntimeRegisteredTarget(job.targetId);
    if(realpathSync(latestTarget.cwd)!==job.cwd)throw new Error('프로젝트 경로가 변경되었습니다.');
    if(!await project.validateRegistration?.())throw new Error('프로젝트 장기기억 연결이 변경되었습니다.');
    const current=detectProjectMemory(project.projectRoot);
    if(!current.exists||!current.config)return 'unavailable';
    if(memoryAutomaticHost.owns(current.config.memoryId))return 'pending';
    if(!current.activity.needsRemember)return 'unchanged';
    await bestEffortWhatISaidCapture(project.projectRoot);
    if(!codexAutoRememberCoordinator.settings().enabled)return 'pending';
    const result=await sessionEndProjectMemory({ sessionStore: memorySessionStore,portalDataFile:PORTAL_DATA_FILE,folderPath:project.projectRoot,
      projectName:project.projectName,agent:job.agent==='claude'?'claude':'codex',autoBackup:current.config.autoBackup!==false,preservePreferredAgent:true,
      workroomJob: job, signal, onLocalSaved:()=>terminalMemoryQueue.recordRecoveredLocalSave(job,current.config!.autoBackup!==false)});
    if(!result.localSaved)throw new Error('로컬 세션 저장이 확인되지 않았습니다.');
    queueEnabledProjectMemoryPrivateGitHubArchive(project.projectRoot);
    return result.backupError?'backup-pending':'saved';
  });
});
