let agentRuntimeHttpService: AgentRuntimeHttpService = unavailableAgentRuntimeHttpService;
let agentRuntimeSupervisorRelease: OwnedFileLockRelease | null = null;
try {
  if (!agentRuntimeGuardRegistry || !agentRuntimeGuardLaunchers) {
    throw new Error('Durable Agent Runtime process ownership is unavailable.');
  }
  // One sidecar process exclusively owns reconciliation and task execution.
  // PID liveness in acquireOwnedFileLock prevents a sleeping/live process from
  // losing this lease; the long stale window prefers temporary unavailability
  // over two supervisors after an ambiguous crash/restart boundary.
  agentRuntimeSupervisorRelease = await acquireAgentRuntimeSupervisor({
    appDataDir: APP_DATA_DIR,
    registry: agentRuntimeGuardRegistry,
  });
  agentRuntimeJournal = openAgentRuntimeTaskJournal(
    join(APP_DATA_DIR, 'agent-runtime', 'tasks-v1.sqlite'),
  );
  agentRuntimeService = createAgentRuntimeService({
    journal: agentRuntimeJournal,
    resolveTarget: resolveAgentRuntimeRegisteredTarget,
    resolveRuntime: resolveVerifiedAgentRuntime,
    managedExecutionEnabled: AGENT_RUNTIME_MANAGED_EXECUTION_ENABLED
      || AGENT_RUNTIME_LOCAL_DEVELOPMENT_TEST_MODE,
    dangerousModeEnabled: AGENT_RUNTIME_DANGEROUS_MODE_ENABLED
      || AGENT_RUNTIME_LOCAL_DEVELOPMENT_TEST_MODE,
    acquireWorkspaceLease: acquireAgentRuntimeWorkspaceLeaseForTarget,
    // The adapter confirms only its registered task PGID is gone. This is
    // useful lifecycle bookkeeping but cannot prove a setsid/detached child is
    // absent; the production execution gate therefore remains closed.
    runCodex: input => runCodexAgentTask(input, {
      spawn: agentRuntimeGuardLaunchers!.spawnCodex,
      dangerousModeEnabled: AGENT_RUNTIME_DANGEROUS_MODE_ENABLED
        || AGENT_RUNTIME_LOCAL_DEVELOPMENT_TEST_MODE,
    }),
    resolutionTimeoutMs: 12_000,
  });
  agentRuntimeConversationJournal = openAgentRuntimeConversationJournal(
    join(APP_DATA_DIR, 'agent-runtime', 'conversations-v1.sqlite'),
  );
  agentRuntimeConversationService = new AgentRuntimeConversationService({
    journal: agentRuntimeConversationJournal,
    onTurnSettled: projectRoot => scheduleWhatISaidCaptureFollowUp(projectRoot),
    resolveTarget: resolveAgentRuntimeRegisteredTarget,
    resolveRuntime: resolveReadOnlyVerifiedAgentRuntime,
    executionEnabled: AGENT_RUNTIME_READ_ONLY_CONVERSATIONS_ENABLED,
    executionMode: 'read-only',
    acquireWorkspaceLease: acquireAgentRuntimeWorkspaceLeaseForTarget,
    runCodexConversation: input => runCodexConversationTurn(input, {
      spawn: agentRuntimeGuardLaunchers!.spawnCodex,
    }),
    inspectCodexConversation: input => inspectCodexConversation(input, {
      spawn: agentRuntimeGuardLaunchers!.spawnCodex,
    }),
    mutateCodexConversation: input => mutateCodexConversation(input, {
      spawn: agentRuntimeGuardLaunchers!.spawnCodex,
    }),
    readCodexConversationHistory: input => readCodexConversationHistory(input, {
      spawn: agentRuntimeGuardLaunchers!.spawnCodex,
    }),
  });
  const readyAgentRuntimeService = agentRuntimeService;
  const readyConversationService = agentRuntimeConversationService;
  agentRuntimeHttpService = {
    capabilities: () => readyAgentRuntimeService.capabilities(),
    conversationCapabilities: readOnlyAgentRuntimeConversationCapabilities,
    readiness: () => inspectAgentRuntimeReadiness({
      inspectCodexAdapter: inspectCodexAdapterForReadiness,
      supervisorState: agentRuntimeStartupState,
    }),
    targets: listAgentRuntimeTargets,
    listTasks: () => readyAgentRuntimeService.listTasks(),
    readEvents: (taskId, after) => readyAgentRuntimeService.readEvents(taskId, after),
    startTask: request => readyAgentRuntimeService.startTask(request),
    cancelTask: (taskId, request) => readyAgentRuntimeService.cancelTask(taskId, request),
    conversations: readyConversationService,
  };
  agentRuntimeStartupState = 'ready';
} catch (error) {
  agentRuntimeStartupState = agentRuntimeStartupFailure(error);
  try { agentRuntimeConversationJournal?.close(); } catch { /* preserve the initialization error */ }
  agentRuntimeConversationJournal = null;
  agentRuntimeConversationService = null;
  try { agentRuntimeJournal?.close(); } catch { /* preserve the initialization error */ }
  agentRuntimeJournal = null;
  agentRuntimeService = null;
  try {
    if (agentRuntimeSupervisorRelease?.()) agentRuntimeSupervisorRelease = null;
  } catch { /* preserve the initialization error */ }
  console.error(
    '[AgentRuntime] local runtime initialization failed:',
    error instanceof Error ? error.message : 'unknown error',
  );
}

async function resolveRemoteControlTaskTargetAuthorities(
  bindings: readonly RemoteControlTaskTargetBinding[],
): Promise<readonly RemoteControlTaskTargetAuthority[]> {
  const inventory = await loadAgentRuntimeTargetInventory();
  const runtimeDirectories = inventory.targets.map(target => ({
    target,
    directory: registeredDiscoveryDirectoryState(target.cwd),
  }));
  const authorities: RemoteControlTaskTargetAuthority[] = [];
  for (const binding of bindings) {
    const requestedPath = binding.target.worktreePath || binding.target.folderPath || '';
    const requested = registeredDiscoveryDirectoryState(requestedPath);
    if (requested.status === 'unknown') {
      throw new RemoteControlTaskGatewayError(
        'REMOTE_CONTROL_TASK_TARGET_STATUS_UNKNOWN',
        '프로젝트 실행 대상을 안전하게 확인하지 못했습니다.',
        true,
      );
    }
    if (requested.status !== 'found') continue;
    const matches = runtimeDirectories.filter(candidate => (
      candidate.directory.status === 'found'
      && sameRegisteredDirectory(requested, candidate.directory)
    ));
    if (matches.length > 1 || (matches.length === 0 && !inventory.complete)) {
      throw new RemoteControlTaskGatewayError(
        'REMOTE_CONTROL_TASK_TARGET_STATUS_UNKNOWN',
        '프로젝트 실행 대상을 안전하게 확인하지 못했습니다.',
        true,
      );
    }
    if (matches.length === 1) {
      authorities.push({
        controlId: binding.controlId,
        runtimeTargetId: matches[0]!.target.targetId,
      });
    }
  }
  return authorities;
}

// Remote development testing shares only the already-gated runtime service.
// The remote gateway itself forces workspace-write and rejects dangerous task
// history, so the source app can exercise the phone-to-Mac flow without ever
// forwarding the local full-access choice. Packaged builds still receive the
// unavailable service until their independent containment flag opens.
async function resolveMobileDeviceConsent(owner:string,authorities:readonly {controlId:string;runtimeTargetId:string}[],bindings:readonly RemoteControlTaskTargetBinding[]) {
  const binding=remoteTerminalBinding(owner);if(!binding)return null;
  const grant=await remoteTerminalGrantStore.find(binding.hostId,binding.controllerId);
  if(!remoteTerminalGrantValid(grant,binding))return null;
  const targetIds=new Set<string>();
  const checkedRoots:{workspaceRootId:string;path:string;identityHash:string}[]=[];
  const roots=grant.scope.kind==='controller-created-projects'?await agentsToZUseWorkspaceRoots():[];
  for(const authority of authorities){
    if(grant.scope.kind==='targets'){
      if(remoteTerminalGrantAllowsTarget(grant,authority.runtimeTargetId))targetIds.add(authority.runtimeTargetId);
      continue;
    }
    const target=bindings.find(b=>b.controlId===authority.controlId)?.target;
    const path=target?.worktreePath||target?.folderPath;if(!target||!path)continue;
    const root=roots.find(r=>r.path===dirname(realpathSync(path)));if(!root)continue;
    const identityHash=remoteTerminalWorkspaceRootIdentity(root.path);
    if(!remoteTerminalGrantAllowsTarget(grant,authority.runtimeTargetId,{controllerId:binding.controllerId,workspaceRootId:root.workspaceRootId,identityHash,registered:true}))continue;
    const receipt=await remoteProjectCreateReceipts.findCreatedProject({controllerId:binding.controllerId,projectId:target.internalId,workspaceRootId:root.workspaceRootId,rootIdentityHash:identityHash});
    if(!receipt||receipt.projectIdentityHash!==remoteTerminalWorkspaceRootIdentity(path))continue;
    targetIds.add(authority.runtimeTargetId);checkedRoots.push({workspaceRootId:root.workspaceRootId,path:root.path,identityHash});
  }
  return {targetIds,workspaceScopes:grant.workspaceScopes??[],requestOwner:`device:${binding.hostId}:${binding.controllerId}`,isActive:()=>{
    const currentBinding=remoteTerminalBinding(owner);if(!currentBinding||currentBinding.controllerId!==binding.controllerId)return false;
    const current=remoteTerminalGrantStore.current(binding.hostId,binding.controllerId);
    return remoteTerminalGrantValid(current,currentBinding)&&current.revision===grant.revision&&checkedRoots.every(root=>{try{const rows=JSON.parse(readFileSync(WORKSPACE_ROOTS_FILE,'utf8'));const row=Array.isArray(rows)?rows.find((r:any)=>r.id===root.workspaceRootId):null;return typeof row?.path==='string'&&realpathSync(row.path)===root.path&&remoteTerminalWorkspaceRootIdentity(root.path)===root.identityHash}catch{return false}});
  }};
}
