async function performMobileWorkspace(request:MobileWorkspaceRequest,targetId:string,owner:string,active:()=>boolean):Promise<MobileWorkspaceResult> {
  const action=request.workspace.action;
  const target=await resolveAiTerminalRegisteredTarget(targetId);
  const path=realpathSync(target.cwd);
  const directory=registeredDiscoveryDirectoryState(path);
  if(directory.status!=='found')throw new Error('프로젝트 경로를 확인하세요.');
  const validate=async(requireConnection=true)=>{
    const current=await resolveAiTerminalRegisteredTarget(targetId);
    const currentDirectory=registeredDiscoveryDirectoryState(current.cwd);
    if((requireConnection&&!active())||realpathSync(current.cwd)!==path||currentDirectory.status!=='found'||!sameRegisteredDirectory(directory,currentDirectory))throw new Error('프로젝트 또는 모바일 권한이 변경되었습니다.');
  };
  await validate();
  if(action==='worktree.review'||action==='worktree.remove'){
    return withManagedWorkspaceLease(path,'mobile worktree cleanup',async()=>{await validate();return {kind:'workspace',action,cleanup:action==='worktree.review'?await mobileWorktreeCleanup.review(owner,targetId,path):await mobileWorktreeCleanup.remove(owner,targetId,path,request.workspace.reviewToken!)};});
  }
  if(action==='said.list'||action==='said.read'){
    const page=await listRegisteredWhatISaid({folderPath:path,query:request.workspace.query,beforeSeq:request.workspace.beforeSeq,limit:3});
    await validate();
    const entries=action==='said.read'?page.items.filter(item=>item.id===request.workspace.recordId):page.items;
    if(action==='said.read'&&entries.length!==1)throw new Error('발언이 변경되었거나 삭제되었습니다. 목록을 새로고침하세요.');
    let nextOffset:number|null=null;
    const records=entries.map(item=>{
      const textHash=createHash('sha256').update(item.text).digest('hex');
      if(action==='said.read'&&textHash!==request.workspace.textHash)throw new Error('발언 내용이 변경되었습니다. 목록을 새로고침하세요.');
      const characters=Array.from(item.text),offset=action==='said.read'?request.workspace.offset!:0,limit=action==='said.read'?1500:500;
      if(action==='said.read'&&offset>characters.length)throw new Error('발언 읽기 위치를 확인하세요.');
      const truncated=characters.length>offset+limit;
      if(action==='said.read')nextOffset=truncated?offset+limit:null;
      return {id:item.id,text:characters.slice(offset,offset+limit).join(''),truncated,textHash,recordedAt:item.recordedAt,agent:item.agent,deviceName:item.deviceName??null,origin:item.promptOrigin};
    });
    return {kind:'workspace',action,source:page.source,hasMore:page.hasMore,nextBeforeSeq:page.nextBeforeSeq,captureAt:page.capture?.lastCaptureAt??null,scanComplete:page.scan?.complete??true,records,...(action==='said.read'?{nextOffset}:{})};
  }
  if(action==='memory.status')return {kind:'workspace',action,memory:mobileWorkspaceJobs.status(owner,targetId)};
  if(action==='memory.save'){
    const memory=await mobileWorkspaceJobs.start(owner,targetId,request.requestId,async()=>{
      // The authorized admission owns the accepted job. Losing the browser
      // connection must not cancel it; project identity still needs revalidation.
      await validate(false);
      return withScheduledMemorySave(path,'manual','mobile session-end',async(signal,lease)=>{
        await validate(false);
        const current=detectProjectMemory(path);
        if(!current.exists||!current.config)throw new Error('장기기억 초기화가 필요합니다.');
        const v2=await runAutomaticMemoryForManualPath(path,lease,signal);
        if(v2)return {state:v2.localSaved?'saved':v2.state,localSaved:v2.localSaved,backupSaved:false,message:v2.localSaved?(v2.backupPending?'로컬 저장 완료 · 백업 대기':'로컬 저장 완료 · 백업 상태는 Mac에서 확인하세요.'):'저장 조건을 확인하고 있습니다. Mac의 자동 저장 상태를 확인하세요.'};
        await bestEffortWhatISaidCapture(path);
        const result=await sessionEndProjectMemory({sessionStore:memorySessionStore,signal,portalDataFile:PORTAL_DATA_FILE,folderPath:path,agent:current.config.agent??'codex',autoBackup:current.config.autoBackup!==false,preservePreferredAgent:true});
        if(result.localSaved)queueEnabledProjectMemoryPrivateGitHubArchive(path);
        return {state:result.localSaved?'saved':'recovery-required',localSaved:result.localSaved===true,backupSaved:result.remoteBackedUp===true,message:result.localSaved?(result.remoteBackedUp?'로컬 저장과 백업 완료':result.backupSkipped?'로컬 저장 완료 · 백업 꺼짐':'로컬 저장 완료 · 백업 확인 필요'):'저장되지 않았습니다. Mac에서 기억 충돌·복구 상태를 확인하세요.'};
      });
    });
    return {kind:'workspace',action,memory};
  }
  const supported=IS_BUNDLED_API_SIDECAR&&process.platform==='darwin'&&!remoteControlApiShutdown;
  if(!supported){if(action!=='duty.status')throw new Error('대직은 설치된 macOS 앱에서 사용할 수 있습니다.');return {kind:'workspace',action,supported:false,connections:[]};}
  csDuty??=createLocalCsDuty(APP_DATA_DIR,async id=>{const t=await resolveAgentRuntimeRegisteredTarget(id);const identity=registeredDiscoveryDirectoryState(t.cwd);if(identity.status!=='found')throw Error('프로젝트 경로를 확인하세요.');return JSON.stringify([t.targetId,t.cwd,identity]);},async id=>(await resolveAgentRuntimeRegisteredTarget(id)).cwd);
  const connectionId=request.workspace.connectionId;
  if(action!=='duty.status'){
    if(!connectionId||!csDuty.connections(targetId).some(c=>c.targetId===connectionId))throw new Error('이 프로젝트에 연결된 카톡방이 아닙니다.');
    await validate();
    if(action==='duty.enable')await csDuty.enable(connectionId,request.workspace.revision!,request.workspace.consent,request.workspace.knowledgeRevision);
    else if(action==='duty.disable')csDuty.disable(connectionId);
    else if(action==='duty.diagnose')return {kind:'workspace',action,supported:true,checks:(await csDuty.diagnose(connectionId)).map(c=>({name:c.label,ok:c.ok,detail:c.detail.slice(0,160)}))};
  }
  return {kind:'workspace',action,supported:true,connections:csDuty.connections(targetId).map(c=>{
    const status=csDuty!.status(c.targetId),config=status.config!;
    return {id:c.targetId,title:c.chatTitle,alias:config.projectAlias??'',profile:config.profileLabel,state:status.state,revision:config.revision,knowledgeRevision:status.knowledge.revision,replied:status.replied,checkedAt:status.checkedAt};
  })};
}


